-- Installed as override/M_PSXQD.lua; read by M_PSXQ.lua.
PSXQ_DATA = {
[16202] = { g = [[bg2]], k = [[side]], o = 0, c = [[any]], w = [[None (leftover journal text)]], h = { [[This is the journal's built-in help text, not a real quest.]], [[The star sapphire task for Belt is an old tutorial line that the game never asks you to do.]] }, s = [[Nothing to do. The first entry only explains the journal's four sections: active quests, finished quests, story entries and your own notes.
The second line (retrieve the star sapphire for Belt) is leftover tutorial text with no matching quest in this game. You can ignore it.]] },
[66122] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-7 (or ToB)]], w = [[Watcher's Keep]], h = { [[Brother Odren of the Knights of the Vigil seeks heroes strong enough to reseal an ancient prison.]], [[At the top of the keep, Brother Pol gives the holy symbol and ritual; Garlena sells supplies.]], [[The Imprisoned One is Demogorgon, and Odren meant to leave you sealed inside with him.]] }, s = [[Brother Odren approaches you and asks you to enter Watcher's Keep to repair the seals of its prisoner. If you are too weak he tells you to come back later.
Accept. At the keep, Odren shows you the entrance; get the holy symbol and ritual from Brother Pol, and buy gear from Garlena.
Go down level by level (see the other Watcher's Keep entries) and open the final seal.
The Imprisoned One is Demogorgon. Choices: kill him (hardest fight in the keep); perform the ritual to reseal him and trick him into letting you out; or agree to free him by lying to Odren that the prisoner is dead.
If Odren goes inside, a ghostly knight offers Helm's scroll to seal the prison forever.
Afterwards, confront Odren: forgive him or punish the Knights.]] },
[74295] = { g = [[bg2]], k = [[main]], o = 32, c = [[1-7]], w = [[Athkatla, Brynnlaw, Underdark, Suldanessellar]], h = { [[Escape Irenicus's dungeon, then raise money in Athkatla to buy help in finding Imoen.]], [[Pick a patron: Gaelan Bayle's Shadow Thieves or the vampire Bodhi; both want a large sum of gold.]], [[After your patron ships you to Brynnlaw, get into Spellhold, escape, cross the Underdark and take the Rhynn Lanthorn from Bodhi.]] }, s = [[Chapter 1: free yourself in Irenicus's dungeon, gather gear and leave through the upper levels.
Chapter 2: Gaelan Bayle in the Slums asks for 20,000 gold. Do side quests (the Copper Coronet is a good start) to earn it. Valen offers Bodhi's counter-deal in the Graveyard District.
Chapter 3: pay one side and do its missions: for Aran Linvail, guard Mook's shipment, meet the recruiter at the Five Flagons, then clear the vampires' lair; for Bodhi, intercept the shipment, frame Vulova, rescue Palern Flynn and kill Aran Linvail.
Chapter 4: in Brynnlaw, enter Spellhold (see Getting inside the asylum), then escape the asylum.
Chapter 5: in the Underdark, help Goldander, get disguised by Adalon and recover her eggs in Ust Natha.
Chapter 6: kill Bodhi in her lair for the Rhynn Lanthorn, bring it to Elhan.
Chapter 7: save Suldanessellar, summon Rillifane's avatar, free Ellesime and defeat Irenicus at the Tree of Life, then in Hell. The Throne of Bhaal entries (Saradush, Yaga-Shura, Balthazar, Melissan) continue the story.]] },
[74318] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-3]], w = [[Athkatla, Docks District]], h = { [[Yoshimo is a freelance thief, and the local guild wants a word with him.]], [[Renal Bloodscalp waits in a building of the Docks District.]], [[Bring Yoshimo to Renal and let them talk.]] }, s = [[The entry appears the first time you enter the Docks District with Yoshimo in the party.
Find Renal Bloodscalp, the local Shadow Thieves leader, inside his building in the Docks District, with Yoshimo in the group.
Talk to him: Yoshimo settles his standing as a freelancer and the matter is closed. Renal is also the man who later offers thieves a guild of their own.]] },
[74319] = { g = [[bg2]], k = [[main]], o = 34, c = [[1]], w = [[Irenicus's dungeon]], h = { [[This is a story note from Imoen, not a task you can finish now.]], [[Keep following the main story: the answer comes much later, from Irenicus himself.]] }, s = [[Imoen tells you in the opening dungeon that your captor claims to know how to unlock your Bhaalspawn power.
There is no action tied to this entry. It foreshadows the main plot: Irenicus's experiments and what he does to you and Imoen at Spellhold in Chapter 4. Just keep going with the main quest.]] },
[74320] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-3]], w = [[Athkatla, Slums and Government District]], h = { [[Jaheira suggested three leads: the Copper Coronet's bartender, the government building, and the poorest part of the city.]], [[Bernard can tell you what happened to her friend Belgrade, which points to the east end of the Slums.]], [[Kill Baron Ployer, take the lock of Jaheira's hair he carries, then rest.]] }, s = [[With Jaheira in the party, Baron Ployer confronts her and lays a curse that slowly drains her.
Optional: visit the government building in the Government District. Corneil is no help, but on the way out Terrece offers, for a bribe, that Ployer's hired mages will abandon him, or even turn on him.
At the Copper Coronet, ask Bernard about Belgrade: he was killed by the same curse in the east end of the Slums.
Find Ployer's house there and kill him. Without the bribe, expect his mages to help him.
Loot the lock of hair from his body and rest: the curse lifts.
If you refuse to help, Jaheira leaves the party.]] },
[74321] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, Temple District and sewers]], h = { [[Listen to the eyeless priest preaching in the Temple District, then accept a temple's offer to investigate.]], [[The cult's temple lies deep below the city, reached through the sewers; its god is a blind beholder.]], [[Join the two halves of the old rod and use it once on the beholder, as the avatar below advises.]] }, s = [[In the Temple District, watch the eyeless priest's sermon. A cleric of Talos, Helm or Lathander then invites you to their temple; accept the job (Nallabir, Oisig or Mornmaster Arval).
Enter the cult's temple from the sewers below the Temple District. Talk to Gaal: to join, he sends you to fetch a rod from the dungeon below and gives you a key. You can also simply attack, which summons the beholder.
Report what you learned to your temple, then return.
Below, meet the forgotten guardians and the avatar of their god: take his half of the rod.
Sassar explains how to reach the beholder's treasure niche; his friend Tad shows the way down the Pit of the Faithless (beware the carrion eaters).
Take the other half, assemble the rod and use it on the beholder. Return the rod to the avatar, then report to your temple for a reward.]] },
[74322] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, Government District]], h = { [[After the cult is destroyed, your temple wants the sculptor Sir Sarles, staying at the Jysstev estate.]], [[Sarles needs pure illithium; ask the ore merchant Jerlia at Waukeen's Promenade who supplies her.]], [[The real ore was stolen by the gnome Neb, hiding in the Derelict House of the Bridge District.]] }, s = [[Your temple contact (Talon Yarryl, Guardian Telwyn or Dawnbringer Sain) asks you to hire Sir Sarles.
Meet Sarles at the Jysstev estate in the southeast of the Government District: he wants 200 pounds of illithium.
Talk to Jerlia at her stall in the southwest of Waukeen's Promenade. She can make a cheap alloy (200 gold, ready after a day), but Sarles usually spots the fake.
For the real ore, ask her supplier, the duergar Unger Hilldark, at the Copper Coronet. He sends you to Neb in the Derelict House, Bridge District. Neb is a dangerous killer: fight him, take the illithium.
Give it to Sarles, then report to your temple for the reward.]] },
[74323] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Umar Hills, Imnesvale]], h = { [[A Cowled Wizard named Jermien is building a golem for the village of Imnesvale.]], [[Mimics are monsters that pose as chests; their blood is what he needs.]], [[This request has only one journal entry and may have no follow-up in the game.]] }, s = [[Jermien, a Cowled Wizard, asks for mimic's blood for the juggernaut golem he is building at Imnesvale.
The journal has no further entry for this quest, so it seems to be unfinished content: there may be no way to hand the blood over or to close it.
If you meet a mimic during your travels, keep whatever it drops and try speaking to Jermien again.]] },
[74324] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-3]], w = [[Athkatla, Graveyard and Temple Districts]], h = { [[Korgan wants the Book of Kaza from an old tomb below the Graveyard District.]], [[The book is gone; hurry to the collector Pimlico's house in the Temple District.]], [[Korgan's old companions are celebrating on the roof of the Copper Coronet.]] }, s = [[Recruit Korgan Bloodaxe (Copper Coronet) and accept his job for the collector Pimlico.
In the Graveyard District, find the crypt leading to an older lower tomb. Fight through the undead: the book is already gone.
Go to Pimlico's house in the Temple District: he has been murdered by Korgan's former party.
Climb to the roof of the Copper Coronet in the Slums and confront Shagbag and his friends. Kill them all before they flee.
Keep or sell the book: the gold is yours. If they escape, the quest fails.]] },
[74325] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, Slums]], h = { [[After the sculptor job, go back to your temple contact for a new task.]], [[A thief named Travin, in the Slums after dark, knows where the stolen Dawn Ring is.]], [[The fence Borinall has the ring, in a red brick house north of the Copper Coronet.]] }, s = [[Return to your contact (Yarryl, Telwyn or Sain). Helm's temple sends you to Dawnbringer Sain at Lathander's temple.
Go to the Slums at night and meet Travin. Talassans take delivery of the stolen Dawn Ring; Helm and Lathander want it back.
Travin sends you to the red brick house with red slate roof above the Copper Coronet on the map. Deal with Borinall there, by talk or force, and take the ring.
Bring it to your temple (Talos keeps it, Helm and Lathander return it to Lathander's temple) for the reward.]] },
[74326] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Umar Hills and Temple Ruins]], h = { [[Delon in Athkatla asks for help; go to Imnesvale and speak with Minister Lloyd.]], [[Madulf's ogres are not guilty; the ranger Merella's cabin west of the village holds the real clues.]], [[The Shade Lord lurks in the ruined temple of Amaunator to the east, with a shadow dragon on guard.]] }, s = [[Delon (Government District) sends you to the Umar Hills. In Imnesvale, talk to Minister Lloyd, northeast of the square.
Visit Madulf north of the village by the river: talk instead of fighting, he is innocent and points you to Merella's cabin (southwest of the map).
In the cabin read Merella's journal and Mazzy's note. Nearby, the werewolf Anath tells of the Shade Lord; spare or kill her.
Go east to the Temple Ruins. Inside, solve the statue's ritual riddles for a symbol of Amaunator (you need three to reach the final door). Help the two ghosts by returning Amuana's bones: Amuana gives a wardstone that hides you from the shadow dragon; keep it and do not attack the dragon.
Free Mazzy from her cage (she can join). A shadow in the cells hid a key in his cell.
Kill the Shade Lord, who wears Merella's body, and destroy his altar. Report to Lloyd for the reward.]] },
[74327] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Umar Hills, Imnesvale]], h = { [[Madulf the ogre, camped north of Imnesvale, would rather talk than fight.]], [[He offers to protect the village from orcs in exchange for peace and trade.]], [[Carry his offer to Minister Lloyd in Imnesvale.]] }, s = [[During the Umar Hills investigation, meet Madulf and his band north of Imnesvale by the river. Do not attack: his people are dying too.
Accept to carry his proposal: his band will guard the village against the hill orcs if the villagers leave them alone and trade with them.
Tell Minister Lloyd: he agrees to talk to the ogre. Later, if you are the village's ranger-protector, Madulf keeps his word when the orcs attack.]] },
[74328] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, sewers below the Temple District]], h = { [[A rambling man named Quallo in the sewers talks about a trapped blade and hidden clues.]], [[Three objects go into three drain pipes: Vallah's hand, a ring from skeletons and a kobold shaman's staff.]], [[Order: the hand first, the ring second, the staff last; a mistake resets the puzzle.]] }, s = [[In the sewers under the Temple District, talk to Quallo: he speaks of a sword bound by wards and of clues near the drains.
Collect the three items in the sewers: the ring carried by skeletons, Vallah's hand and the staff of the kobold shaman. Ask Quallo about each one.
Place them in the pipes in order: hand (suffering comes first), then ring (neither first nor third), then staff (it seals the deal). A wrong order makes you start again.
The wards break and you get the trapped magic sword.]] },
[74329] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Umar Hills, Imnesvale]], h = { [[Three bored boys in Imnesvale want you to buy them swords and ale.]], [[The merchant Min Minling sells what they ask for.]], [[Whatever you buy, you will meet the boys again later in the hills.]] }, s = [[In Imnesvale, three youngsters give you money to buy three bastard swords and some Baalor Ale.
Buy them (or only the ale, or only the swords) from Min Minling and hand them over. You can also refuse and return or keep their money.
Later in the Umar Hills you meet them again: drunk in a cave if they got only ale, chased by a gibberling if they got both, or nearly killed by a shadow creature if they got swords. A small, mostly humorous quest.]] },
[74330] = { g = [[bg2]], k = [[side]], o = 0, c = [[3-6]], w = [[Umar Hills]], h = { [[Rangers who clear the Umar Hills are offered Merella's cabin and her old duty.]], [[Answer the calls of Delon and the forest spirit Mairyn quickly, or you lose the post.]], [[Last threat: a sorceress calling herself Umar, in the emptied Shadow Portal dungeon.]] }, s = [[Ranger stronghold. After the Shade Lord is dead, Minister Lloyd gives you Merella's cabin west of Imnesvale. Rest there between events.
Mairyn asks you to stop humans felling her forest in the west, near the old Shadow Altar. Lord Igen pauses if you find his ancestor's mithral cache: look for the other half of the journal, likely in the old dungeon, and bring him what you find.
Delon warns of an orc attack: reach Imnesvale within three days and repel them. Madulf helps if his pact holds; rescue him from a nearby cave.
Later the false Umar threatens the village from the Shadow Portal dungeon: talk to the mayor, go in and kill her.
Mairyn rewards you with a gift from Mielikki. Refusing or arriving late strips you of the cabin.]] },
[74331] = { g = [[bg2]], k = [[side]], o = 0, c = [[3-6]], w = [[De'Arnise Keep]], h = { [[A fighter who frees the de'Arnise keep can rule it for Nalia's family.]], [[Collect your income from the majordomo, and answer each runner's summons within a week.]], [[The Roenalls finally attack in force: return in time and defeat Lord Farthington.]] }, s = [[Fighter stronghold. After the keep is retaken, Nalia asks you to hold her lands; the majordomo runs it and keeps about 500 gold per week for you. Raising taxes angers the people.
Runners call you back several times; each time return to the keep within about a week and talk to the majordomo:
- Lord Farthington Roenall visits to press his claim.
- A flood ravages the lands: settle the problems fairly.
- Roenall troops march on the keep: organise the defence and fight. Killing Lord Farthington ends the threat.
Arriving too late, or losing the battle, hands the keep to the Roenalls and you are banished.]] },
[74332] = { g = [[bg2]], k = [[main]], o = 42, c = [[2]], w = [[Anywhere (dream while resting)]], h = { [[This is a dream entry, nothing to do right now.]], [[Its questions are answered by the main story, when you finally catch up with Irenicus.]] }, s = [[While resting in Chapter 2 you dream of Imoen losing her sense of self and of Irenicus offering you power if you see through the pain.
No action is needed. Keep raising money for your patron and follow the main quest; the dream foreshadows what Irenicus does at Spellhold.]] },
[74333] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla, Waukeen's Promenade]], h = { [[Aerie's old mentor Quayle has sent for her.]], [[He is in the circus tent on Waukeen's Promenade.]] }, s = [[With Aerie in the party, she gets a message from Quayle asking for help.
Go to the circus tent on Waukeen's Promenade with Aerie and speak to Quayle. He usually passes on a request from an old friend, Raelis Shai, which leads to the playhouse under the Five Flagons (see A friend of Quayle's needs help).]] },
[74334] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-3]], w = [[Athkatla, Bridge District]], h = { [[A woman named Raelis Shai needs help and wrote to Quayle.]], [[She runs the playhouse beneath the Five Flagons Inn in the Bridge District.]] }, s = [[Quayle (or, if he is dead, Aerie through his letter) points you to Raelis Shai.
Go to the Five Flagons in the Bridge District and down to the playhouse in its cellar. Talk to Raelis: she asks you to rescue her actor Haer'Dalis from the wizard Mekrath (see Free Haer'Dalis from imprisonment by Mekrath).]] },
[74335] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-3]], w = [[Athkatla, Government District]], h = { [[Korgan's old party had a pending job offer from a man named Madeen.]], [[Madeen stands in front of the council building in the Government District.]] }, s = [[After the Book of Kaza affair, Korgan mentions a job his former party had been offered.
Take Korgan to the Government District and talk to Madeen in front of the council building to hear the offer.
The journal has no further entry for this quest, so its outcome may simply be the conversation with Madeen.]] },
[74336] = { g = [[bg2]], k = [[main]], o = 46, c = [[4]], w = [[Brynnlaw]], h = { [[Start at the Vulgar Monkey tavern and look for Sanik, who supplied the asylum.]], [[After Sanik's murder, ask about his fiancée Claire, held in Lady Galvena's courtesans' guild house.]], [[Claire's lead gives two ways in: Perth the Adept's wardstone, or convincing Pirate Lord Desharik you are insane.]] }, s = [[Saemon Havarian lands you in Brynnlaw (Shadow Thieves side: first beat the vampire ambush; Sime helps you).
At the Vulgar Monkey, talk to Sanik; an assassin from Lady Galvena kills him. The barkeep tells you about Claire.
Enter the courtesans' guild house on the west side: hire a courtesan, get the master's medallion from Chremy (who watches a girl named Ginia), or fight in. Inside, have the cook drug the guards, kill Galvena and her wizard, take her key and free Claire at the end of the hall.
Claire (or Captain Golin, or Saemon on his ship) tells you the two ways in:
- Desharik, northwest/far west of town: act insane; a high Charisma or Minsc helps. Hesitating fails.
- Perth the Adept: he is dominated and attacks; take his wardstone.
Then walk up the pass to Spellhold, minding traps and guardians.]] },
[74337] = { g = [[bg2]], k = [[main]], o = 60, c = [[6]], w = [[Athkatla, Graveyard District (Bodhi's lair)]], h = { [[Elhan says Bodhi holds the Rhynn Lanthorn in her lair below the Graveyard District.]], [[If Bodhi took your loved one, the cure lies in a book the temple of Oghma once bought in Imnesvale.]], [[Bring the victim and the master vampire's heart to the statue with outstretched arms in the Umar Hills temple.]] }, s = [[Chapter 6: Elhan gives you holy water and sends you to Bodhi's lair in the Graveyard District. Prepare against undead (protection from level drain helps).
Near the lair Bodhi ambushes you; if you have a romance, she steals your lover (Aerie, Jaheira, Viconia or Anomen) and turns them into a vampire.
In the lair, use Elhan's holy water where Bodhi draws her power, then defeat her and her vampires. Destroy her for good to take the Rhynn Lanthorn and her heart. Imoen gets her soul back.
To save a vampirized lover: the elven war sage sends you to the temple of Oghma; its head points to the Imnesvale bookseller and the Vampiricus Omnibus. Then go to the Umar Hills shadow temple, cross the hopscotch-like floor and place the lover with Bodhi's heart in the arms of Amaunator's statue.
Return the Lanthorn to Elhan.]] },
[74338] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, Slums (planar sphere)]], h = { [[The strange sphere in the Slums can only be opened by a Corthala: you need Valygar.]], [[Inside, the knights of Solamnia trapped there warn you of each wing's dangers.]], [[To leave, kill Lavok, then bring a demon's heart to the great golem powering the sphere.]] }, s = [[Bring Valygar (Umar Hills cabin) to the planar sphere in the Slums; his blood opens it.
Inside, meet the three Knights of Solamnia: Onvo warns of a wizard's room with a damaged golem, Reyna of halfling-like creatures to the west, Ancan of a sea room to the north.
Optional: repair the damaged golem; it goes off to fight the beholder.
Reach Lavok and defeat him. Dying, he is himself again and explains that the sphere drifts between planes.
Step outside, kill the demon there and take its heart, then put it in the great golem; Lavok sets the course home.
Back in Athkatla, a mage protagonist can keep the sphere as a stronghold.]] },
[74339] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla / Umar Hills]], h = { [[The Cowled Wizard Tolgerias wants the ranger Valygar Corthala brought to him.]], [[He expects a corpse, not directions.]], [[Siding with Valygar instead lets him join you and leads to the planar sphere.]] }, s = [[Tolgerias hires you to find Valygar, who lives in a cabin in the Umar Hills.
Options:
- Kill Valygar and bring his body to Tolgerias: you get the reward and some information.
- Only tell Tolgerias where Valygar is: depending on the case he pays you and leaves to capture him, or refuses and storms off, and the Cowled Wizards may hold it against you.
- Better: talk to Valygar, learn the truth about the sphere and let him join; Tolgerias then turns on you later.]] },
[74340] = { g = [[bg2]], k = [[side]], o = 0, c = [[5]], w = [[Sahuagin city]], h = { [[Captured by the sahuagin, you are hailed as a chosen one; win the king's trial by combat.]], [[High Priestess Senityili secretly backs the rebel Prince Villynaty; Sekolah's Tooth opens the rebel camp to the south.]], [[Help Villynaty with a false heart, or bring his real heart to King Ixilthetocal.]] }, s = [[If you leave Spellhold by Saemon's ship, sahuagin drag you to their city in Chapter 5. You can refuse everything and fight your way out.
Meet High Priestess Senityili, then King Ixilthetocal. Accept the trial and kill his monster.
The king wants the rebel leader's heart. Senityili gives you an orb so the rebels will take you to Prince Villynaty; Sekolah's Tooth (in a chest guarded by a spectator to the south) opens the rebel doors.
Good path: agree to Villynaty's plan, give the king a false heart and wait for the rebels to attack. Villynaty becomes king; take the treasury key from Ixilthetocal for your reward.
Other path: kill Villynaty and give his heart to the king for gold.
Either way you are shown the way to the Underdark.]] },
[74341] = { g = [[bg2]], k = [[main]], o = 62, c = [[7]], w = [[Suldanessellar, Tree of Life]], h = { [[A projected image of Ellesime speaks to you at the Tree of Life.]], [[Nuts from the palace gardens grow branches up to the three parasites on the trunk.]], [[Kill all three parasites, then rush to the center while Irenicus is weakened.]] }, s = [[After Rillifane's avatar clears the way, climb the Tree of Life and speak with Ellesime's image.
Take nuts from the palace gardens and use them at the marked spots to grow branches to each parasite draining the Tree. Kill all three, quickly.
Ellesime is freed and cuts Irenicus off from the Tree. Hurry to the central platform and fight Irenicus while he is still disoriented. Rest and buff before the last parasite.]] },
[74342] = { g = [[bg2]], k = [[main]], o = 64, c = [[7]], w = [[Hell]], h = { [[Each door in this hell holds a test of character and a Tear of Bhaal.]], [[Talk to the demon at each test; your choice, not your strength, matters most.]], [[With all the tears, the great door opens on Irenicus; good choices bring better rewards.]] }, s = [[After Irenicus dies you are pulled into a hell that answers to your Bhaal blood. Gather the Tears of Bhaal behind each door, then open the great door.
Tests (the demon explains each):
- Selflessness: one path harms you, the other an innocent or a companion. Taking the pain yourself is the good choice.
- Greed: a demon gives you Blackrazor; give it to the genie to free him, or kill the genie.
- Fear: accept or refuse the nymph-skin cloak; refusing is the brave choice.
- Pride: question the demon; the creature may hand over the tear without a fight.
- Wrath: Sarevok offers to teach you the Slayer form; accept or refuse and fight him.
Each choice gives a permanent bonus that depends on whether you chose well. Finally beat Irenicus and his demons through the great door.]] },
[74343] = { g = [[bg2]], k = [[main]], o = 49, c = [[4]], w = [[Spellhold]], h = { [[In the labyrinth under the asylum, the exit door wants the hand of the builder and a focus of power.]], [[Dace Sontan is the builder; the crystal lies in refuse worshipped by kobolds.]], [[Back upstairs, free the imprisoned mages to attack Irenicus, then leave by Saemon's ship or the portal below.]] }, s = [[After Irenicus's ritual, Bodhi drops you in the maze under Spellhold.
Solve the maze rooms; an Arbiter judges you on the way. Find Dace Sontan: take his hand (the builder's hand), and recover the crystal from the kobolds' trash pile. Use both on the exit door.
Bodhi attacks before you leave; you turn into the Slayer for the first time and she flees.
Saemon reappears and suggests using the inmates as an army. Free them; they assault Irenicus, who escapes.
Then choose: accept Saemon's offer of a ship to Tethir (leads to the sahuagin city), or take the key from Irenicus's rooms near the asylum entrance and use the portal in the basement (Underdark).]] },
[74344] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, Mekrath's lair (via the sewers)]], h = { [[Raelis Shai, in the playhouse under the Five Flagons, wants her actor Haer'Dalis back.]], [[The wizard Mekrath keeps him; his lair is reached through the sewers.]], [[Mekrath trades Haer'Dalis for a favour, or you can take him by force; then find the gem.]] }, s = [[Accept Raelis's commission at the playhouse beneath the Five Flagons (Bridge District).
Reach Mekrath's lair through the sewers. Either do his errand (recover his mirror from the imp, see the related quest) and he hands Haer'Dalis over, or fight Mekrath.
Haer'Dalis is in the north storeroom of the tower. Talk to him: he returns to the playhouse alone or joins your party.
Search Mekrath's lair for Haer'Dalis's gem and bring it to Raelis for a reward. Delivering it starts the planar prison quest.]] },
[74345] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, sewers]], h = { [[Mekrath's imp ran off with his mirror into the sewers.]], [[The imp may have summoned something with it; come prepared.]], [[Bring the mirror back and Mekrath offers you his slave as a reward.]] }, s = [[In his lair, Mekrath asks you to recover the mirror his imp stole.
Search the nearby sewers for the imp and whatever it called through the mirror, fight them and take the mirror.
Return it to Mekrath: he gives you a slave in the north storeroom of his tower, who is Haer'Dalis. If you fight Mekrath afterwards, you still find Haer'Dalis there once he is dead.]] },
[74346] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, Mekrath's lair / Bridge District]], h = { [[Haer'Dalis left a precious gem somewhere in Mekrath's lair.]], [[Search the wizard's rooms carefully once Haer'Dalis is free.]], [[Bring the gem to Raelis Shai in the playhouse under the Five Flagons.]] }, s = [[After freeing Haer'Dalis from Mekrath, he asks you to find his gem in the wizard's lair.
Search Mekrath's tower and rooms until you have it (Haer'Dalis confirms it if he is in the party).
Go to the playhouse beneath the Five Flagons Inn in the Bridge District and give it to Raelis Shai for your reward. She then uses it to open her portals, which starts the planar prison quest.]] },
[74347] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Planar prison]], h = { [[Follow the bounty hunters through the portal left open in the playhouse.]], [[The escaped gnome Tagget knows the prison; some floor markings teleport you to guard rooms.]], [[Destroy the Master of Thralls's orb in the magic brazier, then face the warden.]] }, s = [[When you give Raelis the gem, bounty hunters arrest the troupe and take them through a portal. Follow them.
In the prison, beat the bounty hunters and talk to Tagget the gnome: there is no physical exit, the warden must fall. Beware the teleport markings going straight north.
Accept Tagget's route east: find the Master of Thralls. His dwarven slave tells you to burn the orb in the magic brazier in a room you crossed.
Destroy the orb to free the collared slaves, then kill the warden in the cell room north of your arrival.
Raelis opens a conduit home. Haer'Dalis can then join you.]] },
[74348] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-3]], w = [[Athkatla, Docks District (Harper Hold)]], h = { [[A Harper named Meronia calls Jaheira away; she returns with a summons for you too.]], [[Go to the Harper Hold in the Docks District, with Jaheira.]], [[Galvarey means to imprison you; be ready for a hard fight against the Harpers.]] }, s = [[With Jaheira in the party, Meronia takes her aside; she comes back saying you are both summoned to the Harper Hold in the Docks District.
Go there quickly (Jaheira may wait for you inside). Talk to Galvarey: he wants to lock up the child of Bhaal to further his own career.
A fight breaks out against Galvarey and the Harper mages. Depending on her feelings, Jaheira fights at your side and breaks with the Harpers, or flees.
Loot the hold afterwards. Her storyline continues later with the Harpers' fallout.]] },
[74349] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-3]], w = [[Athkatla, Government and Bridge Districts]], h = { [[Anomen's sister has been murdered; go with him to his father's house in the Government District.]], [[Lord Cor blames the merchant Saerk; you can advise vengeance or the law.]], [[Magistrate Bylanna Ianulin in the government building handles the lawful route.]] }, s = [[Anomen hears of his sister Moira's death. Go with him to Lord Cor's house in the Government District (if you refuse, he leaves).
Cor demands revenge on Saerk. Your advice decides Anomen's future:
- Law: visit Magistrate Bylanna Ianulin in the government building. If the courts cannot act, you may still advise revenge. Staying patient gives Anomen the chance to become a true knight of the Order.
- Vengeance: go to Saerk's mansion in the center of the Bridge District. Anomen kills Saerk's daughter; fight Saerk and his guards (Yusef escapes). Tell Lord Cor it is done. Anomen turns bitter and leaves the Order's path.]] },
[74350] = { g = [[bg2]], k = [[side]], o = 0, c = [[5]], w = [[Sahuagin city, area to the south]], h = { [[A friendly spectator guards a chest holding Sekolah's Tooth.]], [[He guards the chest, not what is inside it.]], [[A wise speaker can talk him into letting you open it; otherwise you must fight.]] }, s = [[During The prophecy of Sekolah, Senityili sends you south of the sahuagin city for Sekolah's Tooth.
The chest is watched by a peaceful spectator beholder. Talk to him with your wisest character in the lead: point out that he guards the chest, not its contents.
If convinced, he lets you take the Tooth and wanders off happy. If not, you must kill him to open the chest. The Tooth opens the rebel camp doors.]] },
[74351] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2]], w = [[De'Arnise Keep]], h = { [[Nalia, at the Copper Coronet, begs for help: trolls and yuan-ti hold her family's keep.]], [[Enter by the secret door behind a bush north of the palisade, find the servant Daleson.]], [[Gather the three heads of the old flail, kill trolls with fire or acid, and find TorGal in the cellars.]] }, s = [[Meet Nalia at the Copper Coronet and travel to the keep she marks on your map.
At the palisade, Captain Arat asks you to open the drawbridge: the wheel is on the wall above the bridge. Enter through the secret door behind a bush north of the palisade.
Find Daleson: he speaks of trolls, yuan-ti, the beasts lured by dog stew and Lord de'Arnise's flail heads.
Fire or acid finishes fallen trolls. Charm or free the bodyguard Glaicus: he gives a flail head and points to a secret panel behind the armory. Rescue Lady Delcia (upstairs; her room hides the dungeon passage).
Assemble the flail, go down to the cellars and kill TorGal.
Report at the palisade. A fighter can then rule the keep.]] },
[74352] = { g = [[bg2]], k = [[side]], o = 0, c = [[3-6]], w = [[Druid Grove near Trademeet]], h = { [[A druid who rests in the grove near Trademeet is visited by its spirit.]], [[First task: kill the troll shamaness Nilthiri in the troll mound nearby.]], [[Come back within a couple of weeks; next, protect the boy Loren among the tents outside Trademeet.]] }, s = [[Druid stronghold, after the Trademeet druid troubles are resolved. Rest in the Druid Grove and the spirit of the grove appears.
Accept its call (refusing ends the quest).
Go to the troll mound inside the grove and kill the shamaness Nilthiri; bring fire or acid.
Return within about two weeks and rest in the grove again.
The spirit sends you to protect Loren, Marek's descendant, among the tents outside Trademeet's walls. Destroy the creature possessing him.
Loren goes to the grove for training; you will be called again only when ready to challenge for Archdruid.]] },
[74353] = { g = [[bg2]], k = [[main]], o = 63, c = [[7]], w = [[Suldanessellar / Hell]], h = { [[Elhan finally tells the truth about Irenicus and Bodhi's past.]], [[Save Suldanessellar and stop Irenicus at the Tree of Life.]], [[Then, in Hell, gather the Tears of Bhaal and face Irenicus one last time.]] }, s = [[Story summary of the last chapter (the English title says nineteen, the French one says chapter seven).
Part 1: bring the Rhynn Lanthorn to Elhan; he explains that Irenicus and Bodhi were elves cast out for their crime. Enter Suldanessellar, find Demin, collect the talisman of Rillifane, the moonblade and the golden cup, and put them on the temple altar to summon Rillifane's avatar. Free Ellesime and defeat Irenicus at the Tree of Life.
Part 2: in Hell, pass the tests to collect the Tears of Bhaal, open the great door and defeat Irenicus to regain your soul.]] },
[74354] = { g = [[bg2]], k = [[side]], o = 0, c = [[3-6]], w = [[Athkatla, Bridge District (Five Flagons playhouse)]], h = { [[A bard who rescued Raelis's troupe receives the playhouse under the Five Flagons.]], [[Hire the director Higgold, fund the play, and answer every summons Meck brings you.]], [[Wise choices along the way, and stepping in for Zaren on opening night, make the play a success.]] }, s = [[Bard stronghold. After the planar prison, Raelis gives you the playhouse deed. Samuel Thunderburp sends the director Higgold.
Agree to stage a play, come back after about a week with money to invest. Higgold picks The Sorcerer's Bane, said to be cursed.
Choose the lead actress: Jenna is easy, Iltheia is the better actress but a diva.
During the six to seven weeks of rehearsals, Meck fetches you for problems: a fussy actor, the music, strange happenings tied to the curse, barbarians taking over the stage. Go each time and solve them.
Attend the dress rehearsal, then opening night: Zaren cannot perform, so play his role yourself. Refusing ruins the play.
If it succeeds, keep the playhouse for a regular income collected from Higgold, or sell it to him for 10,000 gold.]] },
[74355] = { g = [[bg2]], k = [[main]], o = 56, c = [[5]], w = [[Underdark, Ust Natha]], h = { [[Bring Matron Ardulace the blood of an elder race, then answer Phaere's summons.]], [[Phaere wants the real dragon eggs swapped for fakes; Solaufein, if spared, gives you better fakes.]], [[Stop the ritual, kill Ardulace to lift the city's seal, then flee quickly with Adalon's eggs.]] }, s = [[Ardulace asks for the blood of an elder orb (beholder tunnels), an elder brain (illithid city) or a kuo-toa prince (western ruins), within three days. Bring one.
She seals the city for her ritual. Phaere then reveals the plan to sacrifice Adalon's eggs to a demon and orders you to swap them in the Despana treasury, inside Lolth's temple, with her fakes.
If you spared Solaufein, he gives you a second, perfect set of fake eggs.
Options: give the fakes to Phaere and keep the real eggs; or expose Phaere to Ardulace. Adalon's imp says the ritual must fail and Ardulace must die.
At the ritual, fight: kill Ardulace (and Phaere). The seal lifts and you have minutes before your disguise fails: run for the exit and return the eggs to Adalon.
Evil choice: give the eggs to the demon for a weapon or an escort out.]] },
[74356] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla, Government District / Docks]], h = { [[Someone in the Government District knows how Isaea abuses his rank.]], [[Isaea's dirty dealings leave traces with a drunk at the docks, a slaver and in his own house.]], [[Gather enough proof, then bring it all to Isaea's commander Corgeig in the government building.]] }, s = [[Isaea Roenall uses his military post to arrest Nalia, and her location is unknown.
In the Government District, talk to the soldier Khellor: he names Barg, a contact at the docks, and points to Isaea's house northwest of the government building.
In the Docks District, get Barg talking: he names the slaver Dirth, found at the Sea's Bounty. Dirth attacks; take the transaction ledger from his body.
Search Isaea's house for his records.
Bring everything to Corgeig in the government building. With too little proof he sends you away; with all of it he frees Nalia and opens an investigation into Isaea.]] },
[74357] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Windspear Hills, Firkraag's dungeon]], h = { [[The relic hunter in Firkraag's dungeon is too eager to let you take all the risks.]], [[Be ready for a fight when you bring Samia what she asked for.]], [[Samia and her companions attack once you hand over or show the texts from the burial chamber.]] }, s = [[In Firkraag's dungeon in the Windspear Hills, Samia asks you to fetch texts about a dead Tethyrian king from his burial chamber and gives you her key.
The chamber is guarded by an invisible creature: bring a way to see or dispel invisibility.
Take the texts and return to Samia. She reveals her plan: let a dupe do the work, then kill them and keep the prize. She and her companions attack.
Defeat them to close this entry. The texts and the tomb's loot stay with you.]] },
[74358] = { g = [[bg2]], k = [[main]], o = 40, c = [[2-3]], w = [[Athkatla, Graveyard District / Docks]], h = { [[Bodhi, in the crypts under the Graveyard District, gives you a series of jobs against the Shadow Thieves.]], [[The jobs are a guarded shipment at the docks, then a rescue or a murder, then the Shadowmaster himself.]], [[Gaelan Bayle holds the key to Aran's lair, and Tizzak inside explains the two magical doors.]] }, s = [[Side with Bodhi in the Graveyard District crypts. The Shadow Thieves become hostile. The crypts are a safe place to rest.
1. Docks District: kill the Shadow Thieves guarding a shipment, take the crate and bring it to Bodhi.
2. Second task, depending on your path: rescue Palern Flynn alive from the second floor of the Shadow Thief headquarters, or kill the merchant Vulova (Government District, between the jail and the government building) and drop her cloak and dagger in his fountain. You may let Vulova flee instead; failing this task does not matter.
3. Get the key from Gaelan Bayle, then use the secret door on the right inside the guild headquarters. Free Tizzak: press the button at the end of the trapped northern hall, take the second key from the wizard Haz, and kill Aran Linvail.
Return to Bodhi: she has booked passage to the asylum where Imoen is held.]] },
[74359] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, Slums, planar sphere]], h = { [[The necromancer Lavok is the master of the planar sphere in the Slums.]], [[Bring the sphere back to your own plane, and Lavok will ask one last favour before he dies.]], [[Decide whether to carry the dying Lavok outside or to let him die inside the sphere.]] }, s = [[Enter the planar sphere in the Slums (with Valygar, or with what opens its door) and work through it until you face Lavok and return the sphere to Athkatla's plane.
The old necromancer is dying. You can honour his wish and bring him outside to die under his home sky, or refuse and let him die inside so he can harm no one.
If the protagonist is a mage, Lavok leaves the sphere to you: it becomes your stronghold, with its own quests later.
Either way the quest ends with Lavok dead.]] },
[74360] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Windspear Hills, Firkraag's dungeon]], h = { [[Garren's child was taken by Firkraag's men; look for a hidden lair in the Windspear Hills.]], [[The child sits in a magically locked cell; a mage in the dungeon has the key.]], [[You do not need to fight Firkraag: free the child, then go back to Garren's cabin.]] }, s = [[After Garren clears your name with the Order of the Radiant Heart, he finds his child kidnapped.
Explore the Windspear Hills to find Firkraag's dungeon; an orc inside mentions Firkraag, a sign you are on track. You may also meet the relic hunter Samia, who sends you into a tomb (a trap, see her own entry).
Find the child in a magically locked cell. Kill the mage nearby who carries the key, open the cell and the child runs home.
Return to Garren's cabin for your reward. Firkraag is an optional and very dangerous red dragon fight.]] },
[74361] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Umar Hills, Imnesvale]], h = { [[A farmer in Imnesvale gossips about his neighbours, the Hendricks.]], [[The Hendricks hid their late daughter's treasure in an unusual place on their farm.]], [[One of the Hendricks' chickens swallowed a gem: buy it from the farmer, or take it.]] }, s = [[In Imnesvale, talk to the farmer Jeb. He suspects the Hendricks, farmers who fled into the village, fed something valuable to one of their chickens; their adventuring daughter brought it home before she died.
Talk to Mr. Hendrick and offer to buy the hidden item: paying a fair price gets you a beljuril gem and a grateful farmer.
You can also find the gem by dealing with the chicken yourself, which is the less kind option.]] },
[74362] = { g = [[bg2]], k = [[main]], o = 54, c = [[5]], w = [[Underdark, Ust Natha]], h = { [[Disguised as Veldrin, report to Solaufein at the Male Fighters' Society and never keep the drow waiting.]], [[Each task comes from Phaere: meet her and Solaufein where she says, within the time she gives.]], [[Many tasks have a bloodless way out: the svirfneblin patrol and Solaufein can both be talked into helping you.]] }, s = [[Go fast at every step: delays make the drow suspicious and the whole city turns hostile.
1. Meet Solaufein at the Male Fighters' Society (north, past the Female Fighters' Society). Meet him and the handmaiden Imrae at the city entrance.
2. Rescue Phaere from the illithids, meeting Solaufein near their city in the southeast of the main cavern. Return to the entrance, then see Phaere at the tavern.
3. Kill the svirfneblin patrol near their village, or visit the gnomes and get the leader's helmet peacefully (you may send Solaufein back first). Bring the helmet to Phaere at the tavern.
4. Kill the adamantite-smuggling beholder on its spelljammer platform with Phaere and Solaufein; do not hurt them.
5. Meet Phaere at the temple of Lolth to see Matron Mother Ardulace, then in her quarters in the Female Fighters' Society tower. She wants Solaufein dead: kill him in his quarters or talk him into giving you his piwafwi cloak, and bring it back.]] },
[74363] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Windspear Hills]], h = { [[Lord Jierdan Firkraag pays well to clear ogres from his lands in the Windspear Hills.]], [[The ogres are not what they seem, and there is a witness to what happens.]], [[Accept Garren Windspear's offer of shelter in his cabin south of the ambush.]] }, s = [[Lord Jierdan Firkraag approaches you and offers 10,000 gold to kill the ogre bandits on his land in the Windspear Hills.
Travel there. The ogres are paladins of the Order of the Radiant Heart under illusions, and they see you as ogres too; the fight is forced.
Garren Windspear witnesses it and offers you shelter in his cabin, a short way south. Accept, or return later.
At the cabin Garren explains that Firkraag set this up, and that Firkraag ruined him too. He leaves for Athkatla to clear your name. This leads to the rescue of his child.]] },
[74364] = { g = [[bg2]], k = [[main]], o = 61, c = [[6]], w = [[Suldanessellar]], h = { [[Look for High Priestess Demin in the southwest of the elven city.]], [[Three relics stolen from Rillifane's temple must go back on his statue; the strongest monsters carry them.]], [[The cup, talisman and moonblade are spread among the city's invaders, one with the black dragon in the northwest.]] }, s = [[The Rhynn Lanthorn reveals Suldanessellar, besieged by Irenicus's creatures. Elhan stays at the entrance.
An elf says Demin was fighting in the southwest: find her in a building there. Irenicus has sealed the palace with Queen Ellesime inside.
Agree to her plan: recover the cup, the talisman and the moonblade from the strongest monsters in the city, including the black dragon outside to the northwest. Demin confirms when you have them.
Place the three relics on Rillifane's statue in his temple. The avatar of Rillifane Rallathil wakes the forest guardians and breaks the seal.
Enter the palace; you will need the Stone Harp and Horn to get through it.]] },
[74365] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Umar Hills, Imnesvale]], h = { [[Not every ogre in the Umar Hills is your enemy.]], [[Madulf and his fellow deserters would rather live in peace near the village.]], [[Talk to Madulf instead of fighting, then bring his offer to Imnesvale's mayor.]] }, s = [[In the Umar Hills, talk to the ogre Madulf rather than attacking him and his band of deserters.
Agree to help them reach an understanding with Imnesvale, then speak with Mayor Lloyd in the village.
The deal: the deserters protect the village and are left in peace, maybe even trading now and then. Killing them instead skips this ending.]] },
[74366] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla, Waukeen's Promenade / Government District]], h = { [[Travel with Cernd: an old friend of his has news about the wife he left behind.]], [[Cernd's former servant Fennecia knows what happened, but talks more freely without him.]], [[The child lives with the noble Deril in the southernmost mansion of the Government District.]] }, s = [[With Cernd in the party, Igarol tells him that his abandoned wife was pregnant, and sends him to his old house in Waukeen's Promenade.
In the house, a beggar says the servant Fennecia now works as a nanny in her own home, marked on your map.
Fennecia only says that Galia is dead while Cernd is there; talk to her alone. Galia took up with the noble Deril and died in strange circumstances; the baby is still in Deril's house, the southernmost mansion in the Government District.
Go there and help Cernd confront Deril. If you refuse, it ends badly with Cernd.
Cernd names the boy Ahsdale and takes him to the Druid Grove; come back a day or so later to get Cernd again.]] },
[74367] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-3]], w = [[Athkatla, Docks / Umar Hills]], h = { [[Tolgerias of the Cowled Wizards wants Valygar Corthala; start at Valygar's house in the Docks District.]], [[His servant Hervo, his friend Suna Seni and a clerk in the government building all point to family land.]], [[Valygar hides in a cabin in the Umar Hills; hear him out before deciding whom to help.]] }, s = [[Tolgerias, in the government building, asks you to bring Valygar back dead or alive. Refusing angers the Cowled Wizards.
In Valygar's house in the Docks District, Hervo lets you look around and mentions the family land in the Umar Hills and his friend Suna Seni. The clerk Llarsh confirms the land and links Valygar to Lavok and the planar sphere in the Slums.
Find Valygar in his cabin in the Umar Hills. He explains that the wizards need his blood to open the sphere, where Lavok waits to steal a relative's body.
Choices: recruit him and enter the sphere together (good path); let him go (he can be found later through Hervo); or kill him and bring the body to Tolgerias.
Lying to Tolgerias fails. Whatever you do, expect Tolgerias to turn on you near the sphere.]] },
[74368] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Trademeet]], h = { [[After the ceremony in Trademeet, two rival nobles each try to hire you.]], [[Both want the Mantle of Waukeen from a haunted tomb in town, to prove their claim.]], [[Lord Logan asks for the circlet for the sake of peace; giving it to him is the gentlest ending.]] }, s = [[Once you have dealt with Trademeet's troubles, Lord Logan Coprith holds a ceremony. Lady Lilith Lurraxol and Lord Skarmaen Alibakkar each approach you; visit one of them at their estate.
Your employer gives you the tomb key and warns it is haunted. Lord Logan asks you to bring the Mantle of Waukeen to him instead.
Clear the tomb and take the gold circlet. Outcomes:
Give it to Logan: smaller reward, both families annoyed, but peace kept.
Work for one family: you are rewarded for killing the head of the other, and Logan is unhappy.
If both families end up fighting you and each other, all die; Logan does not blame you.]] },
[74369] = { g = [[bg2]], k = [[main]], o = 55, c = [[5]], w = [[Underdark, Ust Natha]], h = { [[A silver dragon guards the way to the surface, but her hands are tied while the drow hold her eggs.]], [[Adalon disguises you as the drow Veldrin so you can search Ust Natha.]], [[Earn the drow's trust step by step until you can take the eggs, then carry them back to Adalon.]] }, s = [[In the Underdark, reach Adalon the silver dragon. Irenicus and Bodhi stole her eggs and gave them to the drow.
She gives you the appearance of a drow named Veldrin and sends you into Ust Natha. Play along with the drow tasks (see the Ust Natha quest) without being found out, until you get hold of the eggs.
Return the eggs to Adalon: she gives you an item from her hoard and takes you to the surface.
If the city turns against you, Adalon can no longer help and only a hard fight remains. Destroying the eggs or attacking Adalon makes her an enemy, and you must find another exit.]] },
[74370] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-3]], w = [[Athkatla]], h = { [[A mob in Athkatla is about to burn someone at the stake.]], [[The victim is a drow cleric you may remember from the Sword Coast.]], [[Drive off or kill the fanatics around the stake to save Viconia.]] }, s = [[In Athkatla, a group of fanatics has caught Viconia and is about to burn her at the stake.
Talk to their leader and intervene; the fanatics attack, so be ready for a fight.
Once they are dead, talk to Viconia: she can join the party now, or tells you she can be found in the Graveyard District later.]] },
[74371] = { g = [[bg2]], k = [[side]], o = 0, c = [[4-5]], w = [[Sahuagin city]], h = { [[Two imps watch over six chests and offer a game before you open the locked one.]], [[Each illusionary figure hands you an item that belongs to another; return every item to its true owner's chest.]], [[Solve the riddle before opening the locked chest, or the specter inside kills whoever opens it.]] }, s = [[In the room with six chests, the imps warn that the locked chest holds something that steals souls. They will protect you if you solve their riddle.
Talk to each illusionary figure: it gives you an item. Work out which figure each item really belongs to and put it in the chest behind that figure.
When all items are placed correctly, talk to the imps. If you are right, open the sixth chest: the imps drive the specter away and you keep the drow treasure.
Opening it without solving the riddle releases the specter, which kills the opener and flees.]] },
[74372] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Trademeet / Druid Grove]], h = { [[After the druid grove, Lord Logan sends you to Guildmistress Busya in his house.]], [[The Dao genies will leave once they have the rakshasa Ihtafeer, who hides outside town.]], [[The local Shadow Thieves suspect the old potion seller in the hut northeast of the druid grove.]] }, s = [[Once the druid grove is calm, Lord Logan Coprith tells you about the genies. Talk to Guildmistress Busya in his house: find the rakshasa or kill the genies.
Talk to Khan Zahraa, leader of the Dao. He wants the head of the rakshasa Ihtafeer, probably hiding near town.
Itona of the Shadow Thieves says Ihtafeer has replaced the potion seller Adratha, in a hut northeast of the druid grove. Go there, unmask her and kill her.
Bring the head to Khan Zahraa: the Dao leave for Calimshan. Fighting the genies also solves it.
Collect your reward from Busya, then report to Lord Logan.]] },
[74373] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Windspear Hills]], h = { [[This is the sad ending of the hunt for Garren's child.]], [[The child must be freed before anything happens to it in Firkraag's dungeon.]], [[Free the child from its cell first; only then think about facing Firkraag.]] }, s = [[This entry closes the Garren quest when his child died in Firkraag's dungeon.
Garren is broken and furious, even if you killed Firkraag, and there is nothing more to do with him.
To avoid it, reload and rescue the child: kill the mage who holds the key to the magic cell, open it and let the child run home before you deal with the dragon.]] },
[74374] = { g = [[bg2]], k = [[main]], o = 38, c = [[2]], w = [[Athkatla, Graveyard District]], h = { [[Valen's mistress will not deal with you for free.]], [[Her price is the same kind of sum the Shadow Thieves ask, but smaller.]], [[Come back to the Graveyard District at night with 15,000 gold.]] }, s = [[Bodhi, Valen's mistress, refused to deal with you because you lacked her price.
Gather 15,000 gold through side quests in and around Athkatla.
Return to the Graveyard District at night and talk to her again to accept her offer. This starts Bodhi's tasks and moves the story to the next chapter.]] },
[74375] = { g = [[bg2]], k = [[main]], o = 39, c = [[2]], w = [[Athkatla, Graveyard District]], h = { [[This entry records that you turned Bodhi down.]], [[Refusing Bodhi keeps you on the Shadow Thieves' side.]], [[Pay Gaelan Bayle the Shadow Thieves' price to move on.]] }, s = [[Bodhi offered to help you find Imoen for less gold than the Shadow Thieves, with bloody jobs in return. You refused, and she is now your enemy, though she let you go.
Nothing more to do here. Gather the 20,000 gold for Gaelan Bayle in the Slums: he sends you to the Shadowmaster, Aran Linvail, and the Shadow Thieves' path of the next chapter.
Expect to meet Bodhi again as a foe.]] },
[74376] = { g = [[bg2]], k = [[main]], o = 37, c = [[2]], w = [[Athkatla, Graveyard District]], h = { [[A woman named Valen approaches you and hints that your current allies cannot be trusted.]], [[Her mistress waits for you in the Graveyard District, but only at night.]], [[Follow Bodhi when she leads you away to talk in private.]] }, s = [[Some time after you meet Gaelan Bayle, Valen approaches you in Athkatla and invites you to meet her mistress.
Go to the Graveyard District at night. Bodhi introduces herself and asks you to follow her to a quieter place.
She reveals that Gaelan works for the Shadow Thieves and offers the same help for 15,000 gold. Accept (with the gold, or come back later with it) to work for her, or refuse and stay with the Shadow Thieves.
With some characters, Bodhi decides she cannot trust you, vanishes in mist and promises to meet again in battle.]] },
[74377] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Trademeet]], h = { [[Jenia asks you to see her son Tiris at their house north of the Alibakkar estate.]], [[The tanner Rejiek from the Bridge District is in Trademeet, working with a skinless creature.]], [[Not everyone who hunts the skin dancer is who he claims to be; keep a restoration spell at hand.]] }, s = [[This follows Rejiek's escape in the Bridge District. Jenia sends you to Tiris: he and Raissa were kidnapped and taken to the woods by the southwest gate.
In the woods, Darsidian Moor says he hunts a skin dancer hiding in a walled area north of the east gate, in an orange pavilion, and goes ahead.
There, Darsidian asks you to kill an unconscious 'Rejiek'. Be careful: Darsidian and the rescued 'Raissa' can be skin dancers too, and the real Rejiek may be in disguise.
Kill Rejiek and Darsidian. The true Raissa has been turned into a skin dancer: cast Restoration on her quickly (the Waukeenar temple may sell a scroll). Without it she flees or must be killed.
Return to Tiris. Best ending: Raissa restored, and the couple leave to marry.]] },
[74378] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla, Slums, Copper Coronet]], h = { [[Mazzy's pride has led her to challenge an ogre pit fighter at the Copper Coronet.]], [[An alchemist named Festule has a potion that could even the odds.]], [[Get Gorf's girlfriend Bunkin to slip Festule's potion into his drink before the fight.]] }, s = [[With Mazzy in the party, she challenges Gorf the Squisher, an ogre pit fighter, to a duel at the Copper Coronet.
Before going to the fight, get a potion from Festule the Alchemist. He suggests talking to Bunkin, Gorf's girlfriend.
Convince Bunkin that the potion will make Gorf nicer so she puts it in his drink.
Go to the Copper Coronet's pit: Mazzy fights Gorf alone. With the potion, she should win. Without help she may die, so buff her before the duel and keep a way to raise her.]] },
[74379] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla, Graveyard District]], h = { [[Travel with Nalia after her keep has been cleared; a messenger will find her.]], [[Her father's funeral takes place in Athkatla's Graveyard District.]], [[At the funeral, the son of Lord Roenall presses Nalia about her betrothal.]] }, s = [[With Nalia in the party after Lord de'Arnise's death, a messenger asks her to come to her father's funeral.
Go to the Graveyard District in Athkatla soon. At the funeral, Isaea Roenall insists that Nalia honour the betrothal her father arranged and grows angry when she refuses.
Nothing to fight here. This sets up Isaea's later move against Nalia (see 'Nalia abducted by Isaea Roenall').]] },
[74380] = { g = [[bg2]], k = [[main]], o = 50, c = [[4]], w = [[Brynnlaw]], h = { [[After Spellhold, Saemon Havarian waits at the Brynnlaw tavern with an offer of passage.]], [[His ship is disabled; he wants you to steal the horn that opens the sea gates.]], [[Desharik's girlfriend Cayia keeps the horn in her house, west on the second tier, at night.]] }, s = [[Once out of the asylum, Saemon offers a way off the island. Gather your gear and meet him at the tavern.
He reveals that the Pirate Lord Desharik has disabled his ship; he plans to steal Desharik's. Your part: steal the horn that opens the sea gates from Cayia's house, west on the second tier, at night.
Bring it to Saemon at the docks. After a short fight with Desharik's men you sail away, and Saemon gives you a silver sword (trouble follows, see 'Betrayed on the voyage back').
Alternatives: refuse and use the magic portal inside the asylum. If Saemon dies in the fight with Desharik, the portal is your only way out.]] },
[74381] = { g = [[bg2]], k = [[main]], o = 51, c = [[4-5]], w = [[At sea, then the Sahuagin city]], h = { [[The silver sword Saemon gave you was not his to give.]], [[Its real owners, the githyanki, come aboard to take it back.]], [[Survive the githyanki attack; the ship is sinking and the sahuagin take you below.]] }, s = [[On the voyage from Brynnlaw, githyanki board the ship: the silver sword Saemon gave you was stolen from them. They fight to get it back; prepare for a tough battle.
During the fight, sahuagin storm the sinking ship and Saemon teleports away.
You end up in the Sahuagin city under the sea. From there the road leads into the Underdark.]] },
[74382] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Athkatla / Underdark]], h = { [[A letter in Rejiek Hidesman's home names a craftsman who was working with him.]], [[Darcin Cole believes you are Rejiek and will finish the armor for a rare ingredient.]], [[The blood of a silver dragon can only come from Adalon in the Underdark.]] }, s = [[Search Rejiek Hidesman's home after the skinning murders: take the unfinished hide and the letter.
Find the man the letter mentions and name him correctly as Darcin Cole. He takes you for Rejiek and asks for the blood of a silver dragon.
In the Underdark, after helping Adalon, obtain some of her blood.
Give the hide and the blood to Darcin Cole and come back four days later. He hands over the finished dark leather armor, then realises you are not Rejiek and attacks with summoned wizards. Be ready for a fight.]] },
[74383] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla]], h = { [[Anomen's sister has been murdered, and his father Lord Cor demands blood.]], [[Your advice decides whether Anomen leaves justice to the Order or takes revenge himself.]], [[Urging him to avenge Moira sends him after the Saerk family, with lasting effects on his path.]] }, s = [[With Anomen in the party, he learns that his sister Moira was murdered. Lord Cor blames his rival Saerk and demands vengeance.
If you encourage Anomen to act himself, he attacks Saerk's household: Saerk and his daughter die, the son Yusef escapes. Lord Cor recovers his fortune and leaves for Calimshan; Anomen is not happy.
This choice weighs on Anomen's knighthood trial: advising patience and trusting the Order is the path that keeps him a candidate knight.]] },
[74384] = { g = [[bg2]], k = [[main]], o = 59, c = [[6]], w = [[Athkatla]], h = { [[Back in Athkatla, you can ask powerful groups for help before attacking Bodhi's lair.]], [[The temples mostly decline, but they point to the Order of the Radiant Heart.]], [[Prelate Wessalen or Aran Linvail can send fighters to meet you beneath the Graveyard District.]] }, s = [[Before facing Bodhi in her lair under the Graveyard District, look for allies (optional).
The temples of Helm and Lathander cannot help and send you to the Order of the Radiant Heart; Nallabir at the temple of Talos refuses outright.
Ask Prelate Wessalen at the Order's hall in the Temple District: if he agrees, Sir William Reirrac's group waits for you under the Graveyard District.
If you sided with the Shadow Thieves, ask Aran Linvail: he may send his spare assassins.
Either can refuse, depending on your past dealings. Allies only help in the fight; you can face Bodhi without them.]] },
[74385] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Athkatla]], h = { [[The Cowled Wizard Jermien needs a rare ingredient to bring his juggernaut golem to life.]], [[The blood of a mimic is what he asks for.]], [[Stand ready when the golem wakes: it turns on its maker, and Jermien's daughter is in the room.]] }, s = [[Jermien, a Cowled Wizard, wants a mimic's blood to activate his juggernaut golem. Daar, who loves Jermien's daughter Colette, is also involved.
Bring the mimic's blood to Jermien. The golem comes to life and attacks its maker.
Kill the golem quickly. If you are fast enough, Jermien survives and thanks you. If he dies, save Colette at least; she leaves sadly with Daar.]] },
[74386] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla, Temple District]], h = { [[Anomen is called before the Order of the Radiant Heart to be judged.]], [[Go with him to the Order's hall in the Temple District within two days.]], [[The verdict depends on how Anomen acted earlier, above all about his sister's murder.]] }, s = [[With Anomen in the party, the time comes for his trial. He must reach the Order's hall in the Temple District within two days.
Go with him and enter the hall to watch the judgment. If you refuse to come, he leaves alone, angry, and is unlikely to return.
If he showed restraint and left vengeance to the Order, he is made a full knight. If he took revenge himself, he is found unworthy, storms out, and turns down a darker path.]] },
[74387] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Windspear Hills]], h = { [[This is the happy ending of the hunt for Garren's child.]], [[Once the child is freed from Firkraag's dungeon, Garren is waiting at his cabin.]], [[Return to Garren's cabin; killing Firkraag is a bonus, not a requirement.]] }, s = [[Free Garren's child from the magically locked cell in Firkraag's dungeon (the key is on a mage nearby). The child runs home.
Return to Garren's cabin in the Windspear Hills. He thanks you and offers his cabin as lodging whenever you pass by.
Whether Firkraag is alive or dead, the quest ends here. Firkraag stays an optional and very hard dragon fight.]] },
[74388] = { g = [[bg2]], k = [[main]], o = 48, c = [[4]], w = [[Spellhold, dream world]], h = { [[Inside the dream, follow Imoen's voice: she says you cannot fight alone.]], [[Each door deeper into your mind asks a sacrifice of yourself.]], [[Find the Bhaal creature and bring it back to Imoen so you fight it together.]] }, s = [[Irenicus starts his ritual in Spellhold and you fall into a dream.
Find Imoen in the dream. She tells you to seek the 'Bhaal creature', your instinct, and lead it back to her: fighting it alone means death, win or lose.
Go through the doors deeper into your mind; each one takes a sacrifice from you.
Find the creature, lure it back to Imoen and defeat it together.
You wake up: Irenicus has taken your soul and leaves Bodhi to finish you off. Fight your way out of the asylum.]] },
[74389] = { g = [[bg2]], k = [[side]], o = 0, c = [[2]], w = [[Athkatla, Government District]], h = { [[A man named Madeen knows of a Cowled Wizard looking to hire someone.]], [[Tolgerias waits in the main government building.]], [[Tolgerias promises news of Imoen in exchange for finding Valygar Corthala.]] }, s = [[Madeen tells you that the Cowled Wizard Tolgerias wants to hire someone.
Go to the main government building in the Government District and talk to Tolgerias.
He promises information about Imoen if you do his service: find Valygar Corthala. Accepting starts 'The hunt for Valygar Corthala'; refusing angers the Cowled Wizards.]] },
[74390] = { g = [[bg2]], k = [[main]], o = 43, c = [[3]], w = [[Athkatla]], h = { [[You have paid for help finding Imoen: either the Shadow Thieves or Bodhi now expect your service.]], [[Shadow Thieves path: take Gaelan's key to Aran Linvail beneath the guild headquarters in the Docks District.]], [[Bodhi path: do her tasks against the Shadow Thieves from the crypts in the Graveyard District.]] }, s = [[Chapter 3 starts when you pay for help finding Imoen.
Shadow Thieves: Gaelan gives you a key to meet the Shadowmaster, Aran Linvail, in his lair under the Shadow Thief headquarters in the Docks District. He asks you to strike at the vampire guild in the Graveyard District, then arranges your passage to the island where Imoen is held.
Bodhi: work for her from the crypts beneath the Graveyard District. She sends you against the Shadow Thieves: a shipment at the docks, a second task, then killing Aran Linvail. She then books passage to the asylum.
Either way the chapter ends when you sail to Brynnlaw.]] },
[74391] = { g = [[bg2]], k = [[main]], o = 47, c = [[4]], w = [[Spellhold]], h = { [[Inside Spellhold, the friendly coordinator offers a tour and a visit to Imoen.]], [[Lonk the Sane, a worker, tells you where Imoen is and how she has changed.]], [[Seeing Imoen springs Irenicus's trap: be ready for what follows.]] }, s = [[Once inside Spellhold, talk to the coordinator: he offers a tour and to take you to Imoen.
Talk to the worker Lonk the Sane: Imoen is just down the hall, confused and violent. He seems surprised you know Irenicus.
Find Imoen; she is clearly not herself.
Irenicus then reveals himself: it was a trap from the start. He captures you to take your divine soul, as he already did to Imoen, who is also a child of Bhaal.
This leads to the dream sequence ('The transformation and the dream').]] },
[74392] = { g = [[bg2]], k = [[side]], o = 0, c = [[2]], w = [[Athkatla, Slums, Copper Coronet]], h = { [[The Copper Coronet's owner lets some guests into his 'back rooms'.]], [[Behind them is a slave pen, where Hendak begs for help to escape.]], [[Helping Hendak is the good path; betraying him to Lehtinan earns you a discount from Bernard.]] }, s = [[In the Copper Coronet in the Slums, the owner Lehtinan gives you leave to visit his back rooms.
There you find the slave pens. The slave Hendak asks for help to escape.
Good path: agree, free Hendak and fight Lehtinan and his men.
Evil path: refuse, report Hendak to Lehtinan, take the key he gives you and kill Hendak in his cell. Lehtinan rewards you, including cheaper prices from his clerk Bernard.]] },
[74393] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Umar Hills, Temple Ruins]], h = { [[Mayor Lloyd of Imnesvale needs someone to stop the killings in the Umar Hills.]], [[The trail leads to a ruined temple of Amaunator in the hills.]], [[The Shade Lord hides deep in the temple dungeon; prepare for undead and shadows.]] }, s = [[Mayor Lloyd hires you to stop the murders around Imnesvale.
Investigate the Umar Hills and head to the ruined temple of Amaunator, where shadows have taken over the land.
Work through the temple dungeon and kill the Shade Lord at its heart.
Return to Mayor Lloyd in Imnesvale for his thanks and a reward. Mazzy, who can be met near the temple, may join you.]] },
[74394] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-3]], w = [[De'Arnise Keep]], h = { [[Nalia, in Athkatla, begs for help: trolls have overrun her family's keep.]], [[Open the way through the keep and look for her father, Lord de'Arnise.]], [[The troll leader TorGal holds the keep; bring fire or acid to finish trolls.]] }, s = [[Accept Nalia's request and travel with her to the de'Arnise keep. Captain Arat at the gate explains the situation.
Clear the keep room by room. Trolls only stay dead with fire or acid.
Find and kill the troll leader TorGal. Lord de'Arnise cannot be saved: TorGal has killed him.
Once the keep is cleared, the quest ends. Nalia's future at the keep is uncertain, and her own story continues with her father's funeral. A fighter protagonist can later be offered the keep as a stronghold.]] },
[74395] = { g = [[bg2]], k = [[companion]], o = 0, c = [[any]], w = [[Wilderness, wolfwere encampment]], h = { [[Coran says Safana has been kidnapped by wolfweres camped nearby to the east.]], [[The kidnapping is not what it seems: Safana wants the bounty on your head.]], [[Keep Coran alive in the fight with the wolfwere Lanfear, who wants him for herself.]] }, s = [[Coran tells you that wolfweres have taken Safana and asks you to come to their camp, a short way east. If you refuse, he goes alone; you can still follow.
At the camp, the truth comes out: Safana and the wolfwere Lanfear planned this together, Safana for the bounty on your head, Lanfear to win Coran.
Lanfear kills Safana. Fight Lanfear and her wolfweres, and protect Coran.
Best outcome: Lanfear dies and Coran survives. If Coran is killed, by you or by Lanfear, the quest still ends; a raise spell can bring him back.]] },
[74396] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-3]], w = [[Athkatla, Slums (Planar Sphere) / Umar Hills]], h = { [[The strange metal sphere sunk into the Slums is linked to Valygar's family, and the Cowled Wizards want him.]], [[Only someone of Valygar's bloodline can open the Planar Sphere, so bring him along.]], [[Deep inside the sphere waits Valygar's ancestor Lavok; defeat him to end the curse and claim the sphere.]] }, s = [[The Cowled Wizards ask you to bring them Valygar, who lives in a cabin in the Umar Hills. Talk to him instead and recruit him: he explains that his ancestor Lavok, a necromancer, built the Planar Sphere in the Slums.
With Valygar in the party, enter the sphere. Explore it, deal with its guardians and the trapped prisoners, and find a way to the heart of the sphere.
Confront Lavok, a powerful mage, and defeat him. Expect a fight with a Cowled Wizard and his allies when you come out.
Afterwards Valygar is free of the Cowled Wizards. Keep him in the party or let him go (he waits at his home). The sphere becomes yours to use as a base.]] },
[74397] = { g = [[bg2]], k = [[side]], o = 0, c = [[5]], w = [[Underdark, illithid city]], h = { [[Fellow prisoners in the mind flayer arena hate the illithids even more than you do.]], [[Listen to Simyaz, the githyanki leader: his men can disrupt the mind flayers so you can open the arena door.]], [[The githyanki will teleport away without you, so be ready to fight your own way out of the city.]] }, s = [[Captured by mind flayers in the Underdark, you must fight in their arena. A group of githyanki prisoners led by Simyaz is held there too (the same ones who attacked Saemon's ship, if you met them).
Talk to Simyaz and accept his plan: his men block the illithids' mental power, which lets you open the arena door. You may also kill the githyanki instead, but then you must force the door on your own.
Once out, the githyanki teleport away and leave you behind. Fight carefully through the illithid city: mind flayers stun and drain Intelligence, so use protection from mind attacks and focus them down.
A strange door blocks the way further on; it takes great power to force it. You may meet the githyanki again later.]] },
[74398] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla, Docks (Sea's Bounty)]], h = { [[Travel with Keldorn through Athkatla and an old acquaintance of his will show up.]], [[Vakola blames Keldorn for a betrayal; you will meet him again at the Sea's Bounty in the Docks.]], [[Vakola was a corrupt member of the Order whom Keldorn exposed, and he comes ready to fight.]] }, s = [[With Keldorn in the party, a man named Vakola approaches and accuses him of betrayal. Keldorn denies it.
Later, enter the Sea's Bounty tavern in the Docks District with Keldorn. Vakola is there with his friends. The truth comes out: both served in the Order of the Radiant Heart and Keldorn reported Vakola for taking bribes.
Vakola and his companions attack. Defeat them; the matter ends with Vakola's death.]] },
[74399] = { g = [[bg2]], k = [[main]], o = 52, c = [[5]], w = [[Underdark, Ust Natha]], h = { [[Irenicus fled Spellhold toward the depths; you must follow him below the surface.]], [[In the Underdark, seek out the silver dragon Adalon, who can make you pass for a drow.]], [[Win the trust of the drow of Ust Natha, recover Adalon's stolen eggs and she will guide you to the surface.]] }, s = [[After Spellhold, Irenicus and Bodhi have gone into the Underdark. You reach it either directly from the asylum's depths or by sailing with Saemon (which takes a detour).
In the Underdark, explore carefully (beholders, mind flayers) and find the silver dragon Adalon. The drow stole her eggs; she disguises your party as drow so you can enter the city of Ust Natha.
In Ust Natha, take tasks from the drow leaders to gain rank, keep your disguise and find where the eggs are kept. Recover them and return them to Adalon.
Adalon then shows you the way back to the surface, where the next chapter begins.]] },
[74400] = { g = [[bg2]], k = [[main]], o = 57, c = [[6]], w = [[Forest of Tethir / Athkatla, Graveyard District]], h = { [[Back on the surface, the elves near the exit of the Underdark need your help to reach their city.]], [[Their leader Elhan says Bodhi holds what they need, so return to Athkatla.]], [[Bodhi's lair lies in the catacombs under the Graveyard District; destroy her and bring back what she took.]] }, s = [[Leaving the Underdark, you meet the elven army of Elhan in the forest. Irenicus has sealed off Suldanessellar, and only a magical artifact can reveal the way, but Bodhi has it.
Return to Athkatla and prepare well: Bodhi and her vampires are tough, and she strikes at your party before the final fight. On the way back, you may meet Drizzt, who can join the battle.
Enter Bodhi's lair in the catacombs under the Graveyard District. Fight through her minions, defeat Bodhi and make sure she cannot rise again (destroy her in her coffin).
Recover the artifact and bring it back to Elhan to open the way to the elven city.]] },
[74401] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Windspear Hills, Firkraag's dungeon]], h = { [[The trail of Garren Windspear's kidnapped child leads into the dungeon under the Windspear Hills.]], [[The man who sent you there was a red dragon in disguise, and he waits at the bottom.]], [[You can walk away from Firkraag, or prepare heavy fire protection and fight him for his hoard.]] }, s = [[Following Garren Windspear's quest, go down through the dungeon in the Windspear Hills. At the bottom you meet the true Firkraag, a huge red dragon who toyed with you over an old grudge against Gorion.
He has no more interest in you and leaves one of his servants guarding Garren's child. Defeat the servant and free the child to finish Garren's quest.
You may also challenge Firkraag. This is one of the hardest fights of the game: bring fire resistance, protection from fear, and buffs, and expect his breath and spells. Defeating him gives a large XP reward and a rich hoard.]] },
[74402] = { g = [[bg2]], k = [[side]], o = 0, c = [[6]], w = [[Road from the Forest of Tethir]], h = { [[On the way back to Athkatla from the elves' forest, you may cross paths with a famous drow ranger.]], [[Talk to Drizzt peacefully and tell him of your fight against Bodhi.]], [[If he agrees, he will wait for you in the catacombs under the Graveyard District.]] }, s = [[In chapter 6, while traveling from the Forest of Tethir back to Athkatla, you can be stopped by Drizzt Do'Urden and his companions.
Talk to him without hostility and ask for his help against Bodhi. He agrees to meet you in the catacombs under the Graveyard District.
When you enter Bodhi's lair, Drizzt and his friends appear and fight at your side, which makes the battle much easier.
Attacking Drizzt instead is a very hard fight and costs reputation.]] },
[74403] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-4]], w = [[Athkatla]], h = { [[After the trouble with the Harpers, Jaheira's old tutor Dermin will come to face her.]], [[When Jaheira renounces the Harpers, how you react decides whether she stays.]], [[Support her decision and give her time; urging her on or rushing her makes her leave for good.]] }, s = [[This is part of Jaheira's Harper quest, after the events with Galvarey at Harper Hold. Keep Jaheira in the party and Dermin, her former tutor, appears: he was sent to execute her for the deaths at the Hold.
He does not attack, and Jaheira renounces her life as a Harper.
Choose your words with care. Accept her choice as her own and stay supportive: she remains in the group. If you seem to push her or show impatience, she feels you do not trust her and leaves the party permanently.
Later, the man called Terminsel comes to judge her (see the related quest).]] },
[74404] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-4]], w = [[Athkatla]], h = { [[The stranger who once brought you Jaheira's note will return at the end of her Harper troubles.]], [[Terminsel only wants to know whether Jaheira regrets what she did.]], [[If Jaheira stands firm in her answer, the Harpers close the matter and reward her.]] }, s = [[Final step of Jaheira's Harper quest, after Galvarey and Dermin. Keep Jaheira in the party and Terminsel, the man who brought her note, appears and asks whether she regrets her actions.
The outcome follows how her quest and your relationship went. If she has no regrets, the Harpers consider the matter closed, will not pursue you, and give Jaheira a Harper Pin. Terminsel turns out to be Elminster himself.
If she hesitates, he leaves disappointed, saying her doubt is punishment enough; nothing more happens.]] },
[74405] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-3]], w = [[Athkatla]], h = { [[A chatty gnome selling turnips in Athkatla gets arrested before your eyes.]], [[Jan Jansen's fine is 800 gold, paid to the keeper of the prison.]], [[Short on gold, the jailkeep may lend you part of it; then tell Jan he is free.]] }, s = [[In the streets of Athkatla, the gnome Jan Jansen tries to sell you turnips and is arrested for selling illegal goods. He begs you to pay his 800 gp fine.
Go to the prison and talk to the jailkeep. Pay the fine. If you lack the money, he is so eager to be rid of Jan that he lends you 200 gp, which you should pay back later.
Talk to Jan in his cell to tell him he is free. Take him into the party, or decline and find him later at his home in the Slums.]] },
[74406] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-3]], w = [[Athkatla, Delryn estate]], h = { [[Travel with Anomen for a while and he will receive grave news about his sister.]], [[His father, Lord Cor, wants Anomen to kill the merchant Saerk; the magistrate finds no proof.]], [[Urge Anomen to let the law stand and forgive; this choice decides his future path.]] }, s = [[With Anomen in the party, he learns his sister has been murdered. Go with him to his father's estate. Lord Cor, bitter and drunk, demands that Anomen kill Saerk, a rival merchant he blames.
Anomen refuses and is thrown out. Visit the magistrate Bylanna: there is not enough evidence against Saerk or anyone else.
Advise Anomen to forget the matter and leave vengeance aside. He stays sad but loyal, and this path keeps him on his way to knighthood in the Order of the Radiant Heart (if he passed his test).
If you instead urge him to take revenge, he kills Saerk and turns away from the Order.]] },
[74407] = { g = [[bg2]], k = [[main]], o = 45, c = [[4]], w = [[Brynnlaw / Spellhold]], h = { [[Saemon Havarian's ship takes you to the pirate island of Brynnlaw, near the asylum.]], [[Getting into Spellhold is the challenge; listen to Saemon and to the locals for a way in.]], [[Inside the asylum, find Imoen and face Irenicus; the inmates can help you turn the tables.]] }, s = [[Having paid either Aran Linvail or Bodhi, you sail with the privateer Saemon Havarian to Brynnlaw. Saemon is not to be trusted, but he knows the island.
On Brynnlaw, explore the town and follow the leads Saemon and the locals give you to get yourself admitted into Spellhold.
In the asylum, Irenicus springs his trap: he reveals that Imoen is also a child of Bhaal, takes your soul, and has Bodhi hunt you through the asylum dungeon. Survive its trials and free the inmates.
With their help, drive Irenicus away. He flees into the depths, which begins chapter 5.]] },
[74408] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-4]], w = [[Athkatla, Harper Hold]], h = { [[After the death of Galvarey, the Harpers are not done with Jaheira.]], [[A stranger brings a note: Jaheira has gone alone to Harper Hold, so follow her anyway.]], [[The Harpers at the Hold are a vengeful splinter group; free Jaheira and take her back into the party.]] }, s = [[After the Galvarey incident, Dermin warns Jaheira that the Harpers have ordered her execution and that attacks will grow worse unless she gives herself up.
Soon after, a strange man hands you a note: Jaheira has left for Harper Hold in Athkatla on her own and forbids you to follow.
Go to Harper Hold anyway. Fight the Harpers there: the missing specters on the upper floor show this is only a splinter group seeking revenge.
Find Jaheira and invite her back into the party to continue her quest. If you refuse to take her back, she escapes alone and is lost for good.]] },
[74409] = { g = [[bg2]], k = [[main]], o = 44, c = [[3]], w = [[Athkatla, Graveyard District]], h = { [[If you sided with the vampire Bodhi, finish every task she gives you.]], [[Her last orders strike at the heart of the Shadow Thieves.]], [[Return to Bodhi after her tasks: she reveals the truth about Irenicus and books your passage to Spellhold.]] }, s = [[This is the vampire path of chapter 3. After paying Bodhi, carry out her tasks against the Shadow Thieves, ending with an attack on their guild and the death of the Shadowmaster, Aran Linvail. These are evil acts that hurt your reputation.
Return to Bodhi in her lair in the Graveyard District. She keeps her side of the bargain: Irenicus is her brother, he took you because you are a child of Bhaal, and both he and Imoen were sent to the asylum of Spellhold.
Bodhi wants Irenicus freed for her own goals and has booked your passage to the asylum's island. Head to the Docks to start chapter 4.]] },
[74410] = { g = [[bg2]], k = [[side]], o = 0, c = [[any]], w = [[Unknown]], h = { [[This is only a reminder note about combat training, not a real quest.]], [[No dialog or script of the game is listed as writing it, so it may never appear.]] }, s = [[This journal row only says that Belt reminds you to finish your combat training. No dialog or script is known to add it, so it looks like a leftover from a tutorial.
There is nothing to do and no reward. If it shows up in your journal, you can ignore it.]] },
[74411] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, sewers]], h = { [[A fence named Roger keeps a shop down in the sewers of Athkatla.]], [[Roger is plagued by a sea troll lurking nearby in the sewers.]], [[Kill the troll and finish it with fire or acid so it cannot regenerate, then return to Roger.]] }, s = [[Find Roger the Fence in the Athkatla sewers. He is usually met while chasing Dennis's gong for Vittorio's quest.
He agrees to help (and tell you about the gong) if you kill a sea troll that keeps harassing him.
Search the nearby sewer tunnels for the sea troll. When it falls, finish it with fire or acid damage, or it will get back up.
Return to Roger to report and get what he promised.]] },
[74412] = { g = [[bg2]], k = [[main]], o = 35, c = [[2]], w = [[Athkatla]], h = { [[Imoen was taken to wherever the Cowled Wizards took Irenicus, and you need powerful help to follow.]], [[Gaelan Bayle in the Slums offers aid from the Shadow Thieves, at a very steep price.]], [[Raise the gold through jobs across Athkatla and beyond, then pay the Shadow Thieves or a rival offer.]] }, s = [[You escape Irenicus's dungeon into Waukeen's Promenade in Athkatla and see the Cowled Wizards take Irenicus and Imoen away.
In the Slums, Gaelan Bayle approaches you: his masters, the Shadow Thieves, will help you find Imoen for 20,000 gold.
Explore Athkatla and the lands around it, take on quests and companion requests, and save money. Partway through, a rival offer comes from Bodhi in the Graveyard District, for less gold.
Once you have the sum, pay Gaelan (or Bodhi). This starts chapter 3, where your new patron gives you tasks before booking your passage.]] },
[74413] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-3]], w = [[Umar Hills, Temple Ruins]], h = { [[The Shade Lord's dungeon below the Umar Hills temple ruins holds a captive halfling warrior.]], [[Mazzy Fentan is locked in a cell inside the Shade Lord's lair.]], [[Free her; if you have no room for her, she waits at her home in Trademeet.]] }, s = [[While investigating the disappearances in the Umar Hills, go down into the Shade Lord's dungeon under the temple ruins.
In one of its cells you find Mazzy Fentan, a halfling fighter whose companions fell to the Shade Lord. Open her cell to free her.
This entry is the outcome where you tell her you do not need her help now: she thanks you and returns to her home in Trademeet, where you can recruit her later.
If you take her along instead, she helps you fight the Shade Lord.]] },
[74414] = { g = [[bg2]], k = [[main]], o = 33, c = [[1]], w = [[Irenicus's dungeon]], h = { [[Imoen has freed you; explore the strange dungeon and gather your old friends.]], [[Help the captives and creatures you meet: many of them open the way or give you gear.]], [[The exit lies on the upper level; push through and you will come out in Athkatla.]] }, s = [[You wake in a cage in Irenicus's dungeon, and Imoen frees you. Search the room for gear and look at Jaheira's and Minsc's cells.
Explore the first level: free the djinni with his flask, help the dryads, find the activation stone for the sewage golem so it opens the sealed doors, and find the key for Jaheira's cage. Minsc breaks free on his own.
Other prisoners and experiments, like Rielev, can be talked to or released. Rest when you can.
Go up to the next level, fight the duergar, mephits and other guardians, and reach the exit. You come out in Athkatla in the middle of a battle, which starts chapter 2.]] },
[74415] = { g = [[bg2]], k = [[side]], o = 0, c = [[1-2]], w = [[Irenicus's dungeon / Windspear Hills]], h = { [[Three dryads trapped in Irenicus's dungeon long to be free.]], [[A dwarf named Ilyich, elsewhere in the dungeon, carries their acorns.]], [[Take the acorns from Ilyich and later bring them to the Fairy Queen in the Windspear Hills.]] }, s = [[In Irenicus's dungeon, talk to the three dryads. They ask you to recover their acorns and bring them to the Fairy Queen.
The acorns are carried by the dwarf Ilyich, who guards part of the dungeon with his duergar. Defeat him and take the acorns.
Once you are out and free to travel, go to the Windspear Hills and find the Fairy Queen, Vaelasa. Give her the acorns.
The dryads are freed and leave to replant their trees, and Vaelasa thanks you. You gain experience.]] },
[74416] = { g = [[bg2]], k = [[side]], o = 0, c = [[1]], w = [[Irenicus's dungeon]], h = { [[The djinni Malaaq in Irenicus's dungeon is bound to a flask and guards some of his master's things.]], [[The twin of his flask is kept near his master: in his chambers, or with the dryads or golems.]], [[The dryads hold the flask; bring it to Malaaq to free him.]] }, s = [[Talk to the djinni Malaaq in Irenicus's dungeon. He keeps equipment in storage for Irenicus but cannot give it up while bound to his flask. To free him, you need the twin flask.
Visit the three dryads in the dungeon and get the flask from them.
Return to Malaaq and give it to him. He is freed and, in return, hands over the equipment he was keeping, useful gear for the rest of the dungeon.]] },
[74417] = { g = [[bg2]], k = [[companion]], o = 0, c = [[1]], w = [[Irenicus's dungeon]], h = { [[Jaheira's cage has a magical lock that cannot be picked.]], [[Explore the rest of the dungeon's first level; the key is somewhere there.]], [[Once you have the key, return to the room where you woke up and open her cage.]] }, s = [[Jaheira is locked in a cage in the room where you woke up. Its magical lock cannot be picked.
Explore the first level of the dungeon, fighting its guardians and searching rooms and containers, until you find the key.
Return to her cage and use the key: Jaheira is freed and can join the party.]] },
[74418] = { g = [[bg2]], k = [[companion]], o = 0, c = [[1]], w = [[Irenicus's dungeon]], h = { [[Minsc's cell is welded shut, so there is no key or lock to work on.]], [[Do not waste time searching for a way to open it.]], [[Talk to Minsc again: his rage and Boo are enough to break the cage.]] }, s = [[Minsc is caged in the same room you woke in, and his cell is welded shut.
There is nothing to find. Talk to him: angered by his imprisonment, he bursts out of the cage by himself with Boo's encouragement.
He can then join the party.]] },
[74419] = { g = [[bg2]], k = [[side]], o = 0, c = [[1]], w = [[Irenicus's dungeon]], h = { [[Some doors of the dungeon are magically sealed, and a sewage golem holds the answer.]], [[The golem needs an activation stone before it will go back to its duties.]], [[The stone sits on a table near a tormented man named Rielev.]] }, s = [[Talk to the sewage golem in Irenicus's dungeon. It will open the magically sealed doors of this level if you bring it an activation stone.
Find the room of Rielev, one of Irenicus's tormented experiments, and take the stone from the table near him.
Return to the golem with the stone. It resumes its duties and opens the sealed doors, so you can continue exploring.]] },
[74420] = { g = [[bg2]], k = [[side]], o = 0, c = [[1]], w = [[Irenicus's dungeon]], h = { [[A prisoner named Frennedan is trapped in a glass cage in Irenicus's dungeon.]], [[The key to his cage is in a chest in the main room outside it.]] }, s = [[Talk to Frennedan, held in a glass cage in Irenicus's dungeon, and agree to free him.
Search the chests in the main room next to his prison until you find the key.
Use it on his door to release him.
Freeing him costs nothing and is a small good deed on the way out of the dungeon.]] },
[74421] = { g = [[bg2]], k = [[side]], o = 0, c = [[2]], w = [[Athkatla, Waukeen's Promenade]], h = { [[People who enter the circus tent on Waukeen's Promenade do not come out; the guard lets you in.]], [[Inside, nothing is what it seems; a winged elf trapped in a cage needs a sword held by illusory peasants.]], [[Find and kill Kalah, the gnome illusionist behind it all, to restore the tent.]] }, s = [[Talk to the guard at the circus tent on Waukeen's Promenade and go inside. The tent has become an illusory maze.
Explore it and talk to its strange inhabitants. A caged winged elf asks you for a sword carried by illusory peasants; get it to free her from the illusion. She is Aerie.
Dispel or see through the illusions and work your way to the illusionist, the gnome Kalah. Defeat him: he uses illusions and mirror images, so bring a way to see through them.
With Kalah dead, the tent returns to normal and its victims are freed. Aerie can join the party.]] },
[74422] = { g = [[bg2]], k = [[side]], o = 0, c = [[2]], w = [[Athkatla, Waukeen's Promenade]], h = { [[A little boy cries outside the circus tent on Waukeen's Promenade: his mother is still inside.]], [[You will find her, but changed by the illusionist's magic.]], [[Only the death of Kalah, the gnome illusionist, restores her true form.]] }, s = [[Talk to the lost boy outside the circus tent on Waukeen's Promenade: his mother went into the tent and never came out.
Enter the tent (see the circus tent quest). You find the mother, but she has been transformed like the rest of the circus.
Defeat Kalah, the gnome illusionist. His death breaks the spell: the mother returns to her normal form and leaves at once to rejoin her son.]] },
[74423] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, Slums (Copper Coronet)]], h = { [[The Copper Coronet in the Slums uses slaves as fighters in its pit.]], [[The beastmaster across the arena holds the key to Hendak's cell.]], [[More slaves, children, are held in a dry-docked ship in the east of the Slums, reached through a sewer tunnel.]] }, s = [[In the Copper Coronet inn (Slums), go down to the fighting pit area and talk to the slave Hendak in his cell. Agree to free his people.
Cross the arena to the beastmaster and take his key, by force if needed. Free Hendak and the gladiators; they turn on the inn's owner, Lehtinan, and his guards. Help kill Lehtinan.
Hendak then tells you of more slaves held in a dry-docked ship on the east side of the Slums. Find the tunnel in the sewers that leads from the inn to the slaver compound.
Fight the slavers there and free the children. Report to Hendak, now running the Copper Coronet, for your reward.]] },
[74424] = { g = [[bg2]], k = [[main]], o = 36, c = [[2]], w = [[Athkatla, Slums]], h = { [[Gaelan Bayle, met in the Slums, knows something about Imoen's capture.]], [[His house is on the far east side of the Slums; his price is 20,000 gold.]], [[Once paid, use his key on the secret door just right of the entrance of the thieves' guild.]] }, s = [[Gaelan Bayle approaches you in the Slums and leads you to his house on the far east side of the district.
Inside, he offers the help of a powerful group, the Shadow Thieves, to find Imoen. They would have to cross the Cowled Wizards, so the price is 20,000 gp.
Gather the gold by doing quests around Athkatla and the regions beyond, then return to Gaelan and pay.
He gives you a key. Go to the Shadow Thieves' guild in the Docks District and use the key on the secret entrance immediately to your right as you enter to meet their leader. This starts chapter 3.]] },
[74425] = { g = [[bg2]], k = [[side]], o = 0, c = [[2]], w = [[Athkatla, Docks / Mae'Var's guild house]], h = { [[Renal Bloodscalp of the Shadow Thieves wants a spy inside the guild of his underling Mae'Var.]], [[Do Mae'Var's and Edwin's jobs to earn trust; sparing the traitor Embarl gives you a lead.]], [[Edwin knows about you: get the letter from the strongbox in Mae'Var's quarters and bring it to Renal.]] }, s = [[Renal Bloodscalp, in the Shadow Thieves' guild (Docks), gives you papers and sends you to Gorch at Mae'Var's storefront. Gorch lets you through the back door.
Mae'Var's first task: steal the golden statuette from the temple of Lathander, or the amulet of the Weathermistress of Talos (she takes it off at night).
Then his assistant Edwin, on the third floor, sends you to kill the Cowled Wizard Rayic Gethras (gray house, west Docks; go when his door is open) and to get Marcus's documents at the Sea's Bounty.
Last, Mae'Var orders the death of Embarl at the Sea's Bounty, second floor. Bring back his dagger; sparing him reveals Mae'Var's plot against Renal.
Edwin then gives you the key, or joins you: take the letter from the strongbox in Mae'Var's quarters (second floor) to Renal. Kill Mae'Var as Renal asks, then collect your reward.]] },
[74426] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, Government / Bridge District]], h = { [[Sir Ryan Trawl of the Order of the Radiant Heart wants you to infiltrate the Fallen Paladins.]], [[Their member Reynald de Chatillon, in the Bridge District, wants a Cup that the Order still keeps.]], [[Ask Sir Ryan for Anarg's Cup, use it to reach Anarg, and deal with his group.]] }, s = [[At the Order of the Radiant Heart, Sir Ryan Trawl hires you to find the Fallen Paladins, led by the former knight Anarg, in the Bridge District.
In the Bridge District, find Reynald de Chatillon. He will take you to Anarg if you bring him Anarg's Cup, still held by the Order.
Return to Sir Ryan, who reluctantly gives you the Cup. Hand it to Reynald and follow him to Anarg's hideout.
The Fallen Paladins are a threat: fight Anarg and his men (several warriors at once, be ready). Report to Sir Ryan and return the Cup.
Reward: reputation and the goodwill of the Order.]] },
[74427] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, Bridge District]], h = { [[Lieutenant Aegisfield in the Bridge District investigates the skinner murders and names three witnesses.]], [[Rose remembers a smell and Rampah found a strange leather; the merchant Bel can identify both.]], [[Oak bark and elephant hide point to the local tanner; do not let the lieutenant go there alone.]] }, s = [[Talk to Lieutenant Aegisfield in the Bridge District. He mentions the boy Faraji, the beggar Rampah and the courtesan Rose.
Faraji suspects Missus Cragmoon, a harmless mage: a false lead. Rampah gives you a strange piece of leather. Rose remembers a smell like guril berries.
Show the leather to the merchant Bel: elephant hide. Ask him about the smell: he gives you three samples. Rose picks the oak bark, used for tanning.
The clues point to the tanner Rejiek. If you tell Aegisfield, he goes alone and is killed. Better go to the tannery yourself.
In the tannery, Rejiek and the wizard Vellin Dahn fight you; the mage spirits Rejiek away. Search the place, then report to Aegisfield (or his superiors) to close the case.]] },
[74428] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, Delosar's Inn]], h = { [[A drunk named Vittorio stops you in the street, claiming Captain Dennis owes him money.]], [[Go with Vittorio to the second floor of Delosar's Inn to confront Dennis.]], [[Listen to Dennis before fighting: the debt runs the other way, and you can help him instead.]] }, s = [[Vittorio, a drunken lout, asks for help collecting a debt from Captain Dennis. Go with him to the second floor of Delosar's Inn.
Dennis explains that Vittorio stole his mother's gong. You now choose:
Side with Vittorio and fight Dennis and his men; Vittorio runs off once they are dead.
Let Dennis deal with Vittorio, and Vittorio ends up killed.
Or, the best outcome, offer to recover the gong for Dennis: this starts the gong quest, and Dennis holds Vittorio until you return.]] },
[74429] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, sewers / near Trademeet]], h = { [[Vittorio sold Dennis's gong to Roger, a fence in the Athkatla sewers.]], [[The gong passed from hand to hand: a troll shaman near Trademeet, then an ogre mage nearby.]], [[Drush the ogre mage will trade the gong for any wand of frost.]] }, s = [[Captain Dennis keeps Vittorio while you look for his mother's gong. Find Roger the Fence in the Athkatla sewers; kill a sea troll for him (finish it with fire or acid), and he tells you he sold the gong to the troll shaman Grae.
Travel to the troll mound near Trademeet. Grae is guarded by trolls; bring fire and acid. She sold the gong to Drush, an ogre mage living in a tower nearby.
Drush uses the gong as a shovel and wants a wand of frost for it. Bring him any wand of frost (he mentions a witch named Adratha as a possible source).
Take the smelly gong back to Dennis at Delosar's Inn in Athkatla. He lets Vittorio go and rewards you.]] },
[74430] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, Graveyard / Bridge District]], h = { [[Tirdir, freshly dug out of a grave, was buried alive by three kidnappers.]], [[The gravekeeper Sethle looks the other way; press him about the man in red.]], [[Find the man in red in the Bridge District, follow him into his house and deal with the kidnappers.]] }, s = [[In the Graveyard District, talk to Tirdir, a man buried alive by kidnappers. He gives you a scrap of red cloak from one of them and suspects the gravekeeper.
Question the gravekeeper Sethle: he admits looking the other way and says the man in red can be found in the Bridge District.
In the Bridge District, find the man dressed in red. He flees into a house: follow him inside to the kidnappers' hideout.
Defeat the kidnappers and free their current victim, Lady Elgea. You can also try to collect the ransom for her instead of simply freeing her, a less honorable choice.]] },
[74431] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, Graveyard District / Copper Coronet]], h = { [[At night, the ghost of a halfling boy wanders the graveyard.]], [[Wellyn wants his stuffed bear, Littleman, taken by the thief who killed him.]], [[The thief Llynis has a room at the Copper Coronet; bring the bear back to the ghost.]] }, s = [[Visit the Graveyard District at night and talk to the spirit of Wellyn, a murdered halfling child. He asks for his toy bear, Littleman.
Go to the Copper Coronet in the Slums and find the thief Llynis in one of the rooms. Get the bear from Llynis, by talking or by force.
Return to the graveyard at night and give the bear to Wellyn. His spirit can finally rest. You gain experience.]] },
[74432] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, Graveyard District]], h = { [[Arenthis, a priest of Lathander in the graveyard, seeks a guardian for the orphan Risa.]], [[Someone else in the same district is grieving the loss of a child.]], [[Tell Arenthis about Kamir the paladin, then bring the two together.]] }, s = [[In the Graveyard District, talk to Arenthis, a priest of Lathander caring for the orphan Risa. He needs someone noble to raise her.
Also in the graveyard, talk to Kamir, a paladin mourning the adopted son he failed to protect.
Go back to Arenthis and mention Kamir. Arenthis thinks the paladin would make a fine guardian.
Bring them together: Kamir agrees to raise Risa, and they leave together. This also resolves Kamir's own grief.]] },
[74433] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, Graveyard District]], h = { [[A broken paladin named Kamir mourns his adopted son in the graveyard.]], [[A priest nearby is looking for a guardian for a little orphan girl.]], [[Giving Kamir a child to protect again may be his way to atone.]] }, s = [[Talk to Kamir in the Graveyard District. He failed to protect his adopted son and broke his vow, and is consumed by grief.
This is resolved through the orphan Risa quest: talk to Arenthis, the priest of Lathander nearby, who looks after Risa. Tell him about Kamir.
Bring Kamir and Risa together. The paladin agrees to raise the girl and finds a new purpose.]] },
[74434] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, Temple District]], h = { [[An eyeless priest preaches about the Unseeing Eye in the Temple District.]], [[The established temples are worried about this new cult; ask their priests about it.]], [[The cult's true master hides below the city, in the sewers under the Temple District.]] }, s = [[In the Temple District, you witness an eyeless priest, Gaal, preaching to a crowd about a new god, the Unseeing Eye. This entry only records the first sighting.
To follow it up, talk to the priests of the temples in the district, who want the cult investigated.
The trail leads into the sewers under the Temple District, where the cult worships a beholder. Be ready for a hard fight: beholder rays and many cultists.]] },
[74435] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-3]], w = [[Athkatla, Slums (Jansen home)]], h = { [[Travel with Jan and his cousin Beeloo will call him home to the Slums.]], [[Lissa's daughter is dying; Jan's uncle Gerhardt points you to Lady Jysstev and a being called the Hidden.]], [[The Hidden wants two hunters killed: say you are a 'Seeker' at the Sea's Bounty, then go to the Five Flagons.]] }, s = [[With Jan in the party, his cousin Beeloo says he is needed at home in the Slums. Go there with him: his old love Lissa has come with her sick daughter, Jaella. Talk to Lissa in Jan's old room.
In the basement, uncle Gerhardt says only the Hidden can cure her, and Lady Jysstev, in her Government District estate, can arrange a meeting. You have about ten days.
Convince Lady Jysstev, then go to the sewers under the Copper Coronet to meet the Hidden. He wants two hunters killed.
At the Sea's Bounty (Docks), say you are a 'Seeker'. The innkeep sends you to the Five Flagons (Bridge District), second floor: the hunters are githyanki. Kill them, return to the Hidden, then to Jan.
Jaella is cured, but Lissa goes back to her husband Vaelag. Keep Jan or leave him home. If you are too late, Jaella dies.]] },
[74436] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla, Government District]], h = { [[Keldorn has not seen his family for a long time; take him home before he goes alone.]], [[His wife Maria has been seeing another man, Sir William of Thorpe, who frequents the Mithrest inn.]], [[Urge Keldorn to forgive and reconcile rather than seek justice or vengeance.]] }, s = [[After some time in the party, Keldorn asks to visit his estate in the Government District. Go there with him soon, or he leaves on his own and waits for you at the Radiant Heart headquarters.
At home he learns that Maria has been seeing Sir William of Thorpe. He then wants to confront William at the Mithrest inn in Waukeen's Promenade.
The outcome depends on your advice:
- Urge him to reconcile and blame himself: he talks with Maria, then rejoins you (best outcome).
- Push for the law: Maria and William are jailed, his family leaves him.
- Push for revenge: he kills William and Maria leaves with the children.
- Advise him to stay with his family for good: he leaves the party.]] },
[74437] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Trademeet]], h = { [[With Mazzy in the party, visit her sister Pala in Trademeet.]], [[The love potion came from Wallace, a gnome peddler in the market square, but he did not brew it.]], [[Ask the superior of the temple of Waukeen to search the acolyte Barl's rooms.]] }, s = [[Bring Mazzy to Trademeet: she learns that Pala was poisoned by a love potion bought by her betrothed Danno.
Go to the market square and find Wallace, the gnome peddler. He reveals his new supplier: Barl, an acolyte of the temple of Waukeen in Trademeet.
Talk to the temple superior. He may first ask for a 300 gold donation before he acts. He searches Barl's rooms and finds alchemy gear and a holy symbol of Talona.
Barl attacks: kill him and take the antidote from his body. Pala is cured.
Let Mazzy spend the night with her sister. If you leave without waiting, she stays in Trademeet until you return for her.]] },
[74438] = { g = [[bg2]], k = [[side]], o = 0, c = [[any]], w = [[Unknown]], h = { [[No dialog or script writes this entry: it seems to be unused content.]], [[The only entry speaks of six pieces of King Strohm's burial mask, already reassembled.]] }, s = [[This quest has no known trigger in the game files: no dialog or script writes its journal entry, so it is most likely cut content and cannot normally be started.
Its single entry says the six pieces of King Strohm's burial mask were found and put back together, without saying what the mask is for.
If it appears in your journal, a mod probably added it; check that mod's own documentation.]] },
[74439] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Athkatla, Mae'Var's guildhall]], h = { [[A thief who kills Mae'Var for Renal Bloodscalp is given Mae'Var's guildhall to run.]], [[Visit the guild every five days or so, assign your thieves and always pay the quotamaster.]], [[When pickpockets steal from the guild, docking everyone's pay is the safest answer; be wary of Ama.]] }, s = [[Stronghold for thieves: do Renal Bloodscalp's tasks and kill Mae'Var. Renal then gives you Mae'Var's guildhall.
Go there and talk to Jariel: each week you choose your thieves' activities and their risk, then collect the profit. Pay the quotamaster every five days or so, or the guild is shut down (Renal can reinstate you for a high price).
Events:
- Ama asks you to be a decoy for an ambush in Waukeen's Promenade at night. It is a trap set in Mae'Var's name: be ready to fight. You may then dismiss Lathan, who vouched for her.
- One of Kretor's pickpockets steals from the guild. Dock all their pay: the thief is dealt with. Killing one is a gamble; killing all or doing nothing makes Kretor quit.]] },
[74440] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla, Graveyard District]], h = { [[Keep Edwin in the party: he will remember an old tale about a Nether Scroll.]], [[The scroll is said to lie in one of the tombs of the Graveyard District.]], [[Search the tombs beneath the Graveyard District with Edwin and let him study what you find.]] }, s = [[After some time in Athkatla with Edwin, he mentions the Nether Scroll, possibly hidden in a tomb of the Graveyard District.
Explore the tombs under the Graveyard District with Edwin in the party and search the containers until you find the Nether Scroll.
Edwin studies it. The result does not go as he planned: the scroll changes him, which leads to the Red Wizard Degardan quest (Edwin is being hunted by the Red Wizards?).
There is no other reward than the story that follows.]] },
[74441] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla]], h = { [[This follows the Nether Scroll: a Red Wizard named Degardan comes looking for Edwin.]], [[Cover for Edwin the first time you meet Degardan.]], [[Keep travelling with Edwin: Degardan returns and can undo the scroll's effect.]] }, s = [[After Edwin has been changed by the Nether Scroll, the Red Wizard Degardan approaches the party in Athkatla, looking for Edwin, who has a price on his head in Thay.
Cover for Edwin and send Degardan away.
Keep Edwin in the party. Later Degardan comes back and his magic turns Edwin back to his true form. As soon as he is exposed, Edwin attacks him: help kill Degardan.
Edwin is himself again; why the Red Wizards hunt him stays a mystery.]] },
[74442] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, Bridge District]], h = { [[A playhouse lies beneath the Five Flagons inn in the Bridge District.]], [[Go backstage in the playhouse and speak to Raelis Shai.]] }, s = [[Enter the Five Flagons inn in the Bridge District and go down to the playhouse beneath it. Watch or skip the play, then go backstage.
Talk to Raelis Shai, the head of the troupe. She asks for help: the bard Haer'Dalis is held by the wizard Mekrath, along with a gem she wants back.
Accept to start the quest Rescue Haer'Dalis and his gem from Mekrath. Raelis offers either the playhouse deed (useful for a bard) or 1,000 gold as payment.]] },
[74443] = { g = [[bg2]], k = [[side]], o = 0, c = [[1]], w = [[Irenicus's Dungeon]], h = { [[In Irenicus's dungeon, a ruined man floats in a tank, kept alive against his will.]], [[Talk to Rielev and agree to end his suffering by shutting down the device.]] }, s = [[Explore Irenicus's dungeon at the start of the game. In one of the laboratory rooms you find Rielev, floating in a life support tank.
Talk to him: he begs to be released. Agree and shut down the device.
Rielev dies in peace. Take the crystal that powered the tank: he says it can activate other servants kept in similar devices, which helps you elsewhere in the dungeon.]] },
[74444] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Athkatla, Five Flagons playhouse]], h = { [[Raelis Shai, backstage in the Five Flagons playhouse, wants Haer'Dalis and a gem back from Mekrath.]], [[The wizard Mekrath keeps tieflings as servants; Haer'Dalis is one of them.]], [[Bring both Haer'Dalis and the gem back to Raelis to earn the playhouse deed or gold.]] }, s = [[Accept Raelis Shai's request in the playhouse beneath the Five Flagons inn (Bridge District).
Go to the lair of the wizard Mekrath. Haer'Dalis serves him under duress. Expect a hard fight against Mekrath and his summoned guardians; prepare magic defences.
Free Haer'Dalis (he can join the party) and take the gem.
Return to Raelis: choose the playhouse deed (a stronghold for bards) or 1,000 gold.
The journal also records a selfish outcome where you take her reward without helping her.]] },
[74445] = { g = [[bg2]], k = [[main]], o = 41, c = [[3]], w = [[Athkatla, Docks and Graveyard District]], h = { [[Gaelan's gold buys an audience with Aran Linvail, who wants favours before he helps you find Imoen.]], [[Guard the warehouse with Mook at night, then pose as a recruit on the top floor of the Five Flagons.]], [[The rival guild hides in the tombs under the Graveyard District; bring Aran's stakes.]] }, s = [[Shadow Thieves path of chapter 3.
1. Aran Linvail (Docks) sends you to the docks at night to find Mook near a warehouse. A stranger kills her and fights you, then flees as mist: a vampire. Report to Aran in the morning.
2. Go to the top floor of the Five Flagons inn (Bridge District). Pose as a recruit with the defectors Jaylos and Caehan, then deal with their contact Gracen. You learn the rival guild is in the Graveyard District.
3. Aran names the leader, the vampire Bodhi, and gives you wooden stakes. In the tombs under the Graveyard District, a mage and his golem open the blue doors north of the spider nest. Clear the vampire lair; bring Protection from Evil and restoration magic against level drain. Bodhi escapes.
4. Report to Aran: he reveals where Imoen is held and arranges a ship to take you there.]] },
[74446] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, Docks District]], h = { [[A poisoned man named Renfeld stumbles around the Docks District asking for help.]], [[His friend Rylock waits in front of a building in the southwest of the Docks.]], [[Lead Renfeld there quickly, or he dies on the way.]] }, s = [[In the Docks District, talk to Renfeld, a poisoned man, and agree to take him to his friends.
Walk him to the building in the southwest part of the district, where Rylock stands at the door. Do not waste time on the way.
If Renfeld arrives alive, Rylock is glad to see him. If he died on the way, Rylock still gives you a small reward.
The building is a Harper stronghold: soon after, Xzar approaches you, which starts Find out what happened to Montaron.]] },
[74447] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, Docks District, Harper Hold]], h = { [[After delivering Renfeld, Xzar asks you to find out what the Harpers did to Montaron.]], [[Rylock lets you in once you clear the creatures in the mage Prebek's house, in the centre of the district.]], [[The upstairs guardians spare those wearing a Harper pin; look up, not down, for Montaron.]] }, s = [[Xzar says Montaron sneaked into the Harper building and never came out. Talk to Rylock at the door.
As a test, go to Prebek's small house in the centre of the Docks District, kill the creatures inside, then report back. You may enter the Harper Hold, but only the ground floor.
The upper floor has dangerous guardians. Find a Harper pin inside the hold and wear it to pass them.
Upstairs, a caged bird is said to be Montaron. Freeing it is a Harper trap: the bird is an assassin sent for Xzar, a former Zhentarim.
Montaron's real fate stays unknown. This leads into Jaheira's Harper troubles later.]] },
[74448] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla, Docks District, Harper Hold]], h = { [[With Jaheira in the party, the Harpers start to take an unhealthy interest in you.]], [[Dermin, Jaheira's old mentor, and the Harper Galvarey are not what they seem.]], [[Follow Jaheira's quest to the end at the Harper Hold and expose Galvarey.]] }, s = [[This is the end of Jaheira's Harper quest, which starts after she has been in the party for a while.
Dermin, her former mentor, approaches her; the Harper Galvarey then accuses you of being a danger because you are a child of Bhaal.
Follow the leads Jaheira receives and go to the Harper Hold in the Docks District. There the plot comes out: Galvarey is an opportunist using his rank for power, and Dermin was his accomplice. Fight Galvarey and his allies.
The quest closes with this entry; whether other Harpers keep pursuing Jaheira is left open.]] },
[74449] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla, Slums]], h = { [[A talkative gnome in trouble with the city guard can become a companion.]], [[If you did not take Jan Jansen along, look for him at his family home in the Slums.]] }, s = [[In Athkatla you meet Jan Jansen, a gnome con artist being questioned by the authorities. Talk your way through the scene so he gets out of trouble.
If you do not invite him into the party at once, he goes home: the Jansen family house in the Slums, where he claims to sell turnips.
Visit the house any time and talk to Jan to recruit him. His family and his personal quests start from there.]] },
[74450] = { g = [[bg2]], k = [[companion]], o = 0, c = [[1-2]], w = [[Irenicus's Dungeon, then Athkatla]], h = { [[You refused the thief Yoshimo in Irenicus's dungeon, but he escapes too.]], [[Once outside, look for him in a tavern close to the dungeon exit.]] }, s = [[In Irenicus's dungeon you met Yoshimo and did not let him join. He finds his own way out.
After you escape to Waukeen's Promenade, look for him in a nearby tavern and talk to him: he still offers to join.
Think twice before relying on him for the long term; his story ties into the main plot.]] },
[74451] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla, Government District]], h = { [[This records how Keldorn's family crisis ended in reconciliation.]], [[If he left the party, look for him at his estate in the Government District.]] }, s = [[This follows Keldorn wishes to visit his wife and family, when he decides the fault is his and reconciles with Maria.
- If you told him to leave and rebuild his family, he leaves the party. Depending on the dialog, he may be found again at his estate in the Government District.
- If he promises that his mission with you is his last before resigning from the Order, Maria accepts and he stays with you: the best outcome for keeping him.]] },
[74452] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla, Waukeen's Promenade]], h = { [[This is a bad ending of Keldorn's family quest.]], [[Do not turn the meeting with Sir William into a fight you start: Keldorn's honour sides with him.]] }, s = [[During Keldorn's family quest, the confrontation with Sir William of Thorpe went wrong: Keldorn's sense of justice made him defend William, and he died.
Keldorn is lost for good. To avoid this, reload before the meeting and steer him towards reconciliation with Maria, or leave the matter to the law instead of attacking William yourself.]] },
[74453] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-3]], w = [[Athkatla, Temple District]], h = { [[A paladin of the Radiant Heart searches the sewers under the Temple District for the same cult as you.]], [[After the cult business, find Keldorn at the Radiant Heart headquarters in the Temple District.]] }, s = [[In the sewers beneath the Temple District, while investigating the cult, you meet Sir Keldorn, a paladin of the Most Noble Order of the Radiant Heart.
If you do not take him along at once, he goes back to the Order.
When the cult matter is settled, or whenever you want him, go to the Radiant Heart building in the Temple District and talk to Keldorn to recruit him.]] },
[74454] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Trademeet and the Druid Grove]], h = { [[Flydian at the City Gates asks for help for Trademeet, besieged by animals; druids are suspected.]], [[Lord Logan Coprith wants you to talk to the druid Cernd, held in the jail beneath the mayor's house.]], [[Faldorn rules the grove south of town and can only be beaten in a druid's challenge: Cernd, Jaheira or a druid hero.]] }, s = [[Agree to help Flydian, then travel to Trademeet, southeast of Athkatla. Be polite to the militia captain at the gate.
See High Merchant Lord Logan Coprith. He asks you to talk to the druid Cernd, jailed in the basement of the mayor's house. Cernd suspects the grove south of town and can join you.
In the Druid Grove, a druid tells you that the Shadow Druid Faldorn controls it and is bound to the land: she is invulnerable unless challenged by a druid.
Challenge her with Cernd, Jaheira or your own druid. Win the duel: the attacks stop and Logan rewards you. A druid hero is also offered the grove as a stronghold.
Evil option: Lord Khellon Menold gives you poison for the druids' font; kill the druids for him instead.]] },
[74455] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Windspear Hills]], h = { [[The dragon Firkraag can offer a deal instead of a fight.]], [[He wants the deed to the Windspear Hills, held by Garren Windspear.]], [[Take the deed from Garren, by force if needed, and bring it to Firkraag's lair.]] }, s = [[Evil option in the Windspear Hills. In Firkraag's lair, accept the red dragon's deal instead of fighting him.
He wants the deed to the Windspear Hills. Garren Windspear, whose home is in the Windspear Hills, has it. Garren will not hand it over willingly: take it by force.
Return the deed to Firkraag in his lair to finish the task (see Firkraag's task completed). Expect to lose reputation for siding with the dragon.]] },
[74456] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Windspear Hills, Firkraag's lair]], h = { [[This closes the deal with the dragon Firkraag.]], [[Hand him the Windspear deed in his lair to get your reward.]] }, s = [[After taking the deed to the Windspear Hills from Garren Windspear, go back to Firkraag's lair and give it to him.
He rewards you with a magical cloak and tells you to leave.
Note: a paladin of the Radiant Heart is later asked to slay Firkraag for his Holy Avenger; you can still return to fight him.]] },
[74457] = { g = [[bg2]], k = [[side]], o = 0, c = [[4]], w = [[Brynnlaw]], h = { [[On the pirate isle, the courtesan Ginia is forced to serve because Chremy holds her brother.]], [[Calahan, a smuggler near the docks, can take Ginia and her brother off the isle for a price.]], [[Pay Calahan and deal with Chremy near the inn, then tell Ginia.]] }, s = [[In Brynnlaw, talk to Ginia: Desharik took over the isle, and Chremy keeps her brother captive to force her to work as a courtesan. Agree to help.
Find the smuggler Calahan near the docks and pay him 200 gold to take Ginia and her brother away.
Find Chremy near the inn and kill him, so he cannot interfere.
Return to Ginia once both are done: she is overjoyed. If you kill Chremy but refuse to pay Calahan, she stays stuck on the isle.]] },
[74458] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Athkatla, Docks District]], h = { [[A golden skull in the Docks District promises wealth if you restore its body.]], [[Its arms, legs and torso lie scattered in tombs around the city.]], [[Think twice: the skull is a lich, and restoring it means a very hard fight.]] }, s = [[In the Docks District you meet a talking golden skull, Kangaxx, who promises wealth and power if you lift his curse and give him back his body.
Search the tombs of the city for his arms, legs and torso, then bring them to the skull.
Once whole, he reforms as a lich and attacks at once with powerful spells. Only accept if your party is ready for a high-level magic fight; otherwise simply leave the skull alone.
The exact locations of the body parts are not recorded in the journal.]] },
[74459] = { g = [[bg2]], k = [[main]], o = 58, c = [[6]], w = [[Elven forest, then Athkatla]], h = { [[Elhan needs the Rhynn Lanthorn to reveal the hidden city of Suldanessellar.]], [[Someone powerful who serves Irenicus stole it; you know her old lair in Athkatla.]], [[Return to the tombs under Athkatla's Graveyard District and take the Lanthorn from Bodhi.]] }, s = [[Chapter 6. After the Underdark, Elhan explains that Irenicus hid Suldanessellar behind illusions. Only the Rhynn Lanthorn can open the way.
Bodhi stole it. Travel back to Athkatla and enter her lair in the tombs beneath the Graveyard District. Bring Protection from Evil, stakes and level drain protection; kill Bodhi for good in her coffin chamber and take the Lanthorn.
Return to Elhan in the elven forest. The Lanthorn guides you into Suldanessellar while his elves hold back the drow. Inside, look for the high priestess Demin.
Some journal entries list panes of the Lanthorn with riddles; they seem to come from unfinished content, the Lanthorn itself is what opens the city.]] },
[74460] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Trademeet]], h = { [[The militia captain at Trademeet's gate is very wary of strangers.]], [[Stay calm with her and ask what is wrong: it leads to Animal trouble in Trademeet.]] }, s = [[You arrived in Trademeet without being sent by Flydian, and the militia captain greeted you with hostility.
Do not fight her. Talk to her calmly and offer help: the town suffers animal attacks blamed on druids. She sends you to High Merchant Lord Logan Coprith, which starts the quest Animal trouble in Trademeet.]] },
[74461] = { g = [[bg2]], k = [[side]], o = 0, c = [[5]], w = [[Ust Natha]], h = { [[In the drow city, a haughty drow female gives you an order you had better not refuse.]], [[A sect of Ghaunadaur worshippers hides in the southeastern corner of Ust Natha.]] }, s = [[While disguised as a drow in Ust Natha, a commanding drow female orders you to destroy a sect of Ghaunadaur worshippers.
Go to the southeastern corner of the city, find the hidden sect and kill its members.
Report back: she gives no reward beyond letting you live. Refusing would likely make things worse for your disguise.]] },
[74462] = { g = [[bg2]], k = [[side]], o = 0, c = [[5]], w = [[Ust Natha]], h = { [[A drow named Visaj tells a story about Jarlaxle and a magical rope.]], [[Nothing in this affair is as it is told; expect to end up working for Jarlaxle.]], [[Jarlaxle wants gems from the lich Deirex's tower, and he has his own score with House Jae'llat.]] }, s = [[This quest does not seem reachable in a normal game: Jarlaxle does not appear to be met in an unmodded Shadows of Amn, so it is probably cut content or comes from a mod.
According to the journal: Visaj claims he stole a rope from Jarlaxle that protects against imprisonment, letting you loot the lich Deirex's home. It is a trap: you are forced into Jarlaxle's service and must bring back gems from the lich's tower within one day.
The gems really belong to House Jae'llat, which refused to pay Jarlaxle. You gain access to two drow dwellings, and the rope takes you back.]] },
[74463] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Athkatla, Temple District (Radiant Heart)]], h = { [[A paladin hero is given a place in the Order of the Radiant Heart, with duties to fulfil.]], [[Rush to the Umar Hills for the besieged knights; in Imnesvale, question everyone before siding with Baron Metrich.]], [[Use Detect Evil on the baron and on whoever comes for Tyrianna; the last task is Firkraag's Holy Avenger.]] }, s = [[Paladin stronghold, in the Radiant Heart building of the Temple District.
1. Go at once to the far end of the Umar Hills and save the three besieged knights. Every lost knight weighs on the Order.
2. Baron Metrich wants squatters removed; meet at the Imnesvale tavern. Talk to Brunson, Moreno and Pardo: they are farmers and the baron lied. Refuse him and defend the farmers to earn the Order's approval.
3. Guard young Tyrianna Morningale in a safe house until her godfather Hurgis Baltezan arrives. A fake Hurgis comes first: detect his evil and stop him. The real one comes later.
4. Final task: slay the red dragon Firkraag in the Windspear Hills, take the Holy Avenger and report to Sir William Reirrac.
Failing badly gets you expelled from the Order.]] },
[74464] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Athkatla, Temple District]], h = { [[A cleric hero joins the temple of Lathander, Helm or Talos and must advise the faithful.]], [[Each answer is judged by your god: Lathander values compassion, Helm duty, Talos destruction.]], [[The last task sets the temples of Lathander and Talos against each other; your god decides your side.]] }, s = [[Cleric stronghold, given by the temple of your faith in the Temple District. Talk to your acolyte (Lara for Lathander, Byron for Helm, Vilon for Talos), then answer the faithful who come to you.
- Glinden, betrayed husband: Lathander: release his wife from her vows. Helm: remind her of her duty. Talos: tell him to kill her.
- Ti'Vael, a killer: Lathander: make amends to the family. Helm: turn himself in. Talos: kill the witnesses.
- Rania, losing her faith: Lathander: take time to reflect. Helm: stress her duty. Talos: kill her.
- Cotirso's challenge: Lathander: calmly let him have it. Helm: accept the duel. Talos: kill or frame him (Inspector Ardis pays for names).
Final task: Helm stops the war between the two temples; Lathander raids the temple of Talos; Talos attacks Lathander's temple. Bad answers can get you cast out.]] },
[74465] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Athkatla, Slums, Planar Sphere]], h = { [[After the Planar Sphere quest, the Cowled Wizards offer a mage hero the sphere as a base.]], [[Guide your three apprentices carefully, and find a way home for the Solamnic Knights.]], [[Teos sends you after Lord Ketlaar Argrim at the Crooked Crane; refusing costs you the sphere.]] }, s = [[Mage stronghold. After clearing the Planar Sphere in the Slums, accept the Cowled Wizards' offer: the sphere is yours if you accept their scrutiny. Teos is your contact.
- Apprentices: Teos gives you three. Instruct them each week and they craft magic items for you; keep them alive until they graduate.
- Solamnic Knights: they want to go home. Pay Ribald at the Adventurer Mart 9,000 gold to send a mage who teleports them home, or ask the prelate of the Radiant Heart to host them.
- A false summons from Teos is an ambush by an Argrim fanatic. Teos then asks you to deal with Lord Ketlaar Argrim at the Crooked Crane, near the City Gates, using a rune of imprisonment. Do it to be free of service; refusing bars you from the sphere.]] },
[74467] = { g = [[bg2]], k = [[side]], o = 0, c = [[5]], w = [[Underdark]], h = { [[A duergar in the Underdark talks about a mage trapped by an Imprisonment spell.]], [[It happened in a cavern north of the duergar.]], [[Cast Freedom, from a spell or a scroll, in that cavern to release the mage.]] }, s = [[In the Underdark, talk to a duergar: a mage digging for a treasure or artifact was attacked and trapped by an Imprisonment spell in a cavern to the north.
Get a Freedom spell or scroll. Go to that cavern and cast it there.
The mage, Vithal, is released, which starts A mage's proposal.]] },
[74468] = { g = [[bg2]], k = [[side]], o = 0, c = [[5]], w = [[Underdark, svirfneblin village]], h = { [[Vithal, the mage you freed, lost his book of rituals; he blames the svirfneblin.]], [[The book is with the innkeeper of the svirfneblin village to the north.]], [[Pay the innkeeper, or visit him in drow form, then guard Vithal while he opens his gates.]] }, s = [[After freeing Vithal from his Imprisonment, he asks for his book of rituals, which he thinks the svirfneblin took.
Go to the svirfneblin village north of his cavern and find the innkeeper. He wants a 300 gold finder's fee. If you come back under Adalon's drow illusion, he hands it over for free.
Bring the book to Vithal. He opens gates to other planes in search of treasure: kill the guardians that come through.
You receive a share of the magic items. You can demand more, and get it.]] },
[74469] = { g = [[bg2]], k = [[side]], o = 0, c = [[5]], w = [[Underdark]], h = { [[A strange crystal in the Underdark holds people trapped inside it.]], [[The first beings you release have been conscious for too long and may be mad.]] }, s = [[In the Underdark you find a crystal trap that imprisons people. Release its prisoners one at a time.
The first ones are men driven mad by their long confinement. One may simply rave; another attacks you, so be ready to fight.
Keep releasing the others: this continues in Victims of imprisonment.]] },
[74470] = { g = [[bg2]], k = [[side]], o = 0, c = [[5]], w = [[Underdark]], h = { [[The crystal holds more prisoners, and not all of them are friendly.]], [[Before each release, prepare for a fight: a githyanki and even a lich are inside.]], [[One sane adventurer gives useful directions about kuo-toa to the east and a drow city to the north.]] }, s = [[Continue releasing the beings trapped in the Underdark crystal.
- A man whose mind you restore thanks you, or refuses to pay and has to be persuaded.
- A githyanki attacks at once.
- A lich comes out: buff the party before this release and expect a hard magic fight.
- A sane adventurer, lost from his drow-fighting group, leaves to find them. He may tell you that kuo-toa guard a bridge to the east and that a drow city lies to the north. If he is rude, you can fight him.
The crystal also holds a svirfneblin child (see Victims of imprisonment: Svirfneblin son).]] },
[74471] = { g = [[bg2]], k = [[side]], o = 0, c = [[5]], w = [[Underdark, svirfneblin village]], h = { [[One prisoner of the Underdark crystal is Bedlen, son of the shopkeeper Therndle Daglefodd.]], [[Tell Therndle in his village that you saved his son.]], [[Visit Therndle in the same appearance you had when you freed the boy, drow form or your own face.]] }, s = [[Free Bedlen Daglefodd from the crystal trap; he runs home to the svirfneblin village.
Go to his father Therndle, a shopkeeper in the village, and tell him.
Look the same as when you freed the boy: if you saved him as a drow, come back in drow form; if you saved him with your own face, come without the illusion. If your looks differ, Therndle may not believe you.
If he believes you, he gives a generous reward.
If Bedlen died and you bring news of his body, Therndle may suspect you and the whole village attacks.]] },
[74472] = { g = [[bg2]], k = [[side]], o = 0, c = [[5]], w = [[Underdark]], h = { [[A svirfneblin child freed from the crystal ran home to his father.]], [[Go to the svirfneblin village and find his father, the shopkeeper Therndle Daglefodd.]] }, s = [[You freed a svirfneblin child, Bedlen, from the Underdark crystal. He has gone home and told you to do the same.
Travel to the svirfneblin village and talk to his father Therndle Daglefodd, a shopkeeper there, to claim your reward. Keep the same look (drow form or not) as when you freed him. See Victims of imprisonment: Svirfneblin son.]] },
[74473] = { g = [[bg2]], k = [[side]], o = 0, c = [[5]], w = [[Underdark, svirfneblin village]], h = { [[Therndle Daglefodd, a svirfneblin shopkeeper, has lost his son Bedlen.]], [[Something in the Underdark imprisons people; a strange crystal may hold the boy.]] }, s = [[In the svirfneblin village, the shopkeeper Therndle Daglefodd says his son Bedlen has been missing for days.
There is no clue, but the boy angered some drow and is trapped in the crystal found elsewhere in the Underdark. Release the crystal's prisoners until Bedlen comes out, then return to Therndle for a reward.]] },
[74474] = { g = [[bg2]], k = [[side]], o = 0, c = [[5]], w = [[Underdark, svirfneblin village]], h = { [[This is the dark ending of the missing svirfneblin son.]], [[Bedlen died at your hands; you can still tell Therndle that you found his body.]] }, s = [[This entry records an evil outcome: you killed Bedlen Daglefodd after releasing him from the crystal, then told his father Therndle you found his body in the tunnels, keeping your part secret.
Therndle is grateful to know his son's fate. To get the good outcome and a reward instead, let Bedlen go home alive.]] },
[74475] = { g = [[bg2]], k = [[side]], o = 0, c = [[5]], w = [[Underdark, svirfneblin village]], h = { [[The svirfneblin guards let you through their village if you behave.]], [[Speak with the village lord first, as the guard captain asks.]] }, s = [[In the Underdark, the captain of the svirfneblin guards stops you at their small village. He lets you pass on one condition: speak with their leader first.
Go to Goldander Blackenrock, lord of the village. He has a task for you and a way into the drow city: see Svirfneblin village concerns.]] },
[74476] = { g = [[bg2]], k = [[main]], o = 53, c = [[5]], w = [[Underdark, svirfneblin village]], h = { [[Goldander Blackenrock knows how to reach the drow city: through Adalon, at the foot of the great staircase.]], [[He wants a creature in a lower cavern killed first.]], [[After the kill, read his scroll in that cavern to collapse it, then return for the glow stone.]] }, s = [[Talk to Goldander Blackenrock, lord of the svirfneblin village. He says Adalon, a powerful being at the base of the great staircase, can get you into the drow city. Her lair is hidden in magical darkness.
His price: kill the creature his miners unearthed in a lower cavern, then collapse that cavern with the stone shape scroll he gives you. Prepare well, it is a tough fight.
Return to Goldander: he gives you a magic item and the glow stone that lets you pass the darkness to Adalon. A thief can also pickpocket the stone.
The journal also records an evil path where you slaughter the svirfneblin instead.]] },
[74477] = { g = [[bg2]], k = [[side]], o = 0, c = [[5]], w = [[Underdark]], h = { [[The githyanki you met as captives of the mind flayers did not stay where you left them.]], [[After escaping the illithid city, look for them resting in a cavern of the Underdark.]], [[They want the silver sword back and will not be talked out of a fight.]] }, s = [[After surviving the illithid city in the Underdark, explore the caverns until you find the githyanki party resting there, the same group that was held captive with you (and that attacked Saemon's ship if you met them before).
Talk to their leader. Whatever you answer, they demand the silver sword they say was stolen from them and attack.
Prepare for a hard fight against several githyanki warriors and casters, then loot them. The journal closes once they are dead.]] },
[74478] = { g = [[bg2]], k = [[side]], o = 0, c = [[7]], w = [[Suldanessellar]], h = { [[A locked elven box in Suldanessellar opens only if its five runes are pressed in the right order.]], [[The Priest's Stone in the room above holds the clue; the lid says the Natural Order shall prevail.]], [[Start with Corellon, then Rillifane, and finish with the rune of Suldanessellar.]] }, s = [[Examine the elven puzzle box found in a building of Suldanessellar. Read the Priest's Stone in the room above for the clue.
A wrong rune fires an acid dart at you and resets the box, so press them in this order:
1. Corellon Larethian.
2. Rillifane.
3. The elven symbol for water.
4. The Tree of Life.
5. The rune of Suldanessellar.
The box opens and gives you the talisman of Rillifane.]] },
[74479] = { g = [[bg2]], k = [[side]], o = 0, c = [[4]], w = [[Spellhold, dungeon below the asylum]], h = { [[The vampire you just struck down was a victim of Bodhi, and his soul begs for a true death.]], [[A kobold shaman who fears the vampire keeps a wooden stake in a secret room near the Tome of Madness.]], [[Use the stake on the body in Dace's coffin; his hand is half of the key out of this place.]] }, s = [[In the dungeon maze below Spellhold, after you defeat the vampire Dace Sontan, his tormented spirit appears. Agree to help him.
Find the secret room near the Tome of Madness, where the kobold shaman worships a crystal shard. Take the wooden stake from him (by force if needed).
Return to Dace's coffin and use the stake on his body: his soul is freed.
Take Dace's hand from the coffin. Together with the crystal, it is the key you need to open the way out of this level, so do not skip it.]] },
[74480] = { g = [[bg2]], k = [[side]], o = 0, c = [[5]], w = [[Underdark, Ust Natha]], h = { [[A captive aboleth in a tank in Ust Natha can read your mind and sees through your disguise.]], [[It wants the brain of the priestess Qilue, who lives in the Female Fighters' Society.]], [[Her room is behind the second door from the bottom; strike fast, take the brain, bring it back.]] }, s = [[In the drow city of Ust Natha, talk to the aboleth kept in a tank. It threatens to reveal that you are a surfacer unless you obey. Agree (refusing means it alerts the whole city).
Go to the Female Fighters' Society and enter the second door from the bottom. Kill the priestess Qilue quickly and take her brain from the body.
Return to the aboleth and hand it over. It keeps your secret, and the party gains experience (10,000 XP). There is no other reward.]] },
[74481] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-3]], w = [[Athkatla, Slums]], h = { [[Two kidnappers, Camitis and Reti, held Lady Elgea for ransom, and someone is still coming to pay.]], [[A note found on the kidnappers names the meeting place: in front of the Copper Coronet.]], [[Pose as the kidnapper to Welther to take the ransom; this is the selfish way out.]] }, s = [[This entry follows the kidnapping of Lady Elgea by Camitis and Reti in the Slums. After dealing with the kidnappers, keep their note.
Go to the front of the Copper Coronet and talk to Welther, Lady Elgea's servant. Show the note and claim to be the kidnapper.
He hands over the agreed ransom (an item, not gold) and you tell him where the lady is.
Welther now knows the house where she is held, so it is wise not to go back there.]] },
[74482] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-7 (or ToB)]], w = [[Watcher's Keep, maze level]], h = { [[A friendly cambion in the maze wants to gamble with you rather than fight.]], [[He stakes a gem against your holy symbol of Helm, decided by draws from a deck of many things.]], [[Whether you win or lose the game, refuse to leave without the symbol and expect a fight if he resists.]] }, s = [[In the maze level of Watcher's Keep, meet the cambion and his retinue. Talk instead of attacking.
He offers a game with his deck of many things: your holy symbol of Helm (his way out) against a gem he found. Each draw can bring good or bad effects.
If he wins his freedom, he keeps his word: he returns the holy symbol and gives you the gem anyway.
If he will not let you leave with the symbol, the matter ends in combat with him and his followers.]] },
[74483] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-7 (or ToB)]], w = [[Watcher's Keep, maze level]], h = { [[Two fiends of the Blood War are trapped in the maze, each wanting the other dead.]], [[The balor Tahazzar and the pit fiend Ka'rashur each ask you to bring back the other's heart.]], [[Pick one side, kill the other fiend, and return with its heart for the reward.]] }, s = [[In the maze of Watcher's Keep, you can meet the tanar'ri balor Tahazzar and the baatezu pit fiend Ka'rashur in different parts of the level.
Accept the job from one of them: find the other fiend and destroy it, then cut out its heart.
The target is a very powerful fiend; prepare protections against fire and high-level magic.
Return the heart to your employer. Surprisingly, the fiend keeps its word and gives you its material reward.]] },
[74484] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-7 (or ToB)]], w = [[Watcher's Keep, temple level]], h = { [[The mirror portal in the middle of the temple opens with a ritual at the altar.]], [[The archivist's ghost points you to the forgetful old priest, long dead somewhere in the temple.]], [[The chapter and verse are woven into the old priest's cloak sleeve: bell, bell, candle, book, bell.]] }, s = [[On the first level of Watcher's Keep, gather the ritual items found around the temple (a bell, a candle and the holy book) and use the altar.
Talk to the archivist's ghost: he tells you to find the forgetful old priest. Find his remains and his cloak: the chapter and verse are woven into its sleeve.
At the altar, in this order: ring the bell, ring the bell again, light the candle, open the book (it now opens on the right page), ring the bell a third time.
The mirror portal in the center of the temple activates and takes you down when you want.
If you leave the altar midway, start the ritual over.]] },
[74485] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-7 (or ToB)]], w = [[Watcher's Keep, wizards' level]], h = { [[The chromatic demon in the central cage controls the gate to the next level.]], [[Four elemental wizards each made a scepter key; look in their laboratories on this level.]], [[Place the four scepters in the slots around the cage, and be ready: the freed demon attacks.]] }, s = [[On the second level of Watcher's Keep, talk to the chromatic demon imprisoned in its elemental cage. It will only open the way down if you free it.
Agree, then explore the four wizards' laboratories (air, slime, cold and fire). Start the fan first, and read the wizards' notes to beat their creations (see the related entries).
Collect the four scepter keys and place them in the four slots around the cage.
The demon is freed and immediately attacks you. Kill it to continue to the lower level.]] },
[74486] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-7 (or ToB)]], w = [[Watcher's Keep, Carston's level]], h = { [[A dying apprentice tortured by illithids knows Carston's story and the secret of his glass case.]], [[The Machine of Lum the Mad, inside Carston's glass bubble, controls the gate in the northeast.]], [[Every lever and dial has a random effect, good or bad; the red button only opens the gate at the right moment.]] }, s = [[On the third level of Watcher's Keep, talk to Carston's dying apprentice. He explains that the mad wizard Carston is trapped in a glass bubble by the Machine of Lum the Mad, the only way down. Illithids, githyanki and the dragon Saladrex also live on this level.
Find a way through Carston's glass bubble and deal with him.
Use the machine: three levers and two dials give random effects, some permanent (stat gains, healing, summoned monsters, fire, petrification, level drain).
When the red button works, the magical gate in the northeast corner opens to the next level. Save before experimenting.]] },
[74487] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-7 (or ToB)]], w = [[Watcher's Keep, prison level]], h = { [[The final seal before the Imprisoned One's crypt needs three keys: mind, heart and spirit.]], [[Each key is won in its own trial on this level.]], [[Mind is the puzzle of the colored globes, heart is the gauntlet, spirit is the Eternal Warrior's challenge.]] }, s = [[On the last level of Watcher's Keep, the stairs to the Imprisoned One's crypt are blocked by the final seal.
Complete the three trials, in any order:
- Mind: solve the puzzle of the colored globes.
- Heart: run the gauntlet, proving perseverance and courage.
- Spirit: beat the challenge of the Eternal Warrior.
Each trial gives one key. With the heart, mind and spirit keys, unlock the final seal; the path to the crypt is open.
Prepare well before going down: Demogorgon waits below.]] },
[74488] = { g = [[tob]], k = [[main]], o = 68, c = [[8]], w = [[Saradush]], h = { [[Melissan wants the paranoid general Gromnir, locked in Saradush's castle, stopped before the siege can be broken.]], [[The castle gate stays shut: ask around the Tankard Tree, the Temple of Waukeen and the streets for a secret way in.]], [[Sister Farielle has the key to the abandoned jail across the street, which hides a passage into the castle.]] }, s = [[After talking to Melissan, find a way into Gromnir's castle. Three leads:
- Pyrgam Aleson at the Tankard Tree speaks of an abandoned jail; Sister Farielle at the Temple of Waukeen gives you its key. The door is across the street. Bring holy water against the undead inside and look for the secret area leading to the castle.
- A waitress you save from bullying soldiers says the sealed sewers lead to the castle.
- Peltje talks of vampires posing as prostitutes, based in the sewers.
Inside, Gromnir is beyond reason: kill him and his guards. Then report to Melissan for the next step.]] },
[74489] = { g = [[tob]], k = [[main]], o = 67, c = [[8]], w = [[Saradush]], h = { [[Saradush is besieged by Yaga-Shura's army; find Melissan, the protector of the Bhaalspawn here.]], [[Melissan says the mad general Gromnir must be dealt with first.]], [[With Gromnir dead, leave the city through your pocket plane and go after Yaga-Shura himself.]] }, s = [[You arrive in Saradush, a city besieged by the fire giant Bhaalspawn Yaga-Shura. No one can leave, even by magic.
Talk to Melissan. She promises to explain why the Bhaalspawn are hunted if you help end the siege.
First deal with Gromnir Il-Khan, who has locked himself in the castle (see "Dealing with Gromnir"). Side quests in town are worth doing before you go.
After Gromnir's death, Melissan says the only hope is to kill Yaga-Shura. Use your pocket plane ability to leave the city, then follow "Defeating Yaga-Shura".]] },
[74490] = { g = [[tob]], k = [[side]], o = 0, c = [[8]], w = [[Saradush]], h = { [[Captain Samand holds a young man, Mateo, accused of plotting to open a secret gate to the enemy.]], [[Countess Santele accused him because the merchant Kiser Jhaeri kidnapped her son Ardic.]], [[Ask the wizard Errard instead of killing him: Ardic is hidden in Kiser's house.]] }, s = [[Talk to Captain Samand, then to Mateo at the militia headquarters: he claims innocence.
Visit Countess Santele: Kiser Jhaeri kidnapped her son Ardic and forced her to accuse Mateo.
Talk to Kiser. He asks you to kill the wizard Errard, or even the countess, for gold and a key to Ardic's secret cell in his basement.
Good path: speak to Errard instead. He confirms Ardic is in Kiser's home. Go back, kill Kiser and free Ardic; his testimony clears Mateo and the countess rewards you.
Evil paths: kill Errard (Saradush's defenses suffer) or the countess for Kiser's pay. Ardic may also die in the fight.]] },
[74491] = { g = [[tob]], k = [[main]], o = 69, c = [[8]], w = [[Forest of Mir / Marching Mountains]], h = { [[Yaga-Shura is immune to weapons and magic; his secret lies in the Forest of Mir or the Marching Mountains.]], [[The witch Nyalee, in a Bhaalist temple ruin in the Haunted Glade, raised him and knows how his heart burns.]], [[Take his blazing heart from the brazier in his lair and the golden chest from his stone bed, then bring both to Nyalee.]] }, s = [[Melissan warns that Yaga-Shura cannot be harmed as he is. Leave Saradush by the pocket plane.
In the Forest of Mir, reach the Haunted Glade and the ruined Bhaalist temple. The witch Nyalee explains that Yaga-Shura keeps his heart outside his body, ablaze. She will extinguish it if you also bring back her own heart, which he stole.
In the Marching Mountains, enter Yaga-Shura's lair. Free the woman chained in his quarters: she tells you about the small golden chest hidden in his stony bed (it holds Nyalee's heart).
Take Yaga-Shura's heart from the brazier and the chest, return to Nyalee and give her both. She extinguishes his heart.
Then go to the siege camp to face Yaga-Shura.]] },
[74492] = { g = [[tob]], k = [[main]], o = 70, c = [[8]], w = [[Siege camp outside Saradush]], h = { [[Once Nyalee has extinguished his heart, Yaga-Shura can finally be hurt.]], [[He waits among his army at the siege camp outside Saradush.]], [[Fight through his giants and kill him; Saradush itself cannot be saved.]] }, s = [[This entry closes the Yaga-Shura storyline.
After Nyalee extinguishes Yaga-Shura's heart, travel to the siege camp outside Saradush. Expect a long battle against his army of giants and soldiers before you reach him.
Yaga-Shura is now vulnerable: kill him.
Saradush has been razed in the meantime, as Yaga-Shura destroyed it while searching for you. The story continues with Melissan and the plan to attack the enclaves of Sendai and Abazigal.]] },
[74493] = { g = [[tob]], k = [[main]], o = 72, c = [[9]], w = [[Amkethran and the enclaves]], h = { [[Melissan sends you to the village of Amkethran, where Balthazar holds the maps to the enclaves.]], [[Destroy Sendai and Abazigal in their enclaves; a vision then shows Balthazar fighting Melissan.]], [[Saemon Havarian can get you into the guarded monastery, with a password and stolen uniforms.]] }, s = [[After Yaga-Shura's death, Melissan sends you to Amkethran. Meet Balthazar, the head of the monastery: he gives you the maps to the enclaves.
Attack Sendai's enclave and Abazigal's enclave, in any order (see their own entries).
With both dead, a vision shows Balthazar fighting Melissan. Return to Amkethran: the town is full of Balthazar's mercenaries.
Saemon offers a way in. Refuse and fight through the town, or accept: he eventually gives you a password and disguises to enter the monastery.
Confront Balthazar. He reveals he is one of the Five and wants every Bhaalspawn dead, himself included, and warns that Melissan has used you all along.]] },
[74494] = { g = [[tob]], k = [[main]], o = 73, c = [[9]], w = [[Sendai's enclave]], h = { [[At Sendai's location on the map, you only find a simple woodsman.]], [[He mentions strange events on his land; the woodsman is a disguised drow agent.]], [[The entrance to Sendai's enclave is hidden in his cabin.]] }, s = [[Travel to Sendai's enclave using Balthazar's maps. A woodsman greets you and talks of strange happenings on his property.
He is in fact a disguised drow working for Sendai. Unmask or kill him, then search his cabin for the entrance to the enclave below.
Fight through Sendai's drow and their traps. Expect many casters and puzzles on the way.
Kill Sendai, another of the Five. The Solar will call you back to the pocket plane for a new revelation.]] },
[74495] = { g = [[tob]], k = [[main]], o = 74, c = [[9]], w = [[Abazigal's enclave]], h = { [[Abazigal's son Draconis guards the entrance to his caverns.]], [[A dying monk of Balthazar says a scroll of reversal breaks the geas on a dragon guardian and the inner seal.]], [[The caves link through underwater tunnels; the mad wizard Iycanth trades the scroll for an eyestalk.]] }, s = [[Travel to Abazigal's enclave. At the entrance you meet his son Draconis: kill him (he turns into a dragon).
Inside, find Balthazar's imprisoned monk. Before dying, he gives you a rope and water breathing potions and explains that you need the scroll of reversal.
Explore the caverns through the underwater tunnels. Get the scroll from the wizard Iycanth (see "Iycanth's eyestalk").
Use it to break the geas on the dragon guardian and open Abazigal's inner lair.
Kill Abazigal, a blue half-dragon; prepare protection against electricity.]] },
[74496] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-7 (or ToB)]], w = [[Watcher's Keep, wizards' level]], h = { [[The imp in the library says a magical fan powers every laboratory on this level.]], [[Start with the Air Lab, just behind the imp.]], [[The fan has two settings, high and low; switching between them matters elsewhere on the level.]] }, s = [[On the second level of Watcher's Keep, talk to the imp in the libraries. Tell him his masters are dead: he explains that the fans stopped and the labs are empty without them.
Go to the Air Lab, right behind the imp, and start the magical fan.
The fan has a high and a low setting. Try both as you explore: the labs only come to life with the fan running, and the airflow affects what you can do elsewhere.
With the labs active you can look for the wizards' scepter keys (see "Gather the four scepter keys").]] },
[74497] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-7 (or ToB)]], w = [[Watcher's Keep, wizards' level]], h = { [[Four wizards of air, slime, cold and fire each had a library and a laboratory here.]], [[Their pets are nearly unkillable unless you know how to hurt them.]], [[Read the lab notes in each library: each wizard used his own element against another's creation.]] }, s = [[The imp on the second level of Watcher's Keep tells you about the four elemental wizards (air, slime, cold and fire), who plotted against each other.
Visit the four libraries and read the wizards' notes before entering their laboratories. Each note explains how to destroy a rival's creation.
In each lab, use the element or item named in the notes against its guardian; normal attacks barely work on them.
Defeating the guardians lets you search the labs for the scepter keys needed by the chromatic demon.]] },
[74498] = { g = [[tob]], k = [[side]], o = 0, c = [[9]], w = [[Abazigal's enclave]], h = { [[The mad wizard Iycanth will trade the scroll of reversal for a gauth's eyestalk.]], [[The gauth vanished into one of the pools east of his laboratory.]], [[Fetch it yourself, or restore the petrified adventurers nearby and let them do the job.]] }, s = [[In Abazigal's caverns, meet the wizard Iycanth. He wants the eyestalk of a gauth (a small beholder) that hid in one of the pools east of his lab.
Option 1: dive through the pools (you need water breathing), find and kill the gauth, and take its eyestalk.
Option 2: Iycanth suggests subcontracting. Nearby, Bondari and his companions (Nanoc, Tim and friends) have been turned to stone. Cast Stone to Flesh on them and hand them the "quest": they bring back the eyestalk.
Return to Iycanth's lab and trade the eyestalk for the scroll of reversal, needed to break the geas and enter Abazigal's lair.]] },
[74499] = { g = [[tob]], k = [[side]], o = 0, c = [[9]], w = [[Amkethran]], h = { [[A boy in front of the sealed graveyard cavern blames a strange man for the undead.]], [[Marlowe, a merchant from Calimshan, says the lich Vongoethe stole his daughter Malla's soul.]], [[Hear the lich's side in the graveyard cavern: Marlowe sold his own soul and never paid.]] }, s = [[Talk to the boy near the sealed graveyard cavern on the north side of Amkethran, then to Marlowe in his house on the east cliff. He says the lich Vongoethe took his daughter Malla's soul.
Agree to help: the guard lets you through the magical seal.
In the cavern, Vongoethe tells you Marlowe traded his soul for twenty years of success and fled without paying.
Choices:
- Kill Vongoethe and his undead (tough lich fight). If you get the soul stone, give it to Marlowe or keep it.
- Bring Marlowe to the lich (ask him or trick him). Vongoethe takes Marlowe and gives you the girl's soul; use it to restore Malla.
- Attacking without the stone may leave Malla dead.]] },
[74500] = { g = [[tob]], k = [[side]], o = 0, c = [[8]], w = [[Saradush]], h = { [[Lazarus, the scroll seller of Saradush, had his spellbook stolen and suspects Hectan.]], [[Small muddy footprints lead from the shop window to a street urchin, Squip.]], [[Hectan wants a teleportation scroll for the book; Lazarus warns it will kill whoever uses it.]] }, s = [[Talk to Lazarus in his scroll shop in Saradush. His spellbook is gone; he suspects Hectan, who was drunk at the inn that night.
Examine the clue: small muddy footprints by the shop window. Find the urchin Squip, who admits he stole the book for Hectan.
Confront Hectan. He will only trade the book for a teleportation scroll to escape the besieged city.
Return to Lazarus: he gives you the scroll, warning that anyone who reads it will rebound off the magical barrier around Saradush.
Trade the scroll to Hectan for the book (he meets his end when he uses it).
Return the spellbook: Lazarus reopens his shop.]] },
[74501] = { g = [[tob]], k = [[side]], o = 0, c = [[9]], w = [[Amkethran]], h = { [[A frightened man named Marlowe stops you in Amkethran.]], [[He asks you to meet him at his home atop the east cliff.]], [[Go there and hear his story about a lich; it starts "The graveyard lich".]] }, s = [[In Amkethran, Marlowe approaches you, desperate, and asks you to come to his house on top of the east cliff.
Go there and talk to him. He tells you about the lich Vongoethe and his daughter's stolen soul.
The story then continues in the quest "The graveyard lich": the sealed graveyard cavern is on the north side of town.]] },
[74503] = { g = [[tob]], k = [[main]], o = 65, c = [[8-10]], w = [[Pocket plane]], h = { [[Five corridors lead off the main room of your pocket plane; each opens when you are ready.]], [[The fate spirit near the entrance can summon companions whose fates are tied to yours.]], [[Before each challenge, talk to the fate spirit to fill out your party.]] }, s = [[At the start of Throne of Bhaal, Sarevok's echo explains how your pocket plane works.
The challenges: five corridors around the main room. The Solar opens them one by one as the story advances (after major events like the fall of Saradush or the death of one of the Five). Each holds a hard fight or test; you return to the plane when called.
The fate spirit: talk to it near the entrance of the plane. It can summon former companions whose fates are tied to yours, so you can rebuild your party at any time.
Use it before each challenge.]] },
[74504] = { g = [[tob]], k = [[main]], o = 71, c = [[8]], w = [[Pocket plane]], h = { [[Sarevok's echo in the pocket plane tells you where your destiny leads next.]], [[The pocket plane takes you where you need to be: the city of Saradush in Tethyr.]], [[Gather your party with the fate spirit, then leave the plane through its exit.]] }, s = [[In the pocket plane at the start of Throne of Bhaal, talk to Sarevok's echo. He says your next destination is Saradush, a city of Tethyr.
The plane is not a free portal: it sends you where you need to be.
Summon the companions you want with the fate spirit, then use the exit. You arrive in Saradush, under siege, where the quest "Saradush under siege" begins.]] },
[74505] = { g = [[tob]], k = [[main]], o = 75, c = [[9]], w = [[Amkethran]], h = { [[In Amkethran, the monks will lead you to their master, Balthazar.]], [[Balthazar lets you stay in town if you keep out of his monastery.]], [[He hands you the maps to Sendai's and Abazigal's enclaves: go there next.]] }, s = [[Arriving in Amkethran after the fall of Saradush, you are brought before Balthazar, head of the monastic order.
He is cold but allows you to stay in town as long as you do not try to enter the monastery or meddle in his affairs.
He gives you the maps to the Bhaalspawn enclaves that Melissan left with him. Melissan herself is nowhere to be found.
Use the maps on the world map to attack Sendai's and Abazigal's enclaves. Meanwhile, the town has shops and side quests.]] },
[74506] = { g = [[tob]], k = [[main]], o = 66, c = [[8-10]], w = [[Pocket plane]], h = { [[After each major victory, the Solar calls you back to the pocket plane.]], [[Listen to her revelations: each one opens a new challenge corridor.]], [[Beat every challenge; the last one destroys your pocket plane and opens the way to the Throne of Bhaal.]] }, s = [[Throughout Throne of Bhaal, the Solar summons you to your pocket plane after key events and reveals your past and your role in Alaundo's prophecy (Gorion could have taken Sarevok instead of you; you are the one meant to stop the other Bhaalspawn; the Five are Illasera, Yaga-Shura, Sendai, Abazigal and Balthazar).
After each talk, she opens another challenge corridor. Enter it, with companions from the fate spirit, and win the test.
After Balthazar, she reveals that your true enemy is Melissan, Bhaal's former high priestess. The final challenge destroys your pocket plane so you can follow her to the Throne of Bhaal.]] },
[74507] = { g = [[tob]], k = [[side]], o = 0, c = [[8]], w = [[Saradush, abandoned jail]], h = { [[A mute ghost of an old prisoner haunts the abandoned jail and points to his defiled grave.]], [[He mimes a necklace, points at the nearby cells, and clutches his head: find his necklace and skull.]], [[Place the skull and necklace in the shallow grave and sprinkle elven holy water on it.]] }, s = [[In the abandoned jail of Saradush (the route into Gromnir's castle), the ghost of an old beggar appears several times. He cannot speak but shows you that his grave has been defiled.
Search the nearby cells for his necklace, and find his skull.
At the shallow grave, put back the skull and the necklace, then use elven holy water to sanctify the ground.
The spirit finds peace, gives you experience, and opens a door you could not open before.]] },
[88267] = { g = [[bg2]], k = [[side]], o = 0, c = [[Black Pits II]], w = [[Black Pits II]], h = { [[An eccentric monk among the captives offers odd services in Lathander's name.]], [[Brother Ellraish can brew a poison from powdered quartz and rat droppings.]], [[He also trades a key to the Hunters' Lounge for the illithid merchant's runestone.]] }, s = [[Talk to Brother Ellraish.
Poison: he needs powdered quartz and rat droppings. Bring both and he gives you a poison to use on Joker (see The Joke's on Who).
Key: after a 'vision', he asks for the runestone held by the illithid merchant. The illithid wants Stannel Eibor's ring in exchange. Get the ring, trade it for the runestone, and give the stone to Ellraish.
He hands over the key to the Hunters' Lounge upstairs, which also gets you past the stairway guard (see Moving Up).]] },
[93935] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla / Deepstone]], h = { [[Dark Moon heretics court Rasaad; they meet in an abandoned amphitheater outside Athkatla.]], [[Their leader Hammerhelm points Rasaad to Collus Darathon, founder of the Twofold Trust, in a secret temple.]], [[Collus Darathon is Alorgoth; a map on the Dark Moon assassins leads to Deepstone and his final plan.]] }, s = [[With Rasaad in the party, go to the abandoned amphitheater outside the city and hear Hammerhelm, a former Sun Soul monk who leads the Twofold believers.
He tells Rasaad where to find Collus Darathon: travel to the Twofold's secret temple and pass the trials to join the Twofold Trust.
Collus Darathon is Alorgoth, who sends Sharrans to crush his own cult. Fight beside the Trust, or flee before the attack. Rasaad may defeat his old teacher, the Master of Combat, and lead the Trust.
Later, Dark Moon assassins attack; one carries a map to Deepstone. There, Meems Dugdeep's dwarves need rock salt, a potion of explosions and a special grog to blast a tunnel into the mines.
Inside, Alorgoth opens a gate to the Plane of Shadow. Follow him with Rasaad (he goes alone if you refuse), face Alorgoth, his assistant Yxtrazzal and a shadow dragon, then escape back through the portal.]] },
[94033] = { g = [[bg2]], k = [[side]], o = 0, c = [[Black Pits II]], w = [[Black Pits II, barracks]], h = { [[Brodle knows a guard lieutenant who might back a revolt against Dennaton.]], [[Meet Leokas in the barracks; he wants a small bribe before he even talks.]], [[His real price for his soldiers is huge, though it may come down.]] }, s = [[Talk to Brodle and agree to plan a rebellion; he arranges a meeting and tells you when the lieutenant is ready.
Go to the barracks and meet Leokas. First pay for his silence (100 or 200 gold depending on the talk).
He then asks 20,000 gold for his and his soldiers' support; in some conversations he drops it to 15,000.
Pay him: when the revolt begins, Leokas secures the barracks for you and his men fight Dennaton's forces. If you refuse, expect to fight his troops during the uprising.]] },
[94452] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Wild Forest / Hidden Refuge]], h = { [[Barad Ding, a wild mage at the Hidden Refuge, has lost eight cats.]], [[They roam the Wild Forest; he gives you a bag of cat food as a lure.]], [[Use the cat food near each feral cat, collect all eight, and bring them back to the Refuge.]] }, s = [[At the Hidden Refuge (Neera's camp), talk to Barad Ding. His cats Abby, Connie, Alter, Divine, Chanticleer, Eevo, Lucy and Nector are lost in the Wild Forest.
Take the bag of cat food and search the forest. The cats are feral: use the food to lure each one.
Return to Barad Ding once you have all eight.
Reward: a cat named Dings. If he becomes too much trouble (he fills your bags with dead rodents), you can give him back to Barad Ding.]] },
[94457] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Hidden Refuge / Trademeet]], h = { [[Mironda, the dwarven wild mage at the Hidden Refuge, misses a particular beer.]], [[She wants a cask of Halfling's Help, sold in Trademeet.]], [[Buy the cask at Vyatri's Pub in Trademeet and bring it back to her.]] }, s = [[At the Hidden Refuge, talk to Mironda, a dwarven wild mage. She asks for a cask of Halfling's Help.
Travel to Trademeet and buy the cask from Vyatri at his pub.
Return to the Hidden Refuge and give it to Mironda.
Reward: a magical tankard with your name on it.]] },
[94461] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Hidden Refuge]], h = { [[Zaviak, an alchemist at the Hidden Refuge, longs to see Wilson, "the best bear in the world".]], [[Wilson is a bear who can travel with you.]], [[Come back to the Refuge with Wilson in the party and talk to Zaviak.]] }, s = [[At the Hidden Refuge, Zaviak the alchemist says he would love to see Wilson the bear.
If you have Wilson travelling with you, bring him to the Refuge and talk to Zaviak for a short reunion.
Reward: a few of Zaviak's odd but powerful potions.
If Wilson is not in your party, this quest stays open.]] },
[94464] = { g = [[bg2]], k = [[side]], o = 0, c = [[2-6]], w = [[Hidden Refuge / Athkatla, Bridge District]], h = { [[Mereth, a child wild mage at the Hidden Refuge, lost her mother's hairband.]], [[She lost it when Neera rescued her from the Order of Eight Staves in Athkatla.]], [[Search in and near the crates at the east end of the Bridge District.]] }, s = [[At the Hidden Refuge, talk to the young Mereth. She lost her mother's hairband just before Neera rescued her.
Go to Athkatla's Bridge District and search the crates at its east end until you find the hairband.
Return to the Hidden Refuge and give it to Mereth.
Reward: a magical necklace.]] },
[94474] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla, Waukeen's Promenade, Red Wizard Enclave]], h = { [[Inside the Red Wizard Enclave, fighting every mercenary is not the only way to reach Lanneth.]], [[Their leader Fadell complains of low pay and pointless deaths; her journal says she drinks.]], [[Stir up the mercenaries' grievances and push a drunk Fadell to revolt.]] }, s = [[Part of Neera's quest, after the Hidden Refuge is destroyed. Enter the Red Wizard Enclave in Waukeen's Promenade.
Talk to Fadell, the leader of the mercenaries: she says "things are bad". Ask more: her men are paid next to nothing.
Search the enclave for Fadell's journal: she resents her men's deaths and drinks.
Use these facts to sow revolt among the mercenaries. Once Fadell is drunk enough, she and her men rise against the Red Wizards.
In the final fight, Fadell refuses to help Lanneth even when told you caused many of her men's deaths.
Alternatively, fight the mercenaries yourself.]] },
[94483] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Athkatla, Waukeen's Promenade, Red Wizard Enclave]], h = { [[A minotaur slave and former gladiator, Ghallus, could be a strong ally inside the enclave.]], [[His cell needs a key: Lanneth has one, and a Red Wizard carries a copy.]], [[Get the copy, deal with the mercenaries first, then free the slaves before facing Lanneth.]] }, s = [[In the Red Wizard Enclave, watch the minotaur Ghallus kill a mercenary in the arena, then talk to him.
He needs a key to free himself and the other slaves. Lanneth has one, but a Red Wizard holds a copy: find and take it.
Ghallus prefers that you deal with the mercenaries first (see Part 1).
Return and unlock the slave cells. If the mercenaries are still around, Ghallus leads a bloody revolt against them.
Ghallus then helps you fight Lanneth and her servants.]] },
[94495] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Wild Forest / Athkatla]], h = { [[Neera wants to meet in the Wild Forest outside Athkatla about a secret camp for wild mages.]], [[At the Hidden Refuge, Telana asks you to protect the elven wild mage Daxus, who plays at Delosar's.]], [[When the Refuge is destroyed, the survivors are held in the Red Wizard Enclave in Waukeen's Promenade.]] }, s = [[Meet Neera in Athkatla; she asks you to join her in the Wild Forest. If she cannot find the camp yet, come back later. Then find a way past the wards protecting it.
At the Hidden Refuge, meet Telana and Hayes, who shelter wild mages from the Order of Eight Staves. Talk to the other refugees for side quests.
With Neera, go to Delosar's in the Bridge District at night and talk to Daxus after his show. Give him one of Knocktor's Talismans of the Hearthfire, or let Hayes escort him. Protect him from the Red Wizards.
While you are away, the Refuge is destroyed. Telana says the captives are in the Red Wizard Enclave in Waukeen's Promenade: enter, free them and defeat Lanneth (see Disorder in the Order).
Return to the Refuge to talk to Telana and Neera.]] },
[94558] = { g = [[bg2]], k = [[side]], o = 0, c = [[Black Pits II]], w = [[Black Pits II, kitchen]], h = { [[The cook's two sous-chefs are tired of his tyranny.]], [[The cook is allergic to powdered funguswood; the merchant Bellowgulp may have some.]], [[Slip the powder into a pot on the stove, or betray the plotters to the cook.]] }, s = [[In the kitchen, talk to Marduuk and Short-Order. They ask you to slip powdered funguswood into the cook's food.
Buy the powder from Bellowgulp and the Concocter at the market (they can also make it from a potion of barkskin).
While the cook is distracted, use the powder on a pot on the stove. He dies, and so does his bodyguard, who shares the allergy.
Alternative: tell the cook about the plot. He is grateful, but Dennaton hears of it and the two sous-chefs disappear.]] },
[94559] = { g = [[bg2]], k = [[side]], o = 0, c = [[Black Pits II]], w = [[Black Pits II, kitchen]], h = { [[The cook has a favor to ask.]], [[He wants a bit of the myconid who sells potions in the market.]], [[Bellowgulp can provide a piece of his partner, the Concocter.]] }, s = [[Talk to the cook in the kitchen; he asks for a small piece of the myconid in the market for a special soup.
Go to Bellowgulp and the Concocter at the market and obtain a piece of the Concocter.
Bring the myconid flesh back to the cook. He thinks better of you afterwards.]] },
[94560] = { g = [[bg2]], k = [[side]], o = 0, c = [[Black Pits II]], w = [[Black Pits II]], h = { [[The scribe who records the pit fights looks oddly familiar.]], [[Mention his resemblance to Baeloth; the illithid merchant wants his ring.]], [[His ring buys the illithid's runestone, which buys Brother Ellraish's key.]] }, s = [[Talk to Stannel Eibor, the scribe of the pit fights. Mentioning that he looks like Baeloth the Entertainer makes him uneasy.
The illithid merchant wants Stannel's ring more than anything; recover it from the scribe.
Trade the ring to the illithid for his runestone, then give the runestone to Brother Ellraish for the key to the Hunters' Lounge.]] },
[94561] = { g = [[bg2]], k = [[side]], o = 0, c = [[Black Pits II]], w = [[Black Pits II]], h = { [[Joker, one of the Planar Hunters, loves a drink; several captives hate her.]], [[Many people can make or sell a poison; you also need a drink and a messenger.]], [[Voghiln or a Noser can lure Joker with a special drink or a drinking contest.]] }, s = [[Goal: poison Joker to weaken Dennaton's enforcers before the final fights.
1. Get a poison, any one of: Bellowgulp and the Concocter (ready-made), Brother Ellraish (powdered quartz, rat droppings), Gezzthemin (distilled alcohol, lotus root), Feldrak (rose petals, wine vinegar), or the rat poison in a kitchen cupboard.
2. Get a drink to hide it in: the ceremonial ale from Molzahn, the priest of Tymora (he holds a grudge against Joker), or some fine spirits.
3. Send word to Joker: Voghiln drinks with her and can pass on a drink offer or a drinking-contest challenge; a Noser can do the same.
If she drinks it, she is weakened for the coming battle. If the attempt fails, you must find another way to weaken the Hunters.]] },
[95658] = { g = [[bg2]], k = [[side]], o = 0, c = [[Black Pits II]], w = [[Black Pits II]], h = { [[The old mage called 'The Ancient Threat' forgets you mid-sentence.]], [[A salve could clear Dulf Ebonbeard's mind for a while; ask the pit merchants.]], [[The Concocter can brew Teodgren's Salve of Senile Serenity for a small fee.]] }, s = [[Dulf Ebonbeard is too senile to be useful.
Go to Bellowgulp and the Concocter in the market and buy Teodgren's Salve of Senile Serenity (about 100 gold).
Give it to Dulf: his mind clears for a time, and he can then help you, notably with the spirit transference scroll against Bannor (see Trading Places).]] },
[95779] = { g = [[bg2]], k = [[side]], o = 0, c = [[Black Pits II]], w = [[Black Pits II]], h = { [[Two scribes can write a scroll that moves Bannor's mind into another being.]], [[Dulf Ebonbeard wants rare components; Gerrold Darkfellow wants gold, but promises less.]], [[Either way you need something unique to Bannor: look in his room upstairs.]] }, s = [[To weaken the Planar Hunter Bannor Kaxazel, get a spirit transference scroll.
Option 1: Dulf Ebonbeard (lucid only after his salve, see his quest) wants a wyrm tooth, a carrion crawler egg, ettin-skin parchment and an item of Bannor's, plus a large sum of gold.
Option 2: Gerrold Darkfellow asks only for an item of Bannor's and 4,000 gold, but cannot guarantee the result.
The item: a shard of the broken mirror in Bannor's room, in the Planar Hunters' quarters upstairs (see Moving Up).
After delivery the scribe works for a while, then gives you the scroll. Only a spellcaster can use it: read it on Bannor when you face him.]] },
[95872] = { g = [[bg2]], k = [[side]], o = 0, c = [[Black Pits II]], w = [[Black Pits II]], h = { [[A proud gladiator among the performers loves to talk about himself.]], [[Telling Symm Haximus the plain truth about gladiators touches a nerve.]], [[Fight beside him in the arena and he will share his secrets.]] }, s = [[Talk to Symm Haximus, a self-styled professional gladiator.
Telling him that gladiators are only slaves upsets him; this may be useful later.
He offers to share some of his secrets if he fights alongside you: take him into the party for arena battles, then talk to him again between fights.]] },
[96007] = { g = [[bg2]], k = [[side]], o = 0, c = [[Black Pits II]], w = [[Black Pits II]], h = { [[A self-proclaimed bringer of justice is among the performers.]], [[Mercy Whitedove knows something about the arena guards' loyalty.]], [[Fight at her side in the arena to hear more about her past.]] }, s = [[Talk to Mercy Whitedove.
She tells you the arena guards have no real loyalty to Dennaton and cannot stand against the performers without the Winged behind them: useful for a rebellion.
She will share more of her past if she fights beside you: take her into the party for arena battles, then talk to her again.]] },
[96026] = { g = [[bg2]], k = [[side]], o = 0, c = [[Black Pits II]], w = [[Black Pits II]], h = { [[Brother Ellraish can get you into the Hunters' Lounge, for a price.]], [[The illithid merchant will part with his runestone for something he covets.]], [[He wants the ring of Stannel Eibor, the pit scribe.]] }, s = [[Brother Ellraish wants the illithid merchant's runestone in exchange for a key to the Hunters' Lounge.
Talk to the illithid merchant: he agrees to trade the runestone for Stannel Eibor's ring.
Get the ring from Stannel, give it to the illithid, then bring the runestone to Ellraish.
He gives you the key to the Hunters' Lounge upstairs.]] },
[96076] = { g = [[tob]], k = [[companion]], o = 0, c = [[8-9]], w = [[Tethyr / Thay]], h = { [[Telana tells Neera that Vicross, leader of the Order of Eight Staves, is in Tethyr nearby.]], [[Neera wants to lure her into a trap in a clearing with a burst of wild magic.]], [[A wild surge carries you to Thay, where Szass Tam offers to send you into Vicross's estate.]] }, s = [[With Neera in the party in Throne of Bhaal, she learns that Vicross is close. Go to the clearing she suggests.
Neera casts Nahal's Reckless Dweomer; set up camp and wait for Vicross and the Red Wizards.
Vicross, herself a wild mage, teleports back to Thay, and a wild surge pulls you along into a gladiator arena. Win the fight.
The announcer Dennaton calls you to the staging area. Szass Tam, zulkir of necromancy, wants Vicross dead: rest and prepare, then he teleports you into her estate.
Kill Vicross, search her quarters, and ring the Bell of Summoning.
Szass Tam betrays you; survive his attack until he sends you back to Tethyr. The Order of Eight Staves is finished.]] },
[96107] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-10]], w = [[Athkatla, Temple District / Resurrection Gorge]], h = { [[Dorn's demon patron wants a paladin of Helm dead; ask at Helm's temple in Athkatla.]], [[Guardian Telwyn knows where Terpfen went; later, a marilith named Azothet offers Dorn a way out.]], [[In Resurrection Gorge, gather every summoning stone and the abyssal blade to bind Ur-Gothoz.]] }, s = [[With Dorn in the party, Ur-Gothoz demands the death of Terpfen, a paladin of Helm.
Visit Helm's temple in the Temple District at night and question Guardian Telwyn: Terpfen is escorting a priest of Tyr in a camp south of the city. Travel there and kill him.
Later Azothet, a marilith, urges Dorn to break free in Resurrection Gorge. You can also reveal her scheme to Ur-Gothoz instead.
In the gorge, the dryad Yarrow lets you in but asks you to slay the tanar'ri lurking near her tree. The druid Vernus explains the missing summoning stones: one is behind Winterbrook's waterfall (southwest), the dragons hold one, the tanar'ri carry the rest. Collect them all plus the abyssal blade, then use the circle in the great tree to bind Ur-Gothoz. Expect hard demon and dragon fights.
In Throne of Bhaal, divine attackers hunt you both: go to Lunia, find the Pavilion of Righteous Wrath and get your names erased from the Scroll of Retribution, then escape.]] },
[96115] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-10]], w = [[Athkatla, Graveyard District]], h = { [[Hexxat, met at the Copper Coronet, seeks a tomb in the southeast of the Graveyard District.]], [[Inside Dragomir's Tomb, the ghost Burich and his iron rod open the vampire's chamber.]], [[The Hexxat you know is not the real one; Dragomir's cloak and casque matter afterwards.]] }, s = [[Recruit Hexxat at the Copper Coronet and agree to find Dragomir's Tomb, southeast in the Graveyard District. Enter with her, or she leaves the party.
Inside, Burich the Unyielding gives you an iron rod that opens Dragomir's chamber but seals you in until the vampire dies. Destroy Dragomir.
The tomb then reveals the truth: the woman you traveled with frees the real Hexxat, a vampire, who can join you. Give her Dragomir's cloak so she can walk in daylight.
Later her employer's messenger Cabrina sends you, through Dragomir's Casque, to the crypts of Durkon in Shou Lung. Help the ghost monk Keno against the mind flayers in the Crypt of Scholars, pass Ki Chin Sang's challenge (open a sarcophagus in the hall) for the key, and take the Claw of the Black Leopard back to Amn.
In Throne of Bhaal, fetch the Shroud of the Unproved in Zakhara; L forges the Casque of Entrapment and sends you into Korkorran's labyrinth. Destroy the lich Korkorran to end the quest.]] },
[100039] = { g = [[bg2]], k = [[companion]], o = 0, c = [[2-6]], w = [[Hidden Refuge]], h = { [[In Neera's Hidden Refuge, the halfling artificer is out of materials.]], [[Knocktor the Fizzled needs a silver necklace, two diamonds and a sum of gold.]], [[A finished talisman can also bring Telana's husband Daxus to the Refuge.]] }, s = [[During Neera's quest, reach the Hidden Refuge and talk to Knocktor the Fizzled.
He asks for a silver necklace, two diamonds and 3,000 gold to craft a Talisman of the Hearthfire, which teleports its owner to the Refuge.
Bring him all three; he gives you the talisman.
Telana wants her husband Daxus brought from Athkatla. Give him the talisman to send him to the Refuge at once; otherwise Hayes, waiting south of Delosar's Inn, can escort him instead.]] },
[102771] = { g = [[bg2]], k = [[side]], o = 0, c = [[Black Pits II]], w = [[Black Pits II, market]], h = { [[The potion sellers in the market have a grudge against one of the Planar Hunters.]], [[Ask how they were captured, and whether they are paid for their work.]] }, s = [[Talk to Bellowgulp and the Concocter, the potion merchants in the market.
Ask about their capture: Joker hurt the Concocter when she caught them, which makes them willing allies against her (they can later sell you a poison for her).
Convince Bellowgulp that he deserves to be paid for selling potions to the performers to complete the conversation thread.]] },
[102772] = { g = [[bg2]], k = [[side]], o = 0, c = [[Black Pits II]], w = [[Black Pits II, stairway to the upper floor]], h = { [[Only the Planar Hunters and their servants, the Nosers, may climb the guarded stair.]], [[A Noser will sell uniforms; Ellraish's key or a lockpick also open the door.]], [[If the guard captain stops you, a bribe or a dirty job for him will clear the way.]] }, s = [[A guarded door blocks the stairs to the quarters of Dennaton and the Planar Hunters. Ways through:
- Buy Noser uniforms from one of the Nosers and walk past the guard (return the uniforms afterwards).
- Use Brother Ellraish's key.
- Pick the lock and deal with the guard.
The guard captain may still stop you in the hall. Bribe him, or accept his task: kill Dennaton's nephew Branson, a guard who rests on his bunk in the guard quarters when off duty.
Kill Branson, or spare him: he gives you his family ring as proof. Either way the captain then lets you through. Upstairs, avoid drawing suspicion.]] },
[218675] = { g = [[bg1]], k = [[side]], o = 0, c = [[2]], w = [[Nashkel Mines]], h = { [[A dagger in your possession belongs to a miner named Kylee.]], [[Kylee works in the lower levels of the Nashkel mines.]], [[Find miner Kylee down in the mines and give him his dagger.]] }, s = [[Once you hold Kylee's Dagger and have been asked to return it, go down into the Nashkel mines.
On the lower levels, look for the miner Kylee among the workers.
Talk to him and give him the dagger. He is relieved and much less nervous afterwards.]] },
[227561] = { g = [[bg1]], k = [[main]], o = 2, c = [[1]], w = [[Friendly Arm Inn]], h = { [[Gorion's last instruction was to go to the Friendly Arm Inn.]], [[Follow the roads northeast from the area outside Candlekeep to reach the inn.]], [[Find Khalid and Jaheira at the Friendly Arm Inn; beware of hostile strangers who know your name.]] }, s = [[After Gorion dies defending you from the armoured stranger outside Candlekeep, Imoen catches up with you and can join.
Travel through the wilderness to the Friendly Arm Inn, a walled inn to the northeast. Expect a few ambushes on the way.
At the inn, beware: an assassin waits for you there. Defeat him.
Find Khalid and Jaheira at the Friendly Arm Inn and speak to them. They join you, and the main quest continues toward Nashkel and its troubled mines.]] },
[227633] = { g = [[bg1]], k = [[companion]], o = 0, c = [[2-5]], w = [[Adoy's Enclave (east of Firewine Bridge)]], h = { [[Neera's past catches up with her: a halfling claims she robbed him, and a Red Wizard is hunting wild mages.]], [[Neera hopes the old wild mage Adoy, said to live east of the Firewine Bridge, can advise her.]], [[Free Adoy from the hobgoblin Rogdok, then face the Red Wizard Ekandor with Neera and Adoy.]] }, s = [[With Neera in the party, the halfling Meklin accosts you and accuses her of theft. Pay him what she stole to settle it, or let it end in a fight.
Neera later hears of Adoy, an old wild mage living east of the Firewine Bridge. Travel to Adoy's Enclave.
Adoy is held by the goblins he once summoned by accident, and the hobgoblin Rogdok keeps him prisoner to make himself goblin king. Defeat Rogdok and free Adoy.
The Red Wizard Ekandor, who has been chasing Neera, follows you there. Fight him alongside Neera and Adoy and kill him to end his hunt for wild mages.]] },
[228607] = { g = [[bg1]], k = [[companion]], o = 0, c = [[2-7]], w = [[Nashkel / Baldur's Gate / Cloud Peaks]], h = { [[Rasaad, a Sun Soul monk outside the Nashkel Inn, is being hunted by the Dark Moon cult of Shar.]], [[A man named Sorrem pointed the killers at Rasaad; look for him at the Blade and Stars in Baldur's Gate.]], [[The cult's leaders wait in a temple in the Cloud Peak Mountains south of the Nashkel mines; Rasaad's brother is there.]] }, s = [[Recruit Rasaad outside the Nashkel Inn. Some time later, Dark Moon monks ambush the party to kill him.
In Baldur's Gate, find Sorrem at the Blade and Stars tavern. Press him: he either reveals that the cult meets at the Seven Suns building after dark, or dies and points you to the Cloud Peak Mountains.
At night, deal with the monks at the Seven Suns building; you learn their orders come from a new temple in the Cloud Peaks, south of the Nashkel mines.
Travel to the Cloud Peaks. Beware ice trolls and rejected cult applicants. In the temple you find Gamaz, Rasaad's brother, now a servant of Shar. Expect a tough fight against him and his monks.]] },
[231092] = { g = [[bg1]], k = [[companion]], o = 0, c = [[2-5]], w = [[Nashkel / east of Nashkel / outside Baldur's Gate]], h = { [[Dorn hunts the members of his old adventuring party who betrayed him.]], [[Taris in Nashkel knows where Kryll is, but Dorn's threats scared her; try a gentler approach.]], [[Kill Kryll east of Nashkel, then read her note to find Simmeon outside Baldur's Gate.]] }, s = [[Recruit the half-orc blackguard Dorn Il-Khan. He is hunting the members of his former party who wronged him.
In Nashkel, talk to Taris yourself with kind replies: she points you east of Nashkel, where the sorceress Kryll has enthralled her husband and others.
Travel there and kill Kryll and her charmed followers. She carries a note from Simmeon, the last of Dorn's foes.
Go to the entrance of Baldur's Gate, where Simmeon waits. He is a blackguard too, so expect a hard fight.
With Simmeon dead, Dorn's revenge is complete and he stays with you.]] },
[231270] = { g = [[bg1]], k = [[main]], o = 1, c = [[1-7]], w = [[Sword Coast]], h = { [[Follow the iron crisis: Nashkel and its mines are where the trail starts.]], [[Letters on each villain point to the next: Tranzig, the bandit camp, then the Cloakwood mine.]], [[In Baldur's Gate, the Iron Throne and Sarevok are behind it all; his diary and the coronation end it.]] }, s = [[Ch. 1: after Gorion dies, go north to the Friendly Arm Inn and meet Khalid and Jaheira.
Ch. 2: in Nashkel, see Berrun Ghastkill, then clear the mines down to Mulahey; his letters name Tranzig in Beregost.
Ch. 3: Tranzig points to Larswood or Peldvale and the bandit camp; search Tazok's tent.
Ch. 4: flood the Cloakwood mine by pulling its sealed plug.
Ch. 5: in Baldur's Gate, meet Scar, then Duke Eltan, and investigate the Iron Throne.
Ch. 6: in Candlekeep you are framed for Rieltar's murder; Tethtoril frees you through the catacombs.
Ch. 7: wanted by the Flaming Fist, save Duke Eltan, take Sarevok's diary, get the palace invitation from Slythe and Krystin in the Undercellar, expose Sarevok at the Ducal Palace, then chase him through the Thieves' Guild maze to the Undercity.
This row also holds Siege of Dragonspear main entries.]] },
[231271] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Baldur's Gate, near the palace]], h = { [[Rinnie the bard lives in a house beside the Ducal Palace.]], [[She wants a book on the history of the Unicorn Run.]], [[Keep an eye on bookstores and loot for that history book, then simply hand it to her.]] }, s = [[Talk to Rinnie in one of the houses next to the Ducal Palace in Baldur's Gate. She asks for "The History of the Unicorn Run".
Find a copy of that book during your travels (shops selling books or containers along the way).
Return to Rinnie and give it to her to close the quest and get her reward.]] },
[231272] = { g = [[bg1]], k = [[side]], o = 0, c = [[2]], w = [[Beregost]], h = { [[An old mage from Candlekeep, Firebead Elvenhair, wanders the streets of Beregost.]], [[He wants a book called "The History of the Fateful Coin".]], [[Thalantyr, the mage at the High Hedge west of Beregost, sells it.]] }, s = [[Talk to Firebead Elvenhair in Beregost. He asks you to buy "The History of the Fateful Coin" for him.
Go to the High Hedge, the area west of Beregost, and buy the book from Thalantyr in his house.
Bring it back to Firebead in Beregost. He thanks you and gives you a reward.]] },
[231273] = { g = [[bg1]], k = [[side]], o = 0, c = [[2-4]], w = [[Lighthouse area]], h = { [[A worried mother, Ardrouine, lives on the coast near an old lighthouse.]], [[Her son is trapped in the abandoned lighthouse to the west, surrounded by worgs.]], [[Kill the worgs around the lighthouse, then go back to Ardrouine.]] }, s = [[Talk to Ardrouine in the coastal area with the old lighthouse. Her son is trapped inside the abandoned lighthouse to the west.
Go to the lighthouse and kill the worgs that surround it. They come in a pack, so keep weak characters behind.
Return to Ardrouine: her son is safe and she gives you her last 60 gold pieces.]] },
[231274] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Baldur's Gate, Elfsong Tavern]], h = { [[A noblewoman in Baldur's Gate is being blackmailed and wants it to stop.]], [[The blackmailer, Cyrdemac, drinks at the Elfsong Tavern.]], [[Kill Cyrdemac and return to her, or refuse, or use charm to get paid without killing.]] }, s = [[A noblewoman in Baldur's Gate offers you a contract on Cyrdemac, the man blackmailing her. You can turn her down flat (quest ends).
If you accept, go to the Elfsong Tavern, find Cyrdemac and kill him (an evil act: watch your reputation and the guards).
Return to her for your pay. An evil option lets you take over the blackmail: she then keeps paying you every two days.
A charmed noblewoman simply hands you the reward without any killing.]] },
[231275] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Baldur's Gate, south of the Elfsong Tavern]], h = { [[A necromancer living near the Elfsong Tavern is short of corpses.]], [[Arkion says the city sewers are the best place to find one.]], [[Pick up a body in the Baldur's Gate sewers and carry it back to Arkion's house.]] }, s = [[Talk to Arkion in his house just south of the Elfsong Tavern in Baldur's Gate. He wants a corpse.
Enter the city sewers (several manholes around town) and look for a body you can pick up.
Bring it back to Arkion: he pays you some gold.
Arkion is also involved in two other quests, with Nemphre and Ordulinian.]] },
[231276] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Sword Coast]], h = { [[A chatty gnome, Delsvirftanyon, wants to retire from the curio trade.]], [[He offers to sell you his whole stock in one go.]], [[Pay his price if you can afford it and sort through the jumble; refusing just ends the quest.]] }, s = [[Talk to the gnome Delsvirftanyon. He wants out of the curio business and offers you the entire contents of his store.
You can refuse because you have no room, or because the price is too high: the quest simply ends.
If you have the gold, buy the lot. The items are added to your inventory, so make room first, then sell what you do not need.]] },
[231279] = { g = [[bg1]], k = [[main]], o = 7, c = [[3-4]], w = [[Cloakwood]], h = { [[The documents in Tazok's tent at the bandit camp point to an Iron Throne base in the Cloakwood.]], [[In the Cloakwood, the druids Takiyah and Faldorn know where the forest is being poisoned.]], [[The fort lies east of the druid grove; the mine entrance is in its eastern bailey.]] }, s = [[At the bandit camp, free Ender Sai in Tazok's tent and read the documents in Tazok's chest: the Iron Throne runs the bandits from a base in the Cloakwood.
Travel through the Cloakwood. Takiyah sends you to Faldorn, who fights the people poisoning the forest; agree to help her.
Head north then east of the druid grove to the Iron Throne fort. Fight through the guards; one of them reveals that the mine entrance is in the eastern bailey.
Enter the Cloakwood mines to continue the main story.]] },
[231280] = { g = [[bg1]], k = [[main]], o = 6, c = [[3]], w = [[Bandit camp]], h = { [[Tazok, the bandit lieutenant, reports to someone higher up.]], [[Kivan the ranger hunts Tazok and may tell you more.]], [[Tazok is heading to a mine: the bandit camp and its documents show where.]] }, s = [[You learn this from Kivan or from Tazok himself: Tazok plans to visit a mine site where he may report to the real leader of the bandits.
Go on with the bandit camp: search Tazok's tent and his chest for the documents.
They point to the Iron Throne and its hidden mine in the Cloakwood, which continues in "A Hidden Base in the Cloakwood".]] },
[231281] = { g = [[bg1]], k = [[side]], o = 0, c = [[2-7]], w = [[Beregost, Thunderhammer Smithy]], h = { [[Taerom "Thunderhammer", the smith of Beregost, can work unusual materials.]], [[Bring him an ankheg shell and he can turn it into plate mail.]], [[Pay his fee, wait the days he asks for, then come back for the armor.]] }, s = [[Find an ankheg shell (ankhegs and their burrows on the Sword Coast).
Talk to Taerom "Thunderhammer" at his smithy in Beregost. He offers to make ankheg plate mail from the shell for 4,000 gold.
Pay him: depending on the dialogue, the armor is ready in one day or three days.
Rest or travel, then return to Taerom and collect your ankheg plate mail, a strong armor for the early game.]] },
[231283] = { g = [[bg1]], k = [[side]], o = 0, c = [[Prologue]], w = [[Tutorial]], h = { [[This is only a reminder from the combat trainer, Belt.]], [[Go back to Belt and finish the combat training he started.]], [[Follow his instructions to the end; the note disappears once training is done.]] }, s = [[This entry is a reminder that you have not finished Belt's combat training.
Find Belt again and talk to him, then follow the training steps he gives you until he says you are done.
There is no real reward beyond practice; you can ignore it if you already know how to fight.]] },
[231284] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Sword Coast]], h = { [[Fergus, a Flaming Fist soldier, has a problem of the heart.]], [[He needs a special ring to give to his beloved.]], [[Bring him an angel skin ring and give it to him.]] }, s = [[Talk to Fergus, a Flaming Fist soldier. He wants a gift for the woman he loves: an angel skin ring.
Keep any angel skin ring you find in loot or shops instead of selling it.
Return to Fergus with the ring and give it to him to close the quest.]] },
[231285] = { g = [[bg1]], k = [[side]], o = 0, c = [[1-3]], w = [[South of the Friendly Arm Inn]], h = { [[A grumpy dwarven cleric, Unshey, lost her girdle to an ogre.]], [[The ogre roams the wilderness just south of the Friendly Arm Inn.]], [[Kill the ogre, take the girdle of piercing and return to Unshey.]] }, s = [[Talk to Unshey, the dwarven cleric. An ogre with a taste for belts stole her girdle of piercing.
Find the ogre in the area just south of the Friendly Arm Inn and kill it. It hits hard at low level: use ranged attacks and keep moving.
Take the girdle from its body and bring it back to Unshey. Depending on how it goes, she pays 95 gold for the dead ogre or 70 gold for the girdle, with a rude remark about your smell.]] },
[231287] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Ulgoth's Beard / Durlag's Tower]], h = { [[A loud huckster named Ike sells tours of Durlag's Tower.]], [[Fenrus, near the docks of Ulgoth's Beard, has already taken the tour.]], [[Accept the tour and meet Ike by the tower, but expect the tower to be far from safe.]] }, s = [[Meet Ike, who offers tours of Durlag's Tower. You can refuse; he stays available if you change your mind.
Ask Fenrus, near the docks, about the tour and the tower's history.
Accept Ike's offer and meet him at the entrance of Durlag's Tower.
The tour leads you into danger rather than safety. Ike's ward token opens some of the lower chambers: see "Durlag's Tower" for the rest.]] },
[231288] = { g = [[bg1]], k = [[main]], o = 12, c = [[7]], w = [[Baldur's Gate, Flaming Fist headquarters]], h = { [[After Candlekeep, the Flaming Fist hunts you on the orders of its new commander, Angelo.]], [[Avoid killing the guards: you can surrender, or slow them down and run.]], [[If you end up in the Flaming Fist cells, talk to the prisoner Neb.]] }, s = [[Back in Baldur's Gate, Flaming Fist patrols try to arrest you: Angelo Dosan has replaced Duke Eltan and condemned you.
Killing the guards costs reputation; entangle or hold them and flee, or surrender.
If you surrender, Angelo sentences you to hang and locks you up. In the cell, Neb tells you that Eltan is sick and Scar is dead, then leads you out through a hidden secret passage.
If Shar-Teel is in the party, Angelo, her father, releases you once, but do not get caught again.
The story goes on with "Duke Eltan's Illness".]] },
[231289] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Baldur's Gate, Thieves' Guild]], h = { [[Alatos Thuibuld, master of the Thieves' Guild, has a burglary job for you.]], [[The three daughters of Shandalar in Oberan's estate hold the parts of a Halruaan skyship.]], [[Win friends among the thieves first, Narlen in particular, or the payday will turn into a trap.]] }, s = [[Talk to Alatos in the Thieves' Guild. Refusing or insulting him makes the guild hostile.
Accept the job: get a spellbook, a statuette and an artifact fragment from the three daughters of Shandalar in Oberan's estate, by talking or by stealing.
Bring the items back to the guild. Alatos and the Halruaan Resar planned to get rid of you.
If you have done the burglary jobs with Narlen and Rededge before, Narlen kills Resar and Alatos backs down. Otherwise you must fight your way out; failing to bring all the items also ends in a fight.]] },
[231290] = { g = [[bg1]], k = [[side]], o = 0, c = [[2-3]], w = [[Around Nashkel]], h = { [[A boy named Albert lost his dog, Rufie, outside Nashkel.]], [[Albert gives you Rufie's chew toy to lure the dog back.]], [[Rufie is no ordinary puppy: decide whether to bring him back or put him down.]] }, s = [[Talk to Albert. If you refuse, the quest ends. If you agree, he gives you Rufie's chew toy.
Search the wilderness outside Nashkel for Rufie; with the chew toy in your inventory, the "dog" follows you.
Lead him back to Albert to reunite them; both then vanish, and it is better not to ask where.
If you kill Rufie instead, Albert becomes your enemy.]] },
[231291] = { g = [[bg1]], k = [[side]], o = 0, c = [[4]], w = [[Cloakwood]], h = { [[In the Cloakwood, a Baldur's Gate noble is in trouble with a band of druids.]], [[Aldeth Sashenstar and the druid Seniyad each want your help.]], [[Fight the druids, side with them, or talk both sides down; Aldeth can invite you to his home.]] }, s = [[In the Cloakwood, meet Aldeth Sashenstar, a merchant noble of Baldur's Gate, under threat from druids led by Seniyad.
Help Aldeth: drive the druids off by force, or find the right words to defuse the conflict. Either way, he invites you to his house in Baldur's Gate, useful later in the city.
Or side with the druids and kill Aldeth: Seniyad thanks you.]] },
[231292] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Baldur's Gate (northwest) / Beregost]], h = { [[The dwarf Pheirkas, in northwest Baldur's Gate, wants a cloak stolen.]], [[Its owner, the fat Algernon, stays at Feldepost's Inn in Beregost.]], [[Pick Algernon's pocket, or take the cloak by force, and bring it to Pheirkas.]] }, s = [[Talk to Pheirkas in the northwest district of Baldur's Gate. He wants Algernon's cloak.
Travel to Beregost and find Algernon at Feldepost's Inn. A thief can pickpocket the cloak; save first, a failed attempt turns him hostile.
Return to Pheirkas in Baldur's Gate and hand it over: he pays well.
You may also keep the cloak instead; it is a magical item.]] },
[231293] = { g = [[bg1]], k = [[side]], o = 0, c = [[2-7]], w = [[Beregost, Thunderhammer Smithy]], h = { [[Taerom "Thunderhammer", the Beregost smith, pays for rare monster parts.]], [[He buys every ankheg shell you bring him.]], [[Kill ankhegs, take their shells and sell them to Taerom for a nice sum each.]] }, s = [[Talk to Taerom "Thunderhammer" at his smithy in Beregost. He offers 500 gold for every ankheg shell.
Hunt ankhegs, which burrow in open farmland and fields, and collect the shells they leave.
Sell each shell to Taerom for 500 gold. Alternatively, have him forge one into ankheg plate mail (see "A New Suit of Armor").
He also mentions the bounty on Bassilus.]] },
[231294] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Baldur's Gate (west) / south of the city]], h = { [[Fenten, an old dwarf in west Baldur's Gate, wants ankheg scales.]], [[A ranger named Gerde manages the ankhegs on the plains south of the city, across the river.]], [[Kill exactly four ankhegs next to Gerde, then go back to her and to Fenten.]] }, s = [[Talk to Fenten in the western part of Baldur's Gate. He tells you about ankhegs south of the city and sends you to Gerde.
Cross the river to the plains south of Baldur's Gate and find Gerde. She shows you where the ankhegs surface and sets a quota of four kills; do not exceed it.
Ankhegs are tough and spit acid: fight them a few at a time.
Return to Gerde for 75 gold, then bring the ankheg parts to Fenten, who pays the agreed price.]] },
[231295] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Sword Coast shoreline]], h = { [[An old sage who speaks in rhymes, Mad Arcand, talks about a ship on the shore.]], [[Something of value waits aboard, and Arcand wants it brought back unused.]], [[Search the wreck on the shoreline, take the bottle and do not open it.]] }, s = [[Talk to Mad Arcand. Through his riddles he mentions a ship along the shoreline holding something valuable, and asks you to bring it to him without using it.
Search the coast of that area for the wreck and loot the mysterious bottle.
The quest ends with the bottle in your hands. Arcand warned you not to open it; whether you do is your choice, so save first if you are curious.]] },
[231296] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Baldur's Gate, Sorcerous Sundries]], h = { [[Ordulinian of the Sorcerous Sundries is tired of two feuding necromancers.]], [[Arkion owns a bloodstone amulet and Nemphre an onyx ring; both live south of the Elfsong Tavern.]], [[Bring both items to Ordulinian instead of to either necromancer.]] }, s = [[Talk to Ordulinian at the Sorcerous Sundries in Baldur's Gate. He wants Arkion's bloodstone amulet and Nemphre's onyx ring to end their feud.
Visit Arkion and Nemphre in their houses south of the Elfsong Tavern. Each asks you to get the other's item; obtaining them may mean a fight with powerful mages.
Give both the ring and the amulet to Ordulinian: he trades you a fine magical cloak.
Giving the amulet to Nemphre instead closes "Arkion's Bloodstone Amulet", but you then cannot complete this quest.]] },
[231297] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Baldur's Gate, south of the Elfsong Tavern]], h = { [[The necromancer Nemphre wants back an amulet her former lover kept.]], [[Arkion, who lives nearby, holds the bloodstone amulet and will not give it up easily.]], [[Get the amulet from Arkion and bring it to Nemphre, or keep it for Ordulinian.]] }, s = [[Talk to Nemphre in her house just south of the Elfsong Tavern in Baldur's Gate. She wants Arkion's bloodstone amulet.
Arkion lives in the same area. He is a capable mage: get the amulet through dialogue, theft or a fight, and be ready for his spells.
Return the amulet to Nemphre: she gives you a magical scroll.
Alternatively, give it with Nemphre's onyx ring to Ordulinian at the Sorcerous Sundries ("Arkion and Nemphre") for a better reward.]] },
[231298] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Ulgoth's Beard]], h = { [[Rumors in Ulgoth's Beard say someone found the ship of Balduran, the city's founder.]], [[A gnome named Dushai sells what she knows for a "research fee".]], [[Pay Dushai to learn of Balduran's last voyage to Anchorome; it leads to the island of his wreck.]] }, s = [[Listen to the townsfolk of Ulgoth's Beard: they talk about Balduran's ship and his last expedition.
Talk to the gnome Dushai and pay her fee. She explains that Balduran sailed for Anchorome and never returned.
This is lore that opens the Tales of the Sword Coast trip to Balduran's island, where the wreck lies (see "Dradeel's Spellbook").]] },
[231299] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Baldur's Gate, docks]], h = { [[Nadarin, on the Baldur's Gate docks, has a dangerous escaped animal on his hands.]], [[A basilisk is loose in a dockside warehouse, turning people to stone.]], [[Protect yourself against petrification, kill the basilisk and report to Nadarin.]] }, s = [[Talk to Nadarin near the docks of Baldur's Gate. A basilisk escaped from a ship and hides in a nearby warehouse.
Before entering, use protection from petrification (potions, spells or items) if you have any; its gaze turns characters to stone.
Enter the warehouse and kill the basilisk, preferably with ranged attacks.
Return to Nadarin for a nice reward.]] },
[231300] = { g = [[bg1]], k = [[side]], o = 0, c = [[2-3]], w = [[Beregost / wilderness]], h = { [[Beregost folk talk of a murdering priest who commands the undead.]], [[Kelddath Ormlyr, at the temple of Lathander east of Beregost, offers a bounty on Bassilus.]], [[Find Bassilus with his undead "family" in the wilds, kill him and bring his holy symbol to Kelddath.]] }, s = [[Hear about Bassilus from the people of Beregost or from Taerom, then talk to Kelddath Ormlyr in the temple of Lathander east of Beregost: 5,000 gold for Bassilus.
Find Bassilus in the wilderness. He is mad, believes his undead are his family and calls you his parent. Footy, a crazed boy, lurks nearby.
Bassilus is a priest who casts spells and commands skeletons: deal with the undead and silence or rush him.
Take his holy symbol and return it to Kelddath for the 5,000 gold reward.]] },
[231304] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Baldur's Gate, docks]], h = { [[Brielbara's baby daughter is under a deadly curse.]], [[The man who cast it, Yago, is aboard the Low Lantern.]], [[Take Yago's spellbook and bring it to Brielbara at the Splurging Sturgeon.]] }, s = [[Talk to Brielbara in Baldur's Gate. Yago cursed her daughter to die, and his spellbook holds the way to lift it.
Go to the Low Lantern, the ship moored at the docks, and find Yago. He is a mage and will not hand it over: expect a spell duel.
Take Yago's spellbook from his body.
Meet Brielbara at the Splurging Sturgeon and give her the book: she can now lift the curse.]] },
[231306] = { g = [[bg1]], k = [[main]], o = 5, c = [[2-3]], w = [[Beregost, Feldepost's Inn]], h = { [[Mulahey's letters, found in the Nashkel mines, mention a go-between named Tranzig.]], [[Tranzig has a room at Feldepost's Inn in Beregost.]], [[Confront him and beat him: he gives up the location of the bandit camp.]] }, s = [[After defeating Mulahey in the Nashkel mines, read his letters: he reported to Tazok through a messenger called Tranzig.
Go to Feldepost's Inn in Beregost and find Tranzig in a room upstairs.
He is a mage and attacks with his allies. Bring him low and he surrenders, confessing that he carried letters between Tazok and Mulahey.
He reveals where the bandits are based, which sends you to Larswood or Peldvale and the bandit camp.]] },
[231307] = { g = [[bg1]], k = [[side]], o = 0, c = [[2-4]], w = [[Where the Cloud Peaks meet the sea]], h = { [[A fisherman named Cordyr complains about monsters on his fishing grounds.]], [[Two sirines haunt the waters near where the Cloud Peaks meet the sea.]], [[Defeat the sirines, ideally with protection against charm, then return to Cordyr.]] }, s = [[Talk to Cordyr the fisherman. A pair of sirines has taken over his fishing grounds, near where the Cloud Peaks meet the sea.
Find the sirines in that area. They can charm and confuse your party, so protect against mind effects if you can and focus them one at a time.
Return to Cordyr after they are dealt with: he gives you a magic scroll.]] },
[231308] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Durlag's Tower]], h = { [[A young adventurer, Dalton, is trapped in the depths of Durlag's Tower.]], [[He survived a deadly test that pitted him against his own double.]], [[Reach Dalton deep in the tower and help him get out alive.]] }, s = [[While exploring the lower levels of Durlag's Tower, you meet Dalton, a young man who barely survived the tower's tests: he had to kill his own double.
Talk to him and agree to help him out.
Once he is safe, the quest closes. If the demon knight is defeated, Clair, a survivor of his group, is relieved to learn that at least one friend lived.]] },
[231309] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Balduran's Isle, village]], h = { [[The historian of the island village, Delainy, needs a small favor.]], [[A sacred cloak blew away from the chieftain's hut in a storm.]], [[Search outside the village walls for the cloak, beware the beasts, and talk with Delainy afterwards.]] }, s = [[In the village on Balduran's island, talk to Delainy, the village historian (her male counterpart Durlyle may appear instead). Refusing ends the quest.
Agree to find the village cloak blown away from the chieftain's hut. Search the wilderness outside the walls, watching out for the "beasts" the locals fear.
Return the cloak to Delainy. Further talks with her can go well or badly depending on your answers.
The villagers hide a dark secret about the island: stay wary.]] },
[231310] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Balduran's Isle]], h = { [[A half-mad elven mage, Dradeel, hides in an old hut on the island.]], [[He was Balduran's navigator and lost his spellbook in the wreck.]], [[Search the chest near Balduran's cabin in the wrecked ship and return the book to Dradeel.]] }, s = [[On Balduran's island, find Dradeel in his old hut. He tells you that Balduran's crew stopped here returning from Anchorome and that lycanthropes now infest the island.
He asks you to get his spellbook from the wreck of Balduran's ship, in a chest near Balduran's cabin.
Explore the wreck (expect undead and other foes) and loot the spellbook.
Bring it back to Dradeel: he takes it and leaves without a word of thanks.]] },
[231311] = { g = [[bg1]], k = [[side]], o = 0, c = [[Prologue]], w = [[Candlekeep]], h = { [[Dreppin, the farmhand in Candlekeep, is worried about his sick cow, Nessa.]], [[The cow needs a potion of antidote, and the guard Hull has some.]], [[Get the potion from Hull at the gate and bring it to Dreppin.]] }, s = [[Talk to Dreppin near the stables of Candlekeep. Nessa the cow is ill and needs a potion of antidote.
Go to the main gate and talk to Hull, the guard on duty there. He uses these potions against his hangovers but gives you one.
Bring the potion back to Dreppin to close the quest and earn a little experience before leaving Candlekeep.]] },
[231312] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Sword Coast]], h = { [[A crying girl, Drienne, begs you to rescue her cat, Pixie.]], [[The cat went over a waterfall in the same area.]], [[Bring the cat back to Drienne, even if it is no longer alive.]] }, s = [[Talk to Drienne. Her cat Pixie fell into a waterfall and she asks you to rescue it.
Search near the waterfall in that area; you will only find the poor cat's body. Pick it up.
Return it to Drienne. She may accuse you of killing Pixie, but she pays you 23 gold, or gives you one of her father's scrolls, who seems to have brought the cat back more than once.]] },
[231313] = { g = [[bg1]], k = [[side]], o = 0, c = [[2-4]], w = [[Cloud Peaks]], h = { [[A dryad in the Cloud Peaks is afraid for her oak tree.]], [[She asks you to protect her tree from those who threaten it.]], [[Help her for good fortune; anger her and she still mentions a wolf cave with treasure to the south.]] }, s = [[In the Cloud Peaks, meet a dryad who asks you to protect her tree.
Agree and defend the oak against those who come for it: she grants you her favor.
If you insult her, she orders you out of her wood, but she also mentions a wolf cave just to the south with a hidden treasure cache.
An evil party can kill her instead.]] },
[231314] = { g = [[bg1]], k = [[main]], o = 14, c = [[7]], w = [[Baldur's Gate, Flaming Fist headquarters]], h = { [[Duke Eltan lies sick in the Flaming Fist compound while Angelo commands in his place.]], [[Kolvar, Kent and a seer all suspect his healer, Rashad.]], [[Stop the attempt on Eltan's life, then escort him to the Harbor Master on the east side of the harbor.]] }, s = [[In chapter 7, learn from rumors, Kolvar, Kent, a charmed smuggler or the seer Delthyr that Eltan is gravely ill, Scar is dead, and the healer Rashad is the one making him sick.
Go to the Flaming Fist headquarters and reach Eltan's sickroom. Rashad turns on you: kill him to stop the assassination.
Eltan asks to be taken to the Harbor Master's building on the east side of the harbor. Escort him there; the Harbor Master promises to hide him.
Then head for the Iron Throne to go after Sarevok.]] },
[231315] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Durlag's Tower]], h = { [[Fenrus in Ulgoth's Beard knows the history of Durlag's Tower and its doppelganger tragedy.]], [[Ward stones open the magical locks of the lower levels; Ike has one.]], [[Durlag's phantom wants the demon knight expelled; Clair suggests turning its Mirror of Opposition against it.]] }, s = [[Learn the tower's story from Fenrus: Durlag killed doppelgangers wearing his family's faces, went mad and filled his home with traps.
At the tower, Bayard warns you about lethal traps, ward stones and a demon knight. Bring a good thief and save often.
Climb the upper floors and go down into the labyrinth, using a ward stone (Ike's or one you find) to pass the sealed doors.
Durlag's phantom asks you to understand the tower's paths, solving its tests (making a sword glow is one), and to drive out the demon knight.
In the depths, Clair explains its Mirror of Opposition, which creates duplicates of your party. Use the mirror against the knight, then destroy it: it is a very strong spellcaster.]] },
[231316] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Balduran's Isle, village]], h = { [[The historian of the island village, Durlyle, needs a small favor.]], [[A sacred cloak blew away from the chieftain's hut in a storm.]], [[Search outside the village walls for the cloak, beware the beasts, and talk with Durlyle afterwards.]] }, s = [[In the village on Balduran's island, talk to Durlyle, the village historian (his female counterpart Delainy may appear instead). Refusing ends the quest.
Agree to find the village cloak blown away from the chieftain's hut. Search the wilderness outside the walls, watching out for the "beasts" the locals fear.
Return the cloak to Durlyle. Further talks with him can make him a friend or leave him cold, depending on your answers.
The villagers hide a dark secret about the island: stay wary.]] },
[231317] = { g = [[bg1]], k = [[companion]], o = 0, c = [[2-3]], w = [[West of Nashkel, Gnoll Stronghold]], h = { [[Near Nashkel, a Red Wizard named Edwin wants a witch dead.]], [[Dynaheir is held in the gnoll stronghold west of Nashkel.]], [[Take Edwin to the stronghold and kill Dynaheir, or refuse him and free her instead.]] }, s = [[Meet Edwin near Nashkel. He asks you to kill Dynaheir, a witch, and joins you if you agree. Declining ends the quest.
Travel west to the gnoll stronghold and fight through the gnolls to Dynaheir.
Kill her to fulfil Edwin's wish. This is an evil path and Minsc, her protector, will not accept it.
You can also dismiss Edwin and drop his alliance. Freeing Dynaheir instead lets her join you.]] },
[231318] = { g = [[bg1]], k = [[companion]], o = 0, c = [[4-5]], w = [[Cloakwood / Baldur's Gate]], h = { [[A bard drinking alone in the Cloakwood has a scheme involving a duke's daughter.]], [[Skie lives in her father's Silvershield estate in Baldur's Gate.]], [[Bring Eldoth with you to the estate, or Skie will treat you as real kidnappers.]] }, s = [[Find Eldoth in the Cloakwood forest, near the bridge where Coran also waits. Share a drink with him and agree to his plan: he joins the party.
When Baldur's Gate opens, go to the Silvershield estate with Eldoth in the group and talk to Skie upstairs. She is a willing runaway.
Invite her into the party to keep both companions. If you refuse to take her, Eldoth leaves with her and you lose them both.
Without Eldoth, Skie refuses to follow you.]] },
[231319] = { g = [[bg1]], k = [[companion]], o = 0, c = [[2]], w = [[Beregost, area north of Beregost]], h = { [[Kagain, the dwarf who runs a shop in Beregost, lost a caravan carrying a noble's son.]], [[The raided caravan lies in the wilderness just north of Beregost.]], [[Walk Kagain to the wrecked caravan near the middle of that map, and do not give him orders while he speaks.]] }, s = [[Kagain hires you in his shop in Beregost: a caravan heading for Baldur's Gate was attacked, and Grand Duke Entar Silvershield's son was aboard. Accepting makes him join the party.
Go quickly to the area directly north of Beregost and look for the burned caravan around the middle of the map. Kagain comments on the scene, the son is found dead and the quest ends.
Do it early: the trail goes cold if you wait too long. If Kagain is interrupted by an order just as he starts talking, the quest may not close.]] },
[231320] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Isle of Balduran (Werewolf Island)]], h = { [[Evalt, a villager on the island, fears his brother Evan was lured away by singing.]], [[The 'blue witch' is a sirine who haunts the west coast in the island's northern part.]], [[Speak kindly to the Blue Lady and she may hand over Evan's body without a fight.]] }, s = [[In the island village (southern map), Evalt asks you to look for his brother Evan, taken by a 'blue witch' singing on the west coast.
Travel to the northern part of the island and follow the western shore to the Blue Lady, a sirine queen. Evan is already dead. Be courteous and she gives you his body; insult or attack her and you must kill her to get it.
Bring Evan's body back to Evalt. He is grieving but grateful, and you earn experience.]] },
[231321] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Wood of Sharp Teeth (forest east of Larswood)]], h = { [[An odd priest named Fahrington wanders the spider-infested Wood of Sharp Teeth.]], [[His stolen scroll went east, carried by a tasloi to an ettercap.]], [[Kill the ettercap to the east, bring the scroll back, and never read it yourself.]] }, s = [[Fahrington is in the Wood of Sharp Teeth, the forest east of Larswood. He lost his 'scroll of wisdom' to a tasloi heading east.
Go east through the woods: the area is full of spiders and ettercaps, and their lairs are often trapped, so search for traps. The ettercap carrying the scroll is in the eastern part.
Return to Fahrington with the scroll. He lets you keep it and you earn experience.
Warning: it is a Cursed Scroll of Foolishness. Reading it ruins Wisdom and lowers Intelligence; sell it or leave it in a pack.]] },
[231323] = { g = [[bg1]], k = [[side]], o = 0, c = [[1]], w = [[North of the Friendly Arm Inn]], h = { [[A worried farmer named Brun stands in front of his farmhouse north of the Friendly Arm Inn.]], [[Brun saw strange tracks heading west of the farm.]], [[Nathan's body lies in the ankheg lair to the west; check its far corner.]] }, s = [[In the area north of the Friendly Arm Inn, talk to Farmer Brun outside his farmhouse and agree to look for his son Nathan.
Head west of the farm and enter the ankheg lair. Ankhegs hit hard and spit acid at low levels, so go in rested. Nathan's body is in the lair's northeast corner, with some good loot.
Bring the body back to Brun for experience. If you then offer him some gold without making it look like charity, you gain extra experience.
If you brush him off, the quest is simply dropped.]] },
[231324] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Isle of Balduran (Werewolf Island)]], h = { [[Little Farthing in the island village has lost her doll.]], [[Someone on the northern half of the island carries it.]], [[The dolly is on the body of Palin, who leads you into a wolfwere ambush up north.]] }, s = [[In the village on the southern part of the island, talk to the girl Farthing; she asks you to bring back her dolly if you find it. Choose friendly replies, as a rude answer can lose the quest.
In the northern part of the island you meet Palin. Whether you follow him or not, he calls wolfweres on you: be ready for a tough fight, with weapons able to hurt them.
Take Farthing's Dolly from Palin's corpse and return it to her in the village for good experience.]] },
[231326] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Gullykin / Firewine Bridge]], h = { [[Gandolar Luckyfoot, the halfling mayor of Gullykin, knows a back way into the Firewine ruins.]], [[Look for a hidden door in the basement of a halfling home, not the temple.]], [[Jenkal's basement hides a secret door behind a bookcase; Jenkal himself is the traitor.]] }, s = [[Talk to Gandolar Luckyfoot in Gullykin. Kobolds are raiding the village from the Firewine ruins, and he tells you a secret entrance starts in one of the halfling burrows.
Go to Jenkal's house and down to his basement. Jenkal is the one letting the kobolds in, so expect a fight. Search behind the bookcase for the secret door into the ruins.
This route takes you close to the ogre mage behind the raids and avoids many kobold commandos. A second passage links the ruins to the temple basement.
Kill the ogre mage, then report to Gandolar for a gold reward.]] },
[231327] = { g = [[bg1]], k = [[main]], o = 8, c = [[4]], w = [[Cloakwood Mines]], h = { [[Slaves, guards and the dwarf Yeslick all know who runs the Iron Throne mine.]], [[The mine's master, the mage Davaeorn, lives on the fourth level and holds the key to a steel plug.]], [[Kill Davaeorn, take the key from the chest in his bedroom, and use it on the plug on the first level.]] }, s = [[Enter the Iron Throne mine in the Cloakwood. Talk to the slave miners and to Yeslick, a dwarf held on the second level who can join you: a magical steel plug holds back an underground river.
Go down to the fourth level and defeat Davaeorn, a mage who teleports and summons help; bring spell protection. Read his papers: they matter for the next chapter.
Take the key from the chest in his bedroom, return to the first level and use it on the plug. Run for the exit as the water pours in.
Flooding is optional. Warn the slaves first if you want to spare them; drowning them is the evil path.
Davaeorn's death ends chapter 4 and opens Baldur's Gate.]] },
[231328] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Isle of Balduran, village]], h = { [[Delainy, a friendly village woman, wants flowers that grow beyond the village walls.]], [[Search the land outside the walls; a locked chest in a cabin up north also holds flowers.]], [[Bring the flowers back; how you treat her afterwards decides whether she stays a friend.]] }, s = [[This version appears for a male main character. In the island village, talk to Delainy and agree to fetch the flowers she wants; they grow outside the village walls.
Search outside the walls. If you cannot find them, a locked chest in Dradeel's cabin in the north of the island contains belladonna flowers.
Give her the flowers: she kisses you. Asking her to come with you to the mainland unsettles her; she refuses but stays your friend.
Evil choice: toy with her feelings and leave her once you have what you want.]] },
[231329] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Isle of Balduran, village]], h = { [[Durlyle, a friendly village man, wants flowers that grow beyond the village walls.]], [[Search the land outside the walls; a locked chest in a cabin up north also holds flowers.]], [[Bring the flowers back; how you treat him afterwards decides whether he stays a friend.]] }, s = [[This version appears for a female main character. In the island village, talk to Durlyle and agree to fetch the flowers he wants; they grow outside the village walls.
Search outside the walls. If you cannot find them, a locked chest in Dradeel's cabin in the north of the island contains belladonna flowers.
Give him the flowers: he kisses you. Asking him to come with you to the mainland unsettles him; he refuses but stays your friend.
Evil choice: toy with his feelings and leave him once you have what you want.]] },
[231330] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Baldur's Gate, Blade and Stars]], h = { [[A hesitant fortune-teller at the Blade and Stars inn will read your future for a price.]], [[G'axir wants a sphene gem; gem traders and dangerous monsters may have one.]], [[The basilisk lurking in a Baldur's Gate warehouse leaves a sphene gem behind.]] }, s = [[In southeast Baldur's Gate, enter the Blade and Stars inn and talk to G'axir the Seer. He predicts a dark future and asks for a sphene gem.
Any sphene gem will do. One sure source is the greater basilisk in a city warehouse, linked to the dwarf Nadarin's request; protect yourself against petrification before that fight.
Give the gem to G'axir. His prophecy is short and vague, but the trade earns you experience.]] },
[231331] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Durlag's Tower, outside]], h = { [[The ward token you bought from Galken may open a door somewhere in Durlag's Tower.]], [[Keep it in your pack while you explore; most bought wardstones are of little use.]], [[The real wardstones you need are found inside the tower itself.]] }, s = [[This entry follows Galken's Wares: once you buy Galken's ward token in a building near Durlag's Tower, he warns that its former owner may want it back.
There is no real task. Carry the stone while you explore the tower and its dungeons. The wardstones required to pass the labyrinth levels and the throne room door are found inside the tower, so do not count on this one.
It cannot be sold back, so drop it when you are done if it proves useless.]] },
[231332] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Durlag's Tower, outside]], h = { [[A shifty man named Galken has something to sell near Durlag's Tower.]], [[Visit the buildings around the tower to find him again.]], [[His ware is a ward token; buying it is optional and rarely worth much.]] }, s = [[In the area outside Durlag's Tower, Galken waits inside one of the buildings and offers you something for sale.
Talk to him and pay if you wish: he sells a ward token said to open a door deep in the tower. Buying it adds the entry Galken's Wardstone.
The purchase is optional. The wardstones you actually need are found inside the tower, and another seller nearby, Delsvirftanyon, offers wardstones too.]] },
[231333] = { g = [[bg1]], k = [[companion]], o = 0, c = [[1-2]], w = [[Beregost]], h = { [[A wandering bard is looking for help in Beregost.]], [[Garrick works for an actress named Silke whose 'performance' is not what it seems.]], [[Deal with Silke and Garrick offers to join you.]] }, s = [[Garrick is a bard found in Beregost. He serves the actress Silke, who wants you to help with a staged show that is really an ambush.
Talk to Garrick and Silke. Refusing Silke and fighting her, or settling the matter otherwise, frees Garrick, who then offers to travel with you.
The journal entry only records that you met him; accept him into the party whenever you like. He is a neutral bard with songs and some spells.]] },
[231334] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Baldur's Gate]], h = { [[This entry closes the story of the cursed man Ghorak.]], [[If his curse was lifted, there is nothing left to do.]], [[Visit Ghorak once more after the skull reaches the Lady's Hall to get this ending.]] }, s = [[This is the ending of Ghorak the Diseased.
After you hand Kereph's skull to Agnasia, the priestess of Tymora in the Lady's Hall (west Baldur's Gate), return to Ghorak and tell him. Tymora's curse is lifted and both brothers are at peace.
If you have not started it, see Ghorak the Diseased: the skull hides behind a painting in the Three Old Kegs.]] },
[231335] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Baldur's Gate]], h = { [[Ghorak suffers from a wasting curse tied to the death of his brother Kereph.]], [[Kereph's skull hides behind a painting in the Three Old Kegs inn, in the north of the city.]], [[Give the skull to Agnasia at the Lady's Hall, then go back to Ghorak.]] }, s = [[Talk to Ghorak in Baldur's Gate and offer to cure him. Tymora cursed him for killing his brother Kereph.
Go to the Three Old Kegs in north Baldur's Gate. Kereph's skull is hidden behind a painting upstairs, near the staircase.
Take it to Agnasia, the priestess of Tymora in the Lady's Hall, in west Baldur's Gate.
Return to Ghorak: the curse is gone and the quest ends as Ghorak the Cured!]] },
[231336] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Firewine Ruins]], h = { [[The ghostly knights in the Firewine ruins cannot rest until their lost comrade rejoins them.]], [[Their missing brother still walks the ruins as an undead knight.]], [[Destroy the undead knight and bring his ancient plate armor to the ghosts.]] }, s = [[In the Firewine ruins under Firewine Bridge and Gullykin, talk to the ghostly knights. They say they cannot leave until all are one.
Search the ruins for their traitorous comrade, an undead knight. Defeat him (bring magic weapons and undead protection) and take his ancient armor.
Bring the armor to the ghosts. You can hand it over for a large experience reward and lay them to rest, or trade it for the sword Vampire's Revenge, which hurts its wielder.
Do not provoke the ghosts: fighting them is long and hard.]] },
[231337] = { g = [[bg1]], k = [[side]], o = 0, c = [[1-2]], w = [[Beregost and nearby farmlands]], h = { [[This is a rumour picked up in Beregost, not a formal job.]], [[The 'giant insects' are ankhegs burrowing under the farmlands of the region.]], [[Ankheg nests near the farms, such as the one west of Farmer Brun's farm, hold loot and hard fights.]] }, s = [[Beregost locals complain about giant insects. They mean ankhegs, large burrowing beasts that erupt from the ground in the farmlands of the Sword Coast.
There is no quest giver or reward for this rumour. Hunting ankhegs pays in experience and in ankheg shells, which a smith in Beregost can turn into good armor.
Ankhegs spit acid and hit hard: go rested, ranged attacks help. Their lair west of Farmer Brun's farm, north of the Friendly Arm Inn, is also where Brun's son lies.]] },
[231338] = { g = [[bg1]], k = [[side]], o = 0, c = [[6]], w = [[Candlekeep, library]], h = { [[Back in Candlekeep, Tethtoril reminds you that Gorion left something for you.]], [[Gorion's old room is inside the library, on one of the upper floors.]], [[Search every container in Gorion's room to find his letter and gear.]] }, s = [[When you return to Candlekeep in chapter 6, climb the library and talk to Tethtoril. He tells you Gorion left items for you in his chambers.
Find Gorion's room in the library and loot its containers: you get an inheritance letter, a Ring of Protection +1 and a Wand of Magic Missiles.
Grab them before things turn against you in the library: once the main plot moves on, leaving with them is harder.]] },
[231339] = { g = [[bg1]], k = [[side]], o = 0, c = [[4]], w = [[Beregost / Cloakwood]], h = { [[Gurke, a grumpy dwarf at the Jovial Juggler in Beregost, lost his prized cloak.]], [[Tasloi took it into the first Cloakwood forest area.]], [[The tasloi carrying it lurk in the southeast corner of that forest map.]] }, s = [[Talk to Gurke inside the Jovial Juggler in Beregost. A band of tasloi stole his cloak in the Cloakwood.
Travel to the first Cloakwood forest area and look in the southeast corner. Kill the tasloi there (they flee when losing) and take the Cloak of Non-Detection.
Return to Gurke for experience. Depending on how it plays out, he pays you or, now a local folk hero, lets you keep the cloak.]] },
[231340] = { g = [[bg1]], k = [[side]], o = 0, c = [[1-2]], w = [[Beregost / mountains south-southwest]], h = { [[A wounded paladin named Bjornin rests at the Jovial Juggler inn in Beregost.]], [[The half-ogres have dug in somewhere south-southwest of town.]], [[There are four of them and they wander; hunt down every one before returning.]] }, s = [[Talk to Bjornin in the Jovial Juggler in Beregost. He asks you to wipe out a band of half-ogres in the mountains south-southwest of town.
Travel to that wilderness area and look for them near an abandoned house. There are four half-ogres; they hit hard and roam apart, so you may need to search for the last one.
Return to Bjornin. He rewards you with his shield, a magical medium shield, plus experience and a little reputation.]] },
[231341] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Ulgoth's Beard, inn]], h = { [[A dwarf named Hurgan Stoneblade wants to hire you at the Ulgoth's Beard inn.]], [[His job sends you to the very bottom of Durlag's Tower.]], [[He wants his grandfather's dagger, Soultaker, but cultists will try to take it from you.]] }, s = [[Enter the inn at Ulgoth's Beard: Hurgan Stoneblade approaches and offers work. Hear him out; you can bargain over the reward.
He wants his grandfather's dagger Soultaker, kept at the deepest level of Durlag's Tower.
Once you retrieve it and return to Ulgoth's Beard, cultists seize the dagger, so you usually never hand it to Hurgan or get his payment. A skilled thief can still pick his pocket for a good item.
The tower is very dangerous: bring trap detection and strong protections.]] },
[231342] = { g = [[bg1]], k = [[main]], o = 9, c = [[5]], w = [[Baldur's Gate, Iron Throne building]], h = { [[Rumours, drunks and charmed officials all point to the Iron Throne's new headquarters in southwest Baldur's Gate.]], [[Duke Eltan of the Flaming Fist wants you to infiltrate that tower.]], [[Fight up to the fifth floor, make the leaders talk, then report back to Duke Eltan.]] }, s = [[In Baldur's Gate, gather clues: Husam at the Elfsong Tavern names the leaders (Brunos, Thaldorn, Rieltar), the Harbor Master tracks iron shipments, and Sarevok's name keeps coming up.
Finish Scar's tasks at the Flaming Fist and meet Duke Eltan at their headquarters; he asks you to infiltrate the Iron Throne building in the southwest of the city.
Climb the tower floor by floor. Dra'tan, Triadore and Emissary Tar reveal the mine deals and a sect of Sarevok's followers on the fifth floor. Expect hard fights on the upper floors.
On the top floor, defeat or threaten the leaders: Thaldorn reveals that Rieltar and Brunos have gone to Candlekeep.
Return to Duke Eltan; he gives you the means to enter Candlekeep, starting chapter 6.]] },
[231343] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Baldur's Gate, Merchants' League Estate]], h = { [[Aldeth Sashenstar, whom you may have helped in the Cloakwood, worries about his partners.]], [[Brandilar, the guard captain, suspects Zorl and Irlentree; Zorl's office on the second floor is worth a search.]], [[Show Brandilar the letters from Zorl's desk, then kill every doppelganger, including those at the third-floor party.]] }, s = [[This quest is offered only if you sided with Aldeth against the druids in the Cloakwood. Meet him in the Merchants' League Estate in Baldur's Gate; he waits on the second floor.
Talk to Brandilar, the guard commander, who distrusts Zorl and Irlentree. Search the locked desk in Zorl's office on the second floor for three letters and show them to Brandilar.
Zorl turns into a doppelganger: kill him. Irlentree invites you to Aldeth's anniversary party on the third floor, where more doppelgangers reveal themselves.
Clear the whole building, then report to Aldeth. He gives you Kondar, a bastard sword that is extra effective against shapeshifters, and experience.]] },
[231344] = { g = [[bg1]], k = [[main]], o = 3, c = [[2]], w = [[Nashkel Mines]], h = { [[The guards at the Nashkel mines send you to the foreman, Emerson, first.]], [[Miners speak of 'dog people' in the lower levels: the culprits are kobolds tainting the ore.]], [[Go down to the deepest level, deal with Mulahey, then report to Emerson and the mayor of Nashkel.]] }, s = [[East of Nashkel, talk to Emerson outside the mine; he lets you in. Question miners and guards for clues about creatures below.
Descend through the levels. Kobolds and their traps grow thicker as you go; on level 3 look for Joseph's body for another quest.
On the bottom level, cross the water and confront Mulahey, a half-orc priest who controls the kobolds and has been tainting the iron. Fight him (he summons skeletons) or charm him to make him talk. Free the elf Xan from his cell if you want a companion.
Read Mulahey's papers: they point to the bandits.
Leave the mine, tell Emerson, then claim your reward from the mayor of Nashkel. Chapter 3 begins.]] },
[231345] = { g = [[bg1]], k = [[companion]], o = 0, c = [[1]], w = [[Friendly Arm Inn / Nashkel]], h = { [[Gorion's old friends Jaheira and Khalid wait for you at the Friendly Arm Inn.]], [[They want to investigate the iron troubles in Nashkel, far to the south.]], [[Head to Nashkel without too much delay, or they will grumble and may leave.]] }, s = [[Reach the Friendly Arm Inn and find Jaheira and Khalid; Gorion arranged the meeting. They join you together and ask to travel to Nashkel.
Go south through Beregost to Nashkel and on to the Nashkel mines, the main chapter 2 goal. If you wander too long elsewhere, they complain and may quit.
Once Nashkel's mystery is under way their request is met, and they stay with you as long as your reputation suits them.]] },
[231346] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Wilderness north of the Gnoll Stronghold]], h = { [[A frightened merchant named Jared hides in the mountains north of the Gnoll Stronghold.]], [[The bear blocking his way waits on the other side of the bridge.]], [[Kill the bear and tell Jared; a good reputation earns a better reward.]] }, s = [[In the ogre-infested wilderness north of the Gnoll Stronghold, meet Jared near a bridge. A bear has claimed the far side.
Cross the bridge and kill the bear, a strong one worth plenty of experience.
Return to Jared. He pays according to your reputation: the Boots of the North if it is high, some gold if middling, nothing if low. A thief can pick his pocket for the boots, or an evil party can simply kill him.]] },
[231347] = { g = [[bg1]], k = [[side]], o = 0, c = [[1]], w = [[Friendly Arm Inn]], h = { [[Joia, an old woman inside the Friendly Arm Inn, lost a precious ring.]], [[Hobgoblins stole it just north of the inn, outside the walls.]], [[Kill the hobgoblins to the northwest of the inn's grounds and bring her the flamedance ring.]] }, s = [[Talk to Joia in the Friendly Arm Inn. Hobgoblins took her flamedance ring just north of the inn.
Leave the inn compound and search the northwest part of the map. Kill the hobgoblins and take the ring from their remains; make sure it is her ring, not another one.
Return it to Joia. She has no gold to give, but you earn experience and reputation.]] },
[231348] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Isle of Balduran, north]], h = { [[A grieving woman named Kryla asks you to avenge Jondal, slain by wolf-men.]], [[Her story is a little too convenient on this island of shapeshifters.]], [[Following her leads straight into a wolfwere ambush: buff up and bring magic weapons.]] }, s = [[In the northern part of the island, Kryla tells you wolf-men killed Jondal and begs you to chase them.
It is a trap. Jondal is one of the wolfweres, and Kryla leads you into an ambush.
Prepare before you follow her: wolfweres need magic or silver weapons to hurt, and several attack at once. Defeat the pack to close the quest and earn the experience of the fight. You can also refuse and attack her on the spot.]] },
[231349] = { g = [[bg1]], k = [[side]], o = 0, c = [[2]], w = [[Nashkel / Nashkel Mines]], h = { [[A young woman in a Nashkel house is waiting for her missing husband, a miner.]], [[Joseph disappeared in the mines; he wore a greenstone ring.]], [[His body and ring lie on the third level of the Nashkel mines.]] }, s = [[In Nashkel, enter the house southeast of the road to the bridge and talk to the woman there. Her husband Joseph vanished in the mines; he wears a greenstone ring.
Explore the Nashkel mines down to the third level. Joseph's corpse lies there, with his Greenstone Ring close by to the north.
Bring the ring back to his wife and tell her what happened. You cannot save him, but you earn experience.
Pick up the ring when you find it: some players report it vanishing later.]] },
[231350] = { g = [[bg1]], k = [[companion]], o = 0, c = [[2]], w = [[Beregost, area north of Beregost]], h = { [[Kagain, the dwarf merchant of Beregost, will join you to look for a lost caravan.]], [[The caravan carried Entar Silvershield's son and was raided north of Beregost.]], [[Take Kagain to the burned caravan near the middle of the area north of Beregost, without delay.]] }, s = [[This is the same story as Entar's Son.
In his shop in Beregost, Kagain asks for help finding a missing noble, the son of Grand Duke Entar Silvershield, whose caravan was attacked. Accept and he joins the party.
Go to the wilderness area directly north of Beregost and walk to the destroyed caravan around the middle of the map. Kagain reacts, the son is found dead and the quest closes.
Act early, since waiting too long can spoil it, and do not click orders on Kagain while he is about to speak.]] },
[231351] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Isle of Balduran (Werewolf Island)]], h = { [[The villagers fear the man-wolves to the north, led by a brute named Karoug.]], [[Talking gets you nowhere with Karoug; only a fight settles it.]], [[Prepare magic or silver weapons and protections before facing Karoug and his wolfweres.]] }, s = [[On the island, villagers such as Jorin speak of the wolfweres to the north and their leader Karoug.
Travel north and find Karoug. Whatever you say, he refuses to back down, so the meeting ends in combat.
Wolfweres can only be hurt by magic or silver weapons and fight in packs; rest and buff before the encounter.
Killing Karoug rids the island of a major threat and helps you with the islanders and with the rest of the island's story.]] },
[231352] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Baldur's Gate, northwest]], h = { [[Twin girls in a large house in northwest Baldur's Gate are being watched at night.]], [[Both Gervisse and the druid Voltine accuse each other; listen to both before acting.]], [[Voltine tells the truth: Gervisse is the 'bogeyman'.]] }, s = [[In northwest Baldur's Gate, visit the twins Laerta and Louise in their large house. They talk of a bogeyman at their window.
Old Gervisse asks you to kill Voltine, a shapeshifting druid. Meet Voltine too: despite a rough start, she says Gervisse is a voyeur preying on the girls.
Good path: kill Gervisse. Voltine thanks you with a Wand of Polymorphing. Then talk to Laerta again for experience and a protection scroll.
If you kill Voltine instead, Gervisse thanks you with no reward and you earn little.]] },
[231355] = { g = [[bg1]], k = [[side]], o = 0, c = [[1-2]], w = [[Friendly Arm Inn / Beregost]], h = { [[A gnome named Landrin at the Friendly Arm Inn fled her house in Beregost.]], [[Her house stands just west of the Jovial Juggler; giant spiders fill its cellar.]], [[Bring her the biggest spider's body, her husband's old boots and her bottle of wine for three payments.]] }, s = [[Talk to Landrin upstairs in the Friendly Arm Inn. Spiders drove her from her home in Beregost, just west of the Jovial Juggler inn.
In Beregost, enter her house and go down to the cellar. Kill the spiders; their bites are poisonous, so bring antidotes or Slow Poison. Take the body of the biggest spider, then search the cellar for her husband's old boots and her bottle of wine.
Return to Landrin at the Friendly Arm Inn. She pays for each item: gold for the wine, more for the spider body, the most for the boots. Delivering all three completes her tasks.]] },
[231357] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Baldur's Gate, Elfsong Tavern / Hall of Wonders]], h = { [[A gnome named Brevlik at the Elfsong Tavern wants a 'telescope' from the Hall of Wonders.]], [[The Hall of Wonders is crowded and guarded by day; try at night.]], [[Steal the telescope quietly, without bloodshed, and bring it to Brevlik at the Elfsong.]] }, s = [[At the Elfsong Tavern, Brevlik the gnome hires you to steal a telescope from the Hall of Wonders, the museum near the temple of Gond.
Go at night, when the hall is almost empty. Steal the telescope from its display with a skilled thief. At night you may also meet the halfling thief Alora there, who can join you.
Return to Brevlik at the Elfsong for your reward.
If you got it in a way he dislikes, for example by causing a fight, he refuses to pay; you can walk away or force the issue with him.]] },
[231358] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Wilderness south of High Hedge]], h = { [[Kissiq, a rattled traveller in the wilds near High Hedge, swears a hen spoke to him.]], [[The 'fiendish hen' is somewhere east of where you met Kissiq.]], [[The chicken is Melicamp, a mage under a curse; see his own quest.]] }, s = [[Kissiq, a merchant wandering the wilderness south of High Hedge, tells you about a talking chicken to his east.
Walk east on the same map. The chicken is Melicamp, a young wizard turned into a hen; a wolf stalks him, and he will not talk until it is dead.
This entry is only a lead: continue with Melicamp the Chicken. It cannot be completed on its own, and it stays open if Melicamp was already restored or died.]] },
[231359] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Isle of Balduran, village]], h = { [[A villager named Maralee weeps outside the village gate over her missing child.]], [[Wolf creatures beyond the walls carried the child away.]], [[Search the wolfwere-held lands of the island and bring the child home to Maralee.]] }, s = [[Near the main gate of the island village, Maralee begs you to rescue her child, captured by the wolf creatures. You may refuse, which closes the quest.
Explore the island outside the walls, where the wolfweres roam. Expect fights that require magic or silver weapons. Find the child and escort them back.
Return to Maralee. She is overjoyed, you gain experience and a friend in the village, which helps with the wary islanders.]] },
[231360] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Baldur's Gate]], h = { [[Lothander, an Iron Throne assassin, says his partner Marek has poisoned you.]], [[To lift Lothander's geas, consult the diviner at the marketplace, then Jalantha at the temple of Umberlee.]], [[Fetch the holy book from the Lady's Hall for Jalantha, then get both halves of the antidote.]] }, s = [[In Baldur's Gate, Lothander tells you Marek poisoned you: you have about a week or two to live. He offers the antidote if you free him from a geas.
Pay the diviner in the marketplace tent: only Jalantha Mistmyr, at the Water Queen's House (temple of Umberlee), can lift it.
Jalantha wants a holy book kept at the Lady's Hall, the temple of Tymora. Persuade the priest there or pay for it, then bring it to her.
Meet Lothander at the Blade and Stars inn. He gives you half the antidote; Marek holds the other half at the Blushing Mermaid.
Kill Marek or trick him into handing it over. Without both halves, the poison kills you.]] },
[231362] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Wilderness south of High Hedge / High Hedge]], h = { [[A talking chicken in the wilds south of High Hedge is really a cursed wizard.]], [[Kill the wolf hunting him, then escort Melicamp to the mage Thalantyr at High Hedge, west of Beregost.]], [[Thalantyr needs a skull: the skeletons around High Hedge drop them.]] }, s = [[In the wilderness south of High Hedge, find Melicamp, a wizard stuck as a chicken. Kill the wolf stalking him first, then talk to him.
Take him to Thalantyr at High Hedge, west of Beregost. Thalantyr asks for a skull to undo the spell.
Kill skeletons in the High Hedge area; they drop skulls. Bring one to Thalantyr and stay to watch: if you leave him to it, you get no reward.
The spell has an even chance of success. Save before handing over the skull. If Melicamp survives you earn good experience and reputation (see Melicamp's Transformation).]] },
[231363] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[High Hedge]], h = { [[This entry records how Thalantyr's spell on Melicamp turned out.]], [[The outcome is pure luck; nothing you say changes it.]], [[Save before giving Thalantyr the skull and reload if Melicamp dies.]] }, s = [[Once you bring Thalantyr a skull at High Hedge (see Melicamp the Chicken), he casts his spell on Melicamp while you watch.
Success: Melicamp becomes human again, vows to learn from his mistakes, and you earn experience and reputation.
Failure: his body cannot take another transformation and he dies. Thalantyr says it was only chance.
The roll is random, so save before handing over the skull if you want the good ending.]] },
[231364] = { g = [[bg1]], k = [[side]], o = 0, c = [[2-3]], w = [[Beregost]], h = { [[A worried wife in Beregost waits for news of her husband, who travelled south to Amn.]], [[Any news of Roe will come from the southern road toward Amn.]], [[Bring Mirianne the letter found on a dead halfling messenger.]] }, s = [[Talk to Mirianne in her house in Beregost: her husband Roe left for Amn and she fears for him. Promise to keep an eye out.
On the road south toward Amn, a band of ogres attacks a halfling messenger. Drive them off or kill them, then search the body: a letter from Roe is sewn into his vest (see Mirianne's Letter).
Return to Mirianne and hand over the letter. It brings good news, and she thanks you with a simple protective ring.]] },
[231365] = { g = [[bg1]], k = [[side]], o = 0, c = [[2-3]], w = [[Road to Amn / Beregost]], h = { [[Ogres on the road toward Amn have just killed a small traveller.]], [[Search the halfling messenger's body carefully once the ogres are gone.]], [[The letter is for Mirianne of Beregost: deliver it to her.]] }, s = [[In the wilderness along the southern road toward Amn, you come upon ogres attacking a halfling messenger. Fight them off; ogres hit hard, so keep weak characters back.
Search the dead halfling: a letter from Roe, addressed to Mirianne of Beregost, is sewn into his vest.
Take it to Mirianne in Beregost. This also completes Mirianne's Husband and earns you her ring.]] },
[231366] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Baldur's Gate, eastern sewers]], h = { [[Scar of the Flaming Fist is worried about people vanishing in the eastern part of the city.]], [[The answer lies below the streets, in the sewers under the east side of Baldur's Gate.]], [[An ogre mage lairs down there: kill it and report to Scar.]] }, s = [[Scar, waiting outside the Flaming Fist compound in the southwest of Baldur's Gate, asks you to find out why citizens are disappearing on the east side.
Enter the sewers from a grate in the eastern districts and explore them. Deep inside you meet the culprit, an ogre mage, with its minions. It casts spells and can turn invisible: dispel or detect it and focus it down.
Return to Scar outside the Flaming Fist barracks to report and collect your reward.]] },
[231367] = { g = [[bg1]], k = [[side]], o = 0, c = [[1-3]], w = [[Peldvale]], h = { [[A Flaming Fist soldier is hunting someone in the woods east of the main road.]], [[His target is a drow cleric; charm him and he will tell you why.]], [[When he attacks the drow, take a side: she joins you if you help her.]] }, s = [[In Peldvale you meet the drow Viconia, soon followed by a Flaming Fist mercenary who wants her dead.
If you charm him before the fight, he explains that his unit is chasing a drow who murdered a family. That is all this journal entry adds.
You can kill the soldier and let Viconia join the party (she is evil), or let him fight her. Killing a Flaming Fist member may cost reputation, so decide before swords come out.]] },
[231368] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Baldur's Gate]], h = { [[A mother in Baldur's Gate wants a good luck charm delivered to her runaway son.]], [[Euric likes to hang around one of the city's many taverns.]], [[Give Euric the amulet, then bring his message back to Nadine.]] }, s = [[Nadine of Baldur's Gate gives you an amulet for her son Euric, who has run off again.
Visit the city's taverns until you find Euric. Hand him the amulet; he takes it without much joy and asks you to tell his mother he misses her.
Go back to Nadine and tell her he is safe. She rewards you with another amulet.]] },
[231369] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Baldur's Gate]], h = { [[A thief named Narlen Darkwalk is looking for a partner with light fingers; only a thief may deal with him.]], [[Keep the rest of the party out of sight, and never hurt a city guard during the job.]], [[On the first job, raise the alarm when trouble comes; on the second, you do the stealing yourself.]] }, s = [[A thief of your party meets Narlen Darkwalk near the Splurging Sturgeon; the others must stay out of sight or he calls it off.
Job 1: at the De'Mallonblade house, Narlen and Rededge go in while you watch. When a guard comes, call the alarm and run; do not fight. Failing to warn them gets Rededge killed and turns Narlen against you; killing a guard ends the partnership.
Meet at the Thieves' Guild. If it went well, Narlen plans a second job: meet by the Blade and Stars, again with only the thief visible, then sneak into Gantolandan's place yourself and steal his valuable rogue stone.
Return to the Thieves' Guild to split the loot and earn the guild's respect.]] },
[231370] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Baldur's Gate]], h = { [[A youngster on the streets of Baldur's Gate pays good gold just for a meeting.]], [[Accept Niklos's offer and follow him to the building he leads you to.]], [[If someone asks for a password, answer Fafhrd.]] }, s = [[In Baldur's Gate a youngster named Niklos approaches you and offers 50 gold to meet his master.
If you refuse, the entry closes there. If you accept, take the gold and follow him to a nondescript building.
When you are asked for the password, give Fafhrd and you are let in to meet his master. What you do with the offer you hear inside is up to you.]] },
[231371] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Baldur's Gate, docks]], h = { [[A half-elf dock worker has lost her brand new gauntlets.]], [[She lost them somewhere on her way between the harbor and her warehouse.]], [[Search the ground and containers along the docks, then bring them back to Noralee.]] }, s = [[Noralee, a half-elf working in the harbor district of Baldur's Gate, lost her new gauntlets somewhere between the harbor and the warehouse where she works.
Walk the docks between those two places and check the ground and nearby containers until you find a pair of gauntlets.
Return them to Noralee for a small reward.]] },
[231372] = { g = [[bg1]], k = [[side]], o = 0, c = [[3-4]], w = [[Beregost]], h = { [[A girl named Chloe carries a message for you from the Flaming Fist.]], [[Officer Vai waits at the Jovial Juggler in Beregost.]], [[Vai pays a bounty for the scalps of bandits: keep the ones you find.]] }, s = [[Chloe tells you that Officer Vai of the Flaming Fist wants to see you at the Jovial Juggler in Beregost.
Go to the inn and talk to Vai. She is collecting bounties on the bandits plaguing the region and pays for every bandit scalp you bring her.
Bandits killed around the Sword Coast often carry scalps; keep them and sell them to Vai whenever you pass through Beregost.]] },
[231373] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Sword Coast wilderness]], h = { [[A confused dwarven fighter named Sarhedra has a warning about ogres.]], [[The ogre camp lies to the south of where you meet her.]], [[Kill the ogres and report back, but do not expect much of a reward.]] }, s = [[Talk to Sarhedra, a muddled dwarven fighter you meet in the wilderness. She warns you of an ogre encampment to the south.
Head south and wipe out the ogres. They hit hard: let tanks hold them and use ranged attacks and spells.
Report back to Sarhedra. She gets so flustered looking for another job for you that she forgets to pay; the experience from the ogres is your only real reward.]] },
[231374] = { g = [[bg1]], k = [[main]], o = 13, c = [[7]], w = [[Baldur's Gate, Undercellar]], h = { [[Sarevok's lover Cythandria knows where he spends his time.]], [[She points you to the Undercellar, a hidden brothel.]], [[Reach the Undercellar through the sewers of Baldur's Gate.]] }, s = [[While searching Sarevok's base in Baldur's Gate, you confront Cythandria. She reveals that Sarevok can be found at the Undercellar, a brothel reached through the city's sewers.
Go down into the sewers and find the way to the Undercellar. Sarevok himself is not waiting for you there, but his assassins Slythe and Krystin are (see Slythe and Krystin), and their papers lead you on toward the Ducal Palace.]] },
[231375] = { g = [[bg1]], k = [[side]], o = 0, c = [[2]], w = [[Nashkel]], h = { [[The bounty officer in Nashkel mistakes you for a hunter named Greywolf.]], [[Taking his money now has a price later.]], [[Set him straight and refuse the 200 gold if you want the full bounty on Prism.]] }, s = [[In his office in Nashkel, Oublek mistakes you for Greywolf, a bounty hunter he hired, and offers you money.
Honest choice: tell him he has the wrong person. You give up the quick gold, but he will later pay you the full bounty for the emeralds Prism stole (see Prism the Sculptor).
Greedy choice: take the 200 gold. It is easy money, but when you bring back the emeralds Oublek refuses to pay you (see Payment Denied!), so you lose more than you gained.]] },
[231376] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Sword Coast]], h = { [[An eager young man named Palin wants help routing some monsters.]], [[Let him lead the way, but keep your guard up.]], [[It is an ambush: be ready to fight as soon as you arrive.]] }, s = [[Talk to Palin, a young man who claims some monsters must be routed before they do harm. Agree to help and he leads the way.
Prepare the party before following him: buff, and keep fragile characters behind.
When you reach the spot, the creatures ambush you and fight cleverly. Defeat them to end the episode.]] },
[231377] = { g = [[bg1]], k = [[side]], o = 0, c = [[2]], w = [[Nashkel]], h = { [[This entry appears when Oublek refuses to pay you a bounty.]], [[He remembers the 200 gold he gave you by mistake.]], [[Next time, refuse money that was meant for Greywolf.]] }, s = [[This is the bad outcome of Oublek the Bounty Officer. If you accepted the 200 gold Oublek meant for Greywolf, he will not pay the bounty when you return Prism's emeralds to him in Nashkel.
There is no way to recover the reward afterwards. To avoid it, refuse the money when Oublek first mistakes you for Greywolf, then claim the full bounty for the emeralds.]] },
[231378] = { g = [[bg1]], k = [[side]], o = 0, c = [[1-2]], w = [[Beregost / near High Hedge]], h = { [[A halfling named Perdue lost his short sword to some gnolls.]], [[The gnolls lurk on the plains west of Beregost, close to High Hedge.]], [[Kill the gnolls, take the sword, and decide whether to give it back.]] }, s = [[Talk to Perdue the halfling; however you treat him, you can agree to recover the short sword some gnolls stole from him.
Travel to the plains west of Beregost, near Thalantyr's High Hedge. Find the band of gnolls there and kill them; they hit hard for early levels, so fight them together.
Pick up the short sword from their loot and return it to Perdue. His thanks and reward are stingy. The sword is a good weapon for a thief, so keeping it is a valid choice.]] },
[231379] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Baldur's Gate]], h = { [[An orphan named Petrine has lost her cat Angel, and a man named Bheren hates a cat near his house.]], [[Angel hangs around Bheren's house, along with the ring it plays with.]], [[Bring the ring to Petrine for the kind ending, or kill the cat for Bheren.]] }, s = [[Petrine, an orphan of Baldur's Gate, lost her cat Angel; it is at her uncle Bheren's house, where she will not go. If she gets back the ring Angel uses as a toy, the cat will return to her.
Bheren, in his house, is fed up with a loitering cat and offers you a reward to kill it.
Kind way: search Bheren's house for Angel's ring and bring it to Petrine. Her joy is the only reward.
Cruel way: kill Angel and tell Bheren, who pays you.]] },
[231380] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Baldur's Gate, Elfsong Tavern]], h = { [[A halfling bard named Bellamy has a warning about a paladin.]], [[The paladin Phandalyn waits behind the Elfsong Tavern, and he has heard of you.]], [[With a poor reputation, expect a fight; Bellamy advises going there at night.]] }, s = [[Bellamy, a mysterious halfling bard in Baldur's Gate, warns you about Phandalyn, a paladin lurking behind the Elfsong Tavern by the docks, who knows your reputation.
This is mostly a warning. If your reputation is low, Phandalyn treats you as evil and attacks when you meet him: be ready for a tough fighter with paladin spells. With a good reputation he is no threat.
Bellamy suggests visiting the Elfsong at night to avoid him.]] },
[231381] = { g = [[bg1]], k = [[side]], o = 0, c = [[Prologue]], w = [[Candlekeep]], h = { [[Absent-minded Phlydia has lost yet another book somewhere in Candlekeep.]], [[Her own story about the hay is the best clue to where her books end up.]], [[Find The History of Halruaa on the grounds and hand it back to her.]] }, s = [[In the Candlekeep courtyard, Phlydia asks you to find her book, The History of Halruaa. She once lost a whole set in the hay kept for the cows.
Search the buildings and grounds of Candlekeep, starting with the places her story points to, until you find the book.
Bring it back to Phlydia. She seems to have half forgotten asking you, but rewards you with a gem.]] },
[231383] = { g = [[bg1]], k = [[side]], o = 0, c = [[2]], w = [[Nashkel and surroundings]], h = { [[People in Nashkel talk about Prism, a sculptor who vanished with an investor's emeralds.]], [[Oublek, the bounty officer in Nashkel, pays for the emeralds' return.]], [[Find Prism at work on a huge statue in the wilderness; a bounty hunter will soon join you.]] }, s = [[Rumors in Nashkel tell of Prism, a sculptor who has not been seen for a month. Oublek, the bounty officer, offers a large reward for the emeralds he stole. Refuse any money Oublek tries to give you by mistake (see Oublek the Bounty Officer).
Find Prism in the wilderness, carving a giant statue. The emeralds went into his work and his tale is a sad one.
Greywolf, the bounty hunter Oublek hired, arrives and things turn violent. Greywolf is a strong fighter: prepare before talking to Prism.
Take the emeralds back to Oublek in Nashkel for the bounty.]] },
[231384] = { g = [[bg1]], k = [[side]], o = 0, c = [[2]], w = [[West of Nashkel, Gnoll Stronghold]], h = { [[An outcast gnoll named Ingot knows of a prisoner held by his kin.]], [[The woman is kept in the gnoll fortress to the west.]], [[She is Dynaheir, the witch Minsc is looking for.]] }, s = [[Talk to Ingot, a gnoll banished by his tribe because they feared he would eat their captive. He tells you a woman is held alive in the gnoll fortress to the west.
The captive is Dynaheir. Travel to the Gnoll Stronghold far west of Nashkel, fight your way up through the gnolls and free her (see Rescuing Dynaheir).
Dynaheir can then join you, especially if Minsc is already in the party.]] },
[231385] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Baldur's Gate / north of Tenya's home]], h = { [[A grieving young gnome in the northwest of Baldur's Gate lost his friend to ankhegs.]], [[The ankhegs are upriver from the city, on the east bank, just north of the witch Tenya's home.]], [[Find the dagger Nester stabbed the ankheg with and bring it to Quinn.]] }, s = [[Quinn, a young gnome in the northwest part of Baldur's Gate, tells you his friend Nester was killed by ankhegs and asks for something to bury.
Leave the city and go upriver, along the bank, to the area just north of the witch Tenya's home. Ankhegs burrow out of the ground and spit acid: fight them as a group.
Search the remains for Nester's dagger, then return it to Quinn. He gives you the gem he and Nester meant to sell.]] },
[231386] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Ulgoth's Beard / Durlag's Tower]], h = { [[A dwarf in Ulgoth's Beard wants a family heirloom recovered from Durlag's Tower.]], [[The dagger Soultaker lies deep in the tower, in Durlag's death chamber, and others want it too.]], [[Strangers will take the dagger on your return; Hurgan then sends you against their cult's house in the village.]] }, s = [[In Ulgoth's Beard, Hurgan Stoneblade asks you to recover Soultaker, an enchanted dagger and family heirloom, from Durlag's Tower.
Durlag's Tower is a long, deadly dungeon full of traps and puzzles; go well prepared. The dagger lies in Durlag's death chamber at the bottom.
Back in Ulgoth's Beard, cultists demand the dagger: hand it over, or refuse and they attack and steal it.
Tell Hurgan. He reveals the dagger holds the demon that killed his grandfather, and the cult plans to free it in their house in the village.
Storm the cult's house and defeat the cultists and the demon, a hard fight. Hurgan then leaves, his task done.]] },
[231387] = { g = [[bg1]], k = [[side]], o = 0, c = [[Prologue]], w = [[Candlekeep]], h = { [[Reevor in Candlekeep needs help with his storehouse again.]], [[Rats have overrun the storehouse and the cats are no help.]], [[Clear out every rat inside, then go back to Reevor.]] }, s = [[Talk to Reevor, near his storehouse in Candlekeep. Rats have taken over and he presses you into service once more.
Enter the storehouse and kill all the rats. They are weak, but at level 1 do not let several surround you.
Report back to Reevor. He pays you a measly 5 gold, plus a little experience, a good start before leaving Candlekeep.]] },
[231388] = { g = [[bg1]], k = [[companion]], o = 0, c = [[2-3]], w = [[Nashkel / Gnoll Stronghold]], h = { [[A loud ranger named Minsc in Nashkel has lost the witch he protects.]], [[Dynaheir is held by gnolls in their stronghold far west of Nashkel.]], [[Do not wait too long: Minsc grows impatient and may leave.]] }, s = [[In Nashkel, Minsc asks you to rescue his charge, the witch Dynaheir, captured by gnolls. Accept and he joins the party.
Travel west of Nashkel to the Gnoll Stronghold. Gnolls guard the paths up the cliffs; climb to the top and fight through them. Dynaheir is held in the upper part of the fortress.
Free her and invite her to join, or send her on her way. Minsc complains if you delay, and leaves if you ignore him too long.
If Edwin is in the party, beware: he wants Dynaheir dead, and they do not get along.]] },
[231389] = { g = [[bg1]], k = [[main]], o = 11, c = [[6]], w = [[Candlekeep]], h = { [[Back home in Candlekeep, talk to old friends: several visitors are not what they seem.]], [[Read the prophecies of Alaundo, speak with Koveras, and keep an eye on the Iron Throne leaders upstairs.]], [[You will be framed for murder; escape through the crypts under the keep and listen to Diarmid outside.]] }, s = [[At the gate the Gatewarden lets you in: never take books out of their rooms, and you may stay only ten days.
Talk to Bendalis, Karan, the Chanter and the readers: they mention odd merchants, the Iron Throne leaders meeting Knights of the Shield upstairs, and a sage named Koveras studying Alaundo's prophecies. Expose the doppelganger posing as Shistal.
Read the prophecies, then meet Koveras: he urges you to kill the Iron Throne leaders. Charming Rieltar or Brunos reveals the Iron Throne's plan.
The leaders are murdered and Ulraunt blames you. You end up in the crypts under Candlekeep: fight through doppelgangers and undead to the exit.
Outside, Diarmid mistakes you for Prat's group and reveals Sarevok's scheme. Return to Baldur's Gate.]] },
[231391] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Friendly Arm Inn]], h = { [[A woman named Lena needs someone to take Samuel to a healer.]], [[The healer is Gellana Mirrorshade at the Temple of Wisdom, by the Friendly Arm Inn.]], [[Go straight there with Samuel: if you dawdle, he dies.]] }, s = [[Talk to Lena and promise to take Samuel to the Temple of Wisdom at the Friendly Arm Inn.
Travel there without detours, resting or side trips: time matters.
Inside the temple, speak with Gellana Mirrorshade and hand Samuel over to her care. If you arrive in time he is saved; if you took too long, Gellana cannot save him and he dies.]] },
[231392] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Baldur's Gate, Flaming Fist compound]], h = { [[Scar of the Flaming Fist is your contact in Baldur's Gate.]], [[He waits in the southwest of the city, just outside the Flaming Fist compound.]], [[Go back to him whenever you finish a task he gave you.]] }, s = [[This entry only tells you where to find Scar, the Flaming Fist officer who guides you in Baldur's Gate during Chapter 5.
He stands in the southwest of the city, just outside the Flaming Fist compound. Talk to him there to get his assignments (such as Missing Citizens and the Iron Throne investigation) and to report your results.]] },
[231393] = { g = [[bg1]], k = [[main]], o = 10, c = [[5]], w = [[Baldur's Gate, Flaming Fist compound]], h = { [[Scar wants to talk to you about the Iron Throne.]], [[He is waiting outside the Flaming Fist barracks in the southwest of the city.]], [[Hear him out: his task sends you into the Iron Throne's own headquarters.]] }, s = [[Scar sends word that he wants to discuss the Iron Throne. Go to him outside the Flaming Fist barracks in the southwest of Baldur's Gate.
He asks you to investigate the Iron Throne's headquarters in the city. Enter the building and work your way up the floors, fighting its guards and mercenaries, to learn what its leaders plan.
The findings move the main story forward toward Duke Eltan and Candlekeep.]] },
[231394] = { g = [[bg1]], k = [[side]], o = 0, c = [[7]], w = [[Baldur's Gate, Blushing Mermaid]], h = { [[While you were away, Scar was murdered; a lady of the night named Sugar knows more.]], [[The only witness is Ivanne, in a corner of the Blushing Mermaid Tavern.]], [[Pay Ivanne 10 gold and take the time to hear his whole tale.]] }, s = [[On your return to Baldur's Gate, Sugar, a lady of the night in the streets, tells you Scar is dead and sends you to Ivanne at the Blushing Mermaid.
Go to the tavern and find Ivanne in his corner. Pay him 10 gold to hear the story; if you leave early, come back later.
He tells how a doppelganger lured Scar to a quick death, most likely for the Iron Throne, though Angelo also had much to gain. It is lore only: no fight or reward.]] },
[231395] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Baldur's Gate, Splurging Sturgeon]], h = { [[The owner of the Splurging Sturgeon has a drunken deal for you.]], [[Hand over 100 gold and he promises to double it if you kill the slimes hidden in his tavern.]], [[Hunt down the oozes inside the inn, then claim your money; do not expect the full amount.]] }, s = [[At the Splurging Sturgeon in Baldur's Gate, Lusselyn gets you drunk and talks you into leaving 100 gold with him for safekeeping. He claims slimes and oozes lurk somewhere in his tavern and promises to double your gold if you kill them.
Search the inn's rooms and floors for the slimes and destroy them. They are slow, so ranged attacks and spells keep your fighters safe.
Return to Lusselyn. He pays out only part of what he promised.]] },
[231396] = { g = [[bg1]], k = [[main]], o = 15, c = [[7]], w = [[Baldur's Gate, Undercellar]], h = { [[Two of Sarevok's assassins, Slythe and Krystin, are hiding in the city.]], [[They stay at the Undercellar, an underground brothel; Duke Eltan and Husam both want them dead.]], [[Kill them, search their bodies for Sarevok's plans, then head for the Ducal Palace quickly.]] }, s = [[Duke Eltan, or Husam, tells you that Slythe and Krystin, Sarevok's assassins, may be planning to murder Grand Dukes Belt and Liia. If Eltan is with you, he also wants to be escorted to the Harbor Master's building on the east side of the harbor.
Go to the Undercellar, an underground brothel, and find the pair. They are deadly: Slythe is a stealthy killer and Krystin casts spells. Buff, use detection and focus Krystin.
Search their bodies for papers revealing Sarevok's plans.
Tell Husam what you learned: Sarevok could seize the city at any moment, so get inside the Ducal Palace as soon as possible.]] },
[231397] = { g = [[bg1]], k = [[side]], o = 0, c = [[4]], w = [[Cloakwood]], h = { [[A man named Tiber in the Cloakwood is worried about his brother.]], [[Chelak went into the forest to wipe out a spider infestation and never came back.]], [[His body lies in Centeol's lair, a spider nest deeper in the Cloakwood.]] }, s = [[In the Cloakwood, Tiber asks you to look for his brother Chelak, who went to destroy the spiders infesting the forest.
Go deeper into the Cloakwood to Centeol's lair, crawling with giant spiders and their webs. Bring antidotes or Slow Poison and remedies against webs; Centeol herself is dangerous.
Clear the lair and take Chelak's corpse.
Bring it to Tiber, who rewards you with the sword Spider's Bane.]] },
[231398] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Sword Coast wilderness]], h = { [[A young woman named Tamah stands frozen as a statue after meeting a basilisk.]], [[You need magic that turns stone back to flesh.]], [[Restore Tamah and she offers you her empty lakeside house south of Beregost.]] }, s = [[Tamah fell victim to a basilisk's petrifying gaze and now stands as a stone statue.
Get a Stone to Flesh spell or scroll, then use it on her statue. Watch out for basilisks around: protect your party from their gaze.
Once freed, Tamah thanks you and offers you her lakeside house south of Beregost, empty for some time.]] },
[231399] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Baldur's Gate / Undercity]], h = { [[A mysterious woman named Tamoko warns you about Duke Eltan's healer.]], [[She later meets you near the Flaming Fist headquarters and asks you to spare Sarevok.]], [[In the Undercity she bars your way; refusing to fight her can end it without bloodshed.]] }, s = [[Tamoko approaches you in Baldur's Gate: Duke Eltan's healer is not to be trusted and is likely making him sick. She says she will wait near the Flaming Fist headquarters.
Meet her again later. She asks you to spare Sarevok's life. Promise it and she shares a lot: Slythe and Krystin murdered Duke Entar Silvershield and hide in the Undercellar, Cythandria works with the Iron Throne, and you and Sarevok are both children of Bhaal. Refuse and she tells you little.
In the Undercity, near the end, Tamoko blocks your path to win back Sarevok's favor. Refuse to fight her and she renounces him and leaves. Otherwise you must kill her.]] },
[231402] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Baldur's Gate, Undercellar]], h = { [[The elf Vail knows what became of the Cloak of Balduran.]], [[He gave it to his consort Quenash, who can be found in the Undercellar.]], [[Find Quenash in the Undercellar and ask her for the cloak.]] }, s = [[Talk to Vail the elf in Baldur's Gate. He tells you he gave the Cloak of Balduran to his consort, Quenash, and that she is in the Undercellar.
Reach the Undercellar, the underground brothel reached through the city sewers, and find Quenash.
Talk to her: she hands over the Cloak of Balduran without trouble. She also drops a hint about the Helm of Balduran (see The Helm of Balduran).]] },
[231403] = { g = [[bg1]], k = [[side]], o = 0, c = [[2-5]], w = [[Firewine Bridge / Gullykin]], h = { [[A hunter on the road recommends the Firewine Bridge ruins to adventurers.]], [[Kobolds there are unusually organized; the halflings of Gullykin suffer their raids.]], [[An ogre mage in the ruins below the bridge commands them: kill it and tell Gandolar in Gullykin.]] }, s = [[A hunter suggests you explore the Firewine Bridge, last remnant of an elven trading town destroyed two centuries ago. The halflings of Gullykin, nearby, are harassed by kobolds from the ruins.
Enter the ruins under the Firewine Bridge. Kobolds there fight in organized groups, some with fire arrows: keep the party tight and kill archers first.
Deep inside, defeat the ogre mage who sends the kobolds out. It uses spells and invisibility.
Return to Gandolar in Gullykin, who thanks you for freeing his village.]] },
[231404] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-6]], w = [[Candlekeep]], h = { [[Shaella, a priestess of Leira, sends you on a pilgrimage to your old home.]], [[The Great Book of the Unknowing is said to lie in Candlekeep.]], [[Once you have been back to Candlekeep, talk to Shaella again; do not expect to remember the book.]] }, s = [[Talk to Shaella, a priestess of Leira, the goddess of deception. She tells you about the Great Book of the Unknowing in Candlekeep, which robs anyone who touches it of knowledge, and asks you to seek it.
You cannot return to Candlekeep until the main story takes you there. After that visit, speak with Shaella again.
She assures you that you did find the book, but of course you remember nothing. It is a joke in Leira's style: there is nothing to find and no real reward.]] },
[231405] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Baldur's Gate]], h = { [[The wizard Degrodel, in the northwest of the city, wants the Helm of Balduran.]], [[His lead: petrified adventurers kept by an art dealer on an estate just west of the fairgrounds.]], [[Vail's scroll and Quenash's riddle point to a building whose name fits a helm and a cloak.]] }, s = [[Degrodel, a wizard with an estate in the northwest of Baldur's Gate, asks you for the Helm of Balduran. He says it is on the petrified bodies of adventurers held by an art dealer on an estate just west of the fairgrounds.
Vail the elf gives you a scroll meant to reveal the helm's location, and Quenash in the Undercellar adds that Vail's hiding place is practically named for the purpose.
Follow either lead, recover the helm and be ready for a fight if you restore the petrified adventurers.
Bring the helm to Degrodel's estate. He pays a nice reward, then asks you to leave.]] },
[231406] = { g = [[bg1]], k = [[main]], o = 4, c = [[2]], w = [[Nashkel Mines]], h = { [[A prisoner in the depths of the Nashkel mines has useful knowledge.]], [[Free the elf Xan from his captors.]], [[Charm Xan to learn about the Iron Throne.]] }, s = [[In the lowest level of the Nashkel mines, near Mulahey's lair, you find the elf Xan held prisoner. Defeat his captors and free him; he can join the party.
If you charm Xan with a spell, he reveals that a merchant group called the Iron Throne is stirring up trouble along the Sword Coast, though he does not know why.
This is the first mention of the Iron Throne, the thread the main story will follow.]] },
[231407] = { g = [[bg1]], k = [[side]], o = 0, c = [[2-4]], w = [[Ulcaster ruins]], h = { [[Townsfolk in Beregost tell of an ancient wizard school full of treasure.]], [[The ruined school of Ulcaster lies in the wilderness not far from Beregost.]], [[Explore the ruins and the dungeon beneath, and be ready for undead and magical guardians.]] }, s = [[A townsman of Beregost mentions rumors of an ancient wizard school full of treasures.
The rumor points to the ruins of Ulcaster's school, in the wilderness not far from Beregost.
The rumor itself is only a pointer: go there to explore the ruins and the dungeon below. Expect undead and magical foes; bring a priest to turn undead and some magic weapons.]] },
[231408] = { g = [[bg1]], k = [[side]], o = 0, c = [[5]], w = [[Baldur's Gate, Seven Suns building]], h = { [[Scar, second-in-command of the Flaming Fist, wants someone to look into the Seven Suns trading coster.]], [[The staff inside the Seven Suns building are not what they seem, and the real leader is missing.]], [[Find Jhasso held inside the building, kill every doppelganger, then report to Scar for a double reward.]] }, s = [[In chapter 5, Scar of the Flaming Fist hires you to investigate the Seven Suns compound, in the southwest part of the city. The ex-merchant Dun, met in the streets, also finds their behaviour odd.
Enter the Seven Suns building: a frightened merchant warns you about shapeshifters, and the staff turn into doppelgangers. Expect several fights.
Find Jhasso, the real head of the coster, who confirms the takeover.
Report to Scar at the Flaming Fist barracks just west of the building. He offers to double the reward if you go back and kill every doppelganger. Clear them all and return for the bonus, or decline and keep the basic payment.]] },
[231409] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Beregost / Ulcaster School]], h = { [[Some Beregost townsfolk know a secret, but only tell it to someone they trust completely.]], [[A charm spell makes certain commoners talk about a ruined wizard school.]], [[The abandoned school is Ulcaster's, to the east on the world map; explore its ruins and dungeon for treasure.]] }, s = [[This is only a rumour. In Beregost, charm commoners such as Galteran or Berden (Charm Person, or a charm item) and they tell you about an abandoned wizard school to the east, full of treasure.
That is Ulcaster School, an area of the world map you can reach without the rumour. Travel there and explore the ruins and the dungeon below them. Expect undead and other monsters.
The ghost of Ulcaster himself lingers there, which starts the related quests about his lost tomes.]] },
[231410] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Baldur's Gate, north]], h = { [[Two mages of Baldur's Gate disagree about who should keep a nymph named Abela.]], [[Ramazith pays you to bring her from Ragefast's house, but Ragefast tells a different story.]], [[Free Abela for a good outcome, or hand her to Ramazith for his reward at the cost of your conscience.]] }, s = [[The quest starts either from the mage Ramazith, in his tower in the north of the city, who asks you to fetch a captive nymph, or from Lady Hannah, who accuses Ragefast of enslaving one.
Go to Ragefast's house in the northwest district, northeast of the Hall of Wonders. Listen to him: he believes Ramazith wants Abela for evil purposes, and you learn Ramazith means to use her as a source of spell components.
Good path: set Abela free; she leaves, released at last.
Evil path: take her to Ramazith and collect his reward.]] },
[231411] = { g = [[bg1]], k = [[side]], o = 0, c = [[2-5]], w = [[Lower Chionthar / Wyrm's Crossing]], h = { [[Fishermen along the Chionthar, north of the Friendly Arm Inn, want a priestess of Umberlee gone.]], [[The priestess, living near the bridge to Baldur's Gate, is only a child with her own story.]], [[Siding with Tenya means facing the fishermen of Talos and taking back a bowl; refusing both is also possible.]] }, s = [[Fishermen on the river north of the Friendly Arm Inn ask you to kill a priestess of Umberlee who lives just east of the bridge to Baldur's Gate. They raise their offer suspiciously fast.
Find the priestess Tenya: she is a girl of about twelve who says the fishermen killed her mother. You learn the fishermen serve Talos.
Tenya's path: confront the fishermen, defeat them and bring Tenya the bowl she seeks. She promises a future reward; she reappears later at the Temple of Umberlee in Baldur's Gate (see Tremain's Son).
Fishermen's path: kill Tenya and collect their pay.
You can also refuse both sides.]] },
[231412] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Durlag's Tower, dungeon]], h = { [[Four spirits named after a warrior's flaws guard the lift down in Durlag's Tower; each recites a riddle.]], [[Read each riddle literally: something that glitters, a loud noise, a red drink, and written chronicles.]], [[Search the rooms of that level for the matching objects; the warder Love holds the wardstone for the lift.]] }, s = [[In the dungeon below Durlag's Tower, four warders (Avarice, Fear, Love and Pride) block the lift to the lower levels. Each appears as an apparition and speaks a riddle that the journal records.
Avarice hungers for what glitters most: offer it something precious.
Fear sleeps: wake it with a loud noise, such as a gong or something similar found nearby.
Love thirsts for a sweet crimson drink: find or make wine on this level.
Pride wants its deeds honoured: find and read the chronicles of its deeds hidden on the level.
Once all four are satisfied, Love gives up the wardstone, and the lift takes you down.]] },
[231413] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Bear River]], h = { [[A paladin named Laurel fights an endless war against gibberlings in the wild lands.]], [[She advises preparing as much fire magic as possible before joining her.]], [[Help her hold off the waves of gibberlings, then rest and come back for another hunt.]] }, s = [[Meet the paladin Laurel in the Bear River area. She invites you to help in the region's ongoing battle against the gibberling hordes.
Accept, and follow her advice: memorise fire spells and bring fire arrows or other fire damage, since the beasts fear flame. Gibberlings are weak alone but arrive in large numbers, so keep your casters protected.
Fight off the hordes with her. Afterwards Laurel treats it as a sport and suggests you rest, rearm and visit her again for more.]] },
[231414] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Isle of Balduran (Werewolf Island)]], h = { [[On the island, everyone tells you to speak with the village headwoman, Kaishas Gan, first.]], [[Kaishas wants the beasts led by Karoug, who live in the wreck of Balduran's ship, destroyed.]], [[The villagers are werewolves themselves; after Karoug dies, escape through a secret door in the chieftain's hut.]] }, s = [[After Mendas's boat leaves you on Balduran's Isle, walk to the village. Talk to the villagers (Lahl, Jorin, Evalt, Farthing, Taloun, the Amnian sailor) for background, then to the headwoman Kaishas Gan.
Accept her task: kill Karoug and the wolfweres living in the wreck of Balduran's ship. Expect tough fights; silver or magical weapons help. Balduran's ship holds good loot.
Return to the village. The villagers reveal they are werewolves, give you lycanthropy and attack. Kill Kaishas, who warns you about Selaad, and take the sea charts.
Escape: a secret door in the north of the chieftain's hut leads below ground to the werewolves' ship. Maralee, or Delainy / Durlyle if you won their favour, can show it.
Sail home and finish with Mendas.]] },
[231415] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Ulgoth's Beard / Baldur's Gate]], h = { [[A standoffish scholar named Mendas has just settled in Ulgoth's Beard, and he has an errand.]], [[He wants the Merchants' League sea charts from Baldur's Gate, then the logbook of Balduran's last voyage.]], [[Mendas is not what he claims; be ready to fight him when you come back from the island.]] }, s = [[In Ulgoth's Beard, the townsfolk mention Mendas, a newcomer said to come from Waterdeep. Calahan notes he has no Waterdhavian accent and often leaves town.
Talk to Mendas in his house. He asks you to obtain the sea charts from the Merchants' League Counting House in the northeast of Baldur's Gate (see The Sea Charts).
Bring him the charts. He copies them, hires a boat and asks you to fetch Balduran's logbook. Meet him at the Ulgoth's Beard docks to sail.
Survive the Mysterious Island and sail back. Mendas is revealed as Selaad, the werewolf chieftain who wanted the charts for his pack. Expect a fight against him on your return.]] },
[231416] = { g = [[bg1]], k = [[main]], o = 16, c = [[7]], w = [[Baldur's Gate]], h = { [[Sarevok is campaigning to become Grand Duke, and you need hard proof before you can accuse him.]], [[Look for evidence in the Iron Throne building and in the Flaming Fist headquarters, where Angelo commands.]], [[Bring the proof to the remaining Dukes at the ducal palace before Sarevok is crowned.]] }, s = [[In chapter 7 you return to Baldur's Gate still wanted for the Iron Throne murders. Entar Silvershield and Scar are dead, Duke Eltan is dying and Angelo Dosan runs the Flaming Fist for Sarevok, who is the favourite in the ducal election.
Listen to the rumours and allies (Gregor, the Harper Delthyr, the emissary Kalessia) for the background.
Search the Iron Throne building, as Delthyr suggests, for Sarevok's own records, and the Flaming Fist barracks for proof of his deals with Angelo.
Take the evidence to the ducal palace during the coronation celebration and present it to Dukes Belt and Liia. Expect assassins. Sarevok flees below the city, where the final confrontation takes place in the temple of Bhaal.]] },
[231417] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Baldur's Gate, Merchants' League / Blushing Mermaid]], h = { [[The sea charts Mendas wants are in the Merchants' League Counting House, watched by Captain Tollar Kieres.]], [[Kieres is a drunk who wants a special ale held for him by De'Tranion at the Blushing Mermaid.]], [[Pay his 900 gold tab for the Baalor Ale, talk your way past him, or sneak or fight your way to the charts.]] }, s = [[Go to the Merchants' League Counting House in the northeast of Baldur's Gate. Captain Tollar Kieres blocks your search for the sea charts.
Peaceful way: he wants Baalor Ale. Find De'Tranion at the Blushing Mermaid tavern; he hands it over only if you pay Kieres's 900 gold tab. Bring the ale to Kieres and he lets you look around.
You may also persuade him in dialogue, as he is rarely sober.
Other ways: sneak past or kill him, but fighting inside the city can bring trouble.
Take the sea charts and bring them to Mendas in Ulgoth's Beard.]] },
[231418] = { g = [[bg1]], k = [[side]], o = 0, c = [[2]], w = [[Nashkel / Ancient Ruins]], h = { [[Nashkel's captain of the guard, Brage, went on a murderous rampage and vanished.]], [[Volo and the townsfolk note that Brage changed right after acquiring a new sword.]], [[Deal with Brage in the wilds, then choose between the garrison and the Temple of Helm in Nashkel.]] }, s = [[In Nashkel, the garrison posts a large reward for Brage, the captain of the guard who killed several people. Rumours (Volo, the townsfolk) blame a cursed new sword. Nalin at the Temple of Helm thinks an evil force is at work.
Find Brage in the wilderness outside Nashkel, in the Ancient Ruins area. He is a dangerous fighter. Depending on how the encounter goes, you either kill him or take him alive.
Return to Nashkel. At the garrison you get the bounty, but a living Brage will be executed. At the Temple of Helm, Nalin takes him in so he may atone, the kinder outcome.
Beware of his sword: it is cursed.]] },
[231419] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Ulgoth's Beard / Durlag's Tower]], h = { [[A worried mother in Ulgoth's Beard wants news of her son, who went off adventuring.]], [[Dalton joined Bayard's party and entered Durlag's Tower.]], [[Find Dalton alive inside the tower and bring him back to Therella for a reward.]] }, s = [[In Ulgoth's Beard, Therella asks you to look for her son Dalton, who went to Durlag's Tower.
Travel to Durlag's Tower and explore inside. You meet the adventurer Bayard, whose companions included Dalton. Bayard's group has not fared well.
Find Dalton deeper in the tower and rescue him; he survives his companions.
Return to Therella in Ulgoth's Beard. If Dalton lives, she is overjoyed and rewards you. If he died, she is heartbroken and there is no reward.]] },
[231420] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Ulcaster School]], h = { [[The ghost of the wizard Ulcaster haunts the ruins of his old school.]], [[His precious tomes lie buried under the rubble of the school and its dungeon.]], [[Search the ruins carefully for his books and show them to the ghost.]] }, s = [[Travel to the Ulcaster School area and find the ghost of Ulcaster near the ruins. He hopes someone will dig up the tomes buried beneath the rubble.
Explore the ruins and the dungeon below. Use the Hint button or search containers and piles of rubble; expect undead and other monsters.
When you find one of his lost books, bring it to the ghost. It helps him regain some of his sanity (see Ulcaster's Ghost).]] },
[231421] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Baldur's Gate, Temple of Umberlee]], h = { [[Tremain Belde'ar, who lives north of the Hall of Wonders, has lost his son to the sea.]], [[The boy's body was taken to the Temple of Umberlee near the docks, and time is short.]], [[Get the body from the temple quickly; the child priestess Tenya rules there, so your past with her matters.]] }, s = [[Tremain Belde'ar, in a house just north of the Hall of Wonders, begs you to recover the body of his son Casson from the Temple of Umberlee near the docks.
Go there without delay: if you take too long, the boy cannot be saved.
Inside, the child priestess Tenya rules the temple. If you helped her against the fishermen, she hands over the body and may offer you sanctuary. If you crossed her, she may turn on you and you must fight.
Bring Casson back to Tremain in time: the boy is revived and gets a scolding, and Tremain thanks you.]] },
[231423] = { g = [[bg1]], k = [[side]], o = 0, c = [[Tutorial]], w = [[Tutorial area]], h = { [[Belt wants you to fetch a star sapphire from the basement.]], [[The search uses many abilities: look for chests and objects with the Hint button.]], [[Grab the star sapphire, go back upstairs and speak to Belt to end the tutorial.]] }, s = [[This is the game's tutorial, started from the main menu.
Talk to Belt, then go down to the basement. Work through it using the skills the tutorial introduces: moving, fighting, opening containers, dealing with locks and traps. Press the Hint button to highlight chests and other usable objects.
Find the star sapphire, return upstairs and speak with Belt to finish.
If you get stuck after entering the basement, load the Auto Save to start over.]] },
[231424] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Ulcaster School]], h = { [[The ghost of Ulcaster rambles near the ruins of his school.]], [[He calms down when shown something he owned in life.]], [[Give him one of his lost books found in the ruins.]] }, s = [[At the Ulcaster School area, speak to the ghost of Ulcaster; at first his mind is badly frayed.
Explore the ruins and the dungeon beneath to find one of his lost books (see Tomes of Magic).
Present the book to the ghost. He regains some of his sanity and can speak more clearly about his school and its fate.]] },
[231425] = { g = [[bg1]], k = [[side]], o = 0, c = [[3-4]], w = [[Beregost, Jovial Juggler]], h = { [[A Flaming Fist officer stuck in Beregost is paying for proof of dead bandits.]], [[Bandits you kill on the roads and in their camps often carry scalps.]], [[Bring Officer Jessa Vai the bandit scalps at the Jovial Juggler for gold each.]] }, s = [[In the Jovial Juggler inn in Beregost, Officer Jessa Vai of the Flaming Fist is stranded with her men. She offers 50 gold for every bandit scalp you bring.
Kill bandits wherever you meet them (roadside ambushes, the bandit camp, the woods) and loot their scalps.
Return to Vai at the Jovial Juggler and hand them over for 50 gold each. Once the bandits are dealt with, she promises to put in a good word for you with her superiors in the Flaming Fist.]] },
[231426] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Nashkel]], h = { [[A Nashkel merchant is eager to buy a particular kind of fur.]], [[Winter wolves are rare on the Sword Coast; keep their pelts when you kill one.]], [[Sell winter wolf pelts to that merchant in Nashkel for a good price.]] }, s = [[A merchant in Nashkel tells you he wants winter wolf pelts.
There is no fixed target: whenever you kill a winter wolf, loot its pelt. They are tougher than ordinary wolves and use a frost breath, so cold resistance helps.
Bring the pelts back to the Nashkel merchant and sell them; he pays well for them.]] },
[231427] = { g = [[bg1]], k = [[companion]], o = 0, c = [[2]], w = [[Nashkel Mines]], h = { [[Someone is held prisoner deep in the Nashkel mines.]], [[The elf Xan was investigating the region's troubles, like you, and got captured.]], [[Free Xan on the lowest level of the mines, then accept or refuse his offer to join.]] }, s = [[Go down through the Nashkel mines to the lowest level, where the kobolds' leader holds his prisoners.
Find and free the elf Xan, a gloomy enchanter who was also investigating the iron crisis.
When freed, he offers to join you. Accept to recruit him, or refuse and he leaves. The journal records either choice.]] },
[231429] = { g = [[bg1]], k = [[companion]], o = 0, c = [[1-2]], w = [[Road south of the Friendly Arm Inn / Nashkel]], h = { [[An odd pair, a mage and a halfling, approach you on the road early in your journey.]], [[Xzar and Montaron want to investigate the troubles in Nashkel.]], [[Take them with you to Nashkel and its mines.]] }, s = [[Early in chapter 1, the necromancer Xzar and the halfling Montaron meet you on the road south of the Friendly Arm Inn. They offer to join you.
If they join, they ask you to travel to Nashkel, where the mines are causing trouble. This matches the main quest, so simply head south to Nashkel and the mines.
Keep them reasonably busy: they dislike long detours, and they get along badly with good-aligned companions. Both are evil, which matters if your party is good.]] },
[231430] = { g = [[bg1]], k = [[side]], o = 0, c = [[2-3]], w = [[Beregost, Burning Wizard]], h = { [[A thief at the Burning Wizard in Beregost keeps picking your pocket whenever you talk.]], [[Zhurlong lost some boots to hobgoblins in the rocky lands south of Beregost.]], [[Kill those hobgoblins, take the boots and return them to Zhurlong to get your gold back.]] }, s = [[At the Burning Wizard tavern in Beregost, Zhurlong picks your pocket each time you speak with him. He mentions boots stolen by hobgoblins in the rocky badlands south of town.
Travel south of Beregost, find the hobgoblins, kill them and loot the boots.
Bring the boots to Zhurlong. He returns all the gold he stole from you and adds 100 gold, which he jokingly calls an advance on your pocket.]] },
[231431] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Upper Chionthar]], h = { [[Settlers by the river are terrorised by the walking dead.]], [[The old farmer Wenric has counted twenty zombies roaming the riverbank.]], [[Destroy every last one of the twenty zombies, then return to Wenric for 150 gold.]] }, s = [[In the Upper Chionthar area, along the river, the old farmer Wenric asks you to destroy a zombie infestation: he counted twenty of them. He offers 150 gold.
Sweep the area and kill all the zombies. They are slow but can wear down a weak party; clerics who can turn undead and blunt weapons help.
Return to Wenric once all twenty are gone to collect the 150 gold.]] },
[231604] = { g = [[bg1]], k = [[side]], o = 0, c = [[Prologue]], w = [[Candlekeep, barracks]], h = { [[Hull, one of the Watchers of Candlekeep, forgot something this morning.]], [[His sword is still in the barracks.]], [[Take it from the chest against the right wall of the barracks and bring it to Hull.]] }, s = [[In Candlekeep, talk to Hull, a Watcher on guard duty. He forgot his sword in the barracks.
Go to the barracks and open the chest against the right wall to take the sword.
Bring it back to Hull. He pays you 10 or 20 gold depending on his mood, along with a few grumbles.]] },
[231605] = { g = [[bg1]], k = [[side]], o = 0, c = [[Prologue]], w = [[Candlekeep, barracks and inn]], h = { [[Fuller, nursing a hangover in the Candlekeep barracks, needs an errand run.]], [[He wants crossbow bolts from Winthrop, the innkeeper.]], [[Get the bolts from Winthrop at the inn and bring them back to Fuller.]] }, s = [[In the Candlekeep barracks, talk to Fuller, who is recovering from a night of mead. After some insisting, he asks you to fetch crossbow bolts from Winthrop.
Go to the inn, talk to Winthrop and get the bolts.
Return to Fuller. Depending on his mood, he gives you his father's old dagger or 10 gold.]] },
[231606] = { g = [[bg1]], k = [[side]], o = 0, c = [[Prologue]], w = [[Candlekeep, inn and inner grounds]], h = { [[Old Firebead Elvenhair, visiting from Beregost, waits at the Candlekeep inn for an item.]], [[He left an identify scroll with Tethtoril in the inner grounds.]], [[Get the scroll from Tethtoril and bring it back to Firebead at the inn.]] }, s = [[At the Candlekeep inn, talk to Firebead Elvenhair. He needs the identify scroll he left with Tethtoril.
Walk to the inner grounds near the library and talk to Tethtoril to get the scroll.
Return to the inn and give it to Firebead. In thanks he casts a protective spell on you that lasts for the night.]] },
[231607] = { g = [[bg1]], k = [[side]], o = 0, c = [[any]], w = [[Gibberling Mountains]], h = { [[The Flaming Fist has posted a 50 gold bounty on a deserter named Samuel.]], [[Samuel is hiding out in the wilds of the Gibberling Mountains.]], [[Find Samuel and hand him over to the Flaming Fist soldier for the bounty.]] }, s = [[A Flaming Fist soldier tells you that a man named Samuel deserted his post, and offers 50 gold for his capture.
Look for Samuel in the Gibberling Mountains area and confront him.
Deliver him to the Flaming Fist soldier to collect the 50 gold reward.]] },
[231988] = { g = [[bg1]], k = [[companion]], o = 0, c = [[3-4]], w = [[Cloakwood / Temple of Lathander]], h = { [[An elf named Coran in the Cloakwood is after a wyvern with a price on its head.]], [[The wyverns nest deeper in the Cloakwood; bring their head as proof.]], [[Take the wyvern's head to Kelddath at the Temple of Lathander east of Beregost for the reward.]] }, s = [[In the first Cloakwood area, meet Coran, an elven archer. He proposes to hunt down a wyvern together; agreeing makes him join.
Go deeper into the Cloakwood and find the wyvern lair. Wyverns are poisonous: bring antidotes or protection from poison.
Loot a wyvern head after the fight.
Travel to the Temple of Lathander just east of Beregost and give the head to Kelddath, Beregost's mayor and head of the temple. He pays 2,000 gold.]] },
[232148] = { g = [[bg1]], k = [[companion]], o = 0, c = [[3]], w = [[Bandit Camp]], h = { [[Kivan the ranger seeks revenge on an ogre named Tazok who killed someone dear to him.]], [[Tazok is a leader among the bandits; he can be found at their camp.]], [[Bring Kivan to the bandit camp; what happens there depends on how you enter and whether Tazok is present.]] }, s = [[With Kivan in the party, he tells you he hunts the half-ogre Tazok, who killed his wife.
In chapter 3, find the bandit camp and enter it with Kivan.
Outcomes: if Tazok is there, Kivan attacks him. Tazok may brush off the attempt and even let you stay in the camp, or flee and turn the whole camp on you. If Tazok is absent, you find only his lackeys.
In every case Kivan cannot finish his revenge here; Tazok shows up again later in the main story.]] },
[232202] = { g = [[bg1]], k = [[side]], o = 0, c = [[2-5]], w = [[Adoy's Enclave, goblin caves]], h = { [[The ranger Magreb mourns his friend Rilsa, killed by rebellious goblins.]], [[The goblins hold a series of caves to the northeast of where you meet him.]], [[Find Rilsa's body in the caves, bury her, and bring her ring back to Magreb.]] }, s = [[In the Adoy's Enclave area, the ranger Magreb tells you about a goblin uprising. His friend Rilsa was killed trying to make contact with them.
Enter the caves to the northeast and fight through the goblins.
Find Rilsa's body. Take the ring she carries and choose to give her a proper burial.
Return the ring to Magreb. If you buried her, he is comforted. If not, he thanks you but goes off to bury her himself, displeased.]] },
[232218] = { g = [[bg1]], k = [[side]], o = 0, c = [[5-7]], w = [[Baldur's Gate / Wood of Sharp Teeth]], h = { [[A ranger named Shilo Chen is looking for help in Baldur's Gate.]], [[Ogre magi are slaughtering the wildlife in the Wood of Sharp Teeth.]], [[Go to the southwest corner of the Wood of Sharp Teeth and destroy the ogre magi.]] }, s = [[In Baldur's Gate, the ranger Shilo Chen asks for help: a band of ogre magi is killing the wildlife in the Wood of Sharp Teeth.
Travel to the Wood of Sharp Teeth and head for its southwest corner.
Fight the ogre magi. They cast spells and can turn invisible, so bring ways to see or dispel invisibility. Shilo may send other adventurers as reinforcements.]] },
[232759] = { g = [[bg1]], k = [[companion]], o = 0, c = [[3]], w = [[Bandit Camp]], h = { [[Kivan is very eager to hunt bandits with you.]], [[His real target is Tazok, a bandit leader who tortured and killed his wife.]], [[Take Kivan to the bandit camp in chapter 3 to see how his revenge plays out.]] }, s = [[Kivan asks you to hunt bandits together. This entry mirrors Kivan and Tazok.
Find the bandit camp (chapter 3) and enter it with Kivan in the party. He reveals that Tazok tortured and killed his wife.
Outcomes: Tazok shrugs off the attack and lets you stay, or he flees and turns the camp against you, or he is absent and only his lackeys remain. Kivan does not get his revenge at the camp.]] },
[232802] = { g = [[bg1]], k = [[side]], o = 0, c = [[2-3]], w = [[Nashkel / Beregost, Thunderhammer Smithy]], h = { [[A vial of strange liquid from the mines may explain why iron has become brittle.]], [[Mayor Berrun Ghastkill of Nashkel suggests a smith in Beregost could study it.]], [[Give the vial to Taerom at the Thunderhammer Smithy, then come back a couple of days later.]] }, s = [[After finding a vial of mysterious liquid linked to the kobolds of the Nashkel mines, show it to Berrun Ghastkill in Nashkel. He advises taking it to Taerom Fuiruim in Beregost.
Go to the Thunderhammer Smithy in Beregost and give the vial to Taerom.
Wait a couple of days, then return. Taerom has found how to reverse the kobolds' poison and now sells weapons that will not break.]] },
[232866] = { g = [[bg1]], k = [[companion]], o = 0, c = [[1-3]], w = [[Coast south of Candlekeep]], h = { [[Safana, met by the sea, wants help with a treasure.]], [[The treasure lies in a cove on the coast just south of Candlekeep, guarded by a monster.]], [[Go to the cove with Safana, defeat its guardian and claim the treasure.]] }, s = [[Meet Safana, a charming thief, and agree to help her recover a treasure held by a monster.
Travel to the coast just south of Candlekeep and find the treasure cove.
Go inside with Safana and defeat the creature guarding it; prepare your party before you enter.
Loot the treasure. Safana stays in the party afterwards if you wish.]] },
[249477] = { g = [[sod]], k = [[side]], o = 0, c = [[any]], w = [[Underground caverns]], h = { [[Murs has heard screams coming from inside the cavern walls.]], [[Search west and south of the old ogre settlement, where the noise seems trapped in the rock.]], [[Behind the rock lies a sealed cavern; what lives inside is beyond saving.]] }, s = [[Talk to Murs: he mentions screams heard from the cavern walls west and south of the old ogre settlement.
Go there and search the walls for a way into a sealed cavern.
Inside is a hatch of blind albino wyrmlings, twisted by foul magic and driven mad by years of eating each other. They cannot be reasoned with and attack.
Kill them all to end their suffering and close the quest.]] },
[249478] = { g = [[sod]], k = [[side]], o = 0, c = [[any]], w = [[Unknown]], h = { [[This quest has no journal entries in the game's tables.]], [[Its title suggests someone or something has gone astray; listen to the people you meet in the wilds.]], [[If you never get an entry for it, you are not missing anything.]] }, s = [[The game's quest table lists this title but no journal entry is attached to it, so there is nothing that can be tracked or completed here.
It is most likely an unused or cut quest from Siege of Dragonspear. You can safely ignore it.]] },
[251953] = { g = [[sod]], k = [[side]], o = 0, c = [[any]], w = [[Underground caverns]], h = { [[Drow and crusaders are fighting over two missing drow youths; Shapur leads the drow.]], [[Search the caves nearby for the two runaways before more blood is spilled.]], [[Their fate is up to you: bring them home, fake their deaths with their house insignias, or arrive too late.]] }, s = [[At the site where drow face off against crusaders, talk to Shapur: two adolescent drow have run away and the drow blame the crusaders.
Search the surrounding caves for the runaways. Outcomes:
- Convince them to go home: they meet you back at the battle site and Shapur, grudgingly, thanks you before the drow withdraw.
- Agree to fake their deaths: they give you their house insignias to show Shapur.
- If an ankheg kills them, report their deaths.
When you tell Shapur they died, she may take it calmly and leave, or attack you: be ready for a fight.]] },
[257689] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear Castle]], w = [[Below Dragonspear Castle, near Kanaglym]], h = { [[The ghost dragon guarding the doors to Kanaglym makes threats, but something else is pulling its strings.]], [[Walk past the dragon into the room beyond, where a cabal of wizards works dark magic.]], [[Kill the wizard Kherriun, who holds the dragon's essence, then speak to Halatathlaer again.]] }, s = [[A huge ghost dragon, Halatathlaer, guards a pair of doors at the entrance to Kanaglym. She threatens you but does not attack: she is bound by an outside power. If you found the journal about her eggs earlier, you can tell her their fate.
Pass her and enter the room beyond, where a cabal of wizards performs a ritual. Kill their leader Kherriun to free the dragon's essence; once freed, Halatathlaer helps you finish the cabal.
Talk to her afterwards: she reveals what she knows about Hephernaan and Caelar, then departs for the Fugue Plane through the Fountain of Nepenthe.
If you tell her you killed her mutant hatchlings, she leaves in a rage. You can also simply fight and destroy the ghost dragon.]] },
[258034] = { g = [[sod]], k = [[side]], o = 0, c = [[Boareskyr Bridge]], w = [[Bridgefort]], h = { [[The crusaders besieging Bridgefort would welcome a traitor inside the walls.]], [[Persuade the dwarf lieutenant Kharm that you serve the crusade, then get into the fort.]], [[Only the guard Mari holds the drawbridge key: talk her into lowering it or take the key.]] }, s = [[This is an evil option that hands Bridgefort to the crusade at the cost of many lives.
At the crusader lines outside Bridgefort, talk to the dwarf Lieutenant Kharm and convince him you belong to the crusade. He asks you to slip into the fort and lower the drawbridge.
Inside, the only key to the drawbridge mechanism is held by the guard Mari. Convince her to lower the bridge, or get the key from her by other means, then work the mechanism.
The crusaders take the fort. You are thrown in with the prisoners and must fight your way out, unless you identify yourself, in which case you leave unharmed while everyone else in Bridgefort is captured.]] },
[258475] = { g = [[sod]], k = [[side]], o = 0, c = [[any]], w = [[Spider cave]], h = { [[Spider eggs lie scattered around a cave full of spiders; pick some up.]], [[Only certain giant insects like to eat spider eggs.]], [[Once you hold the eggs, something big stirs in the caverns: go find the noise.]] }, s = [[In the spider-infested cave, collect the eggs scattered around the cavern (expect spiders to defend their nest).
After that, the journal warns that something large has entered the cave. Follow the noise.
Its source is a giant rhino beetle. Spider eggs are the kind of food such insects crave, so keep them with you when you meet it and see how it reacts.
Finding the beetle closes the quest.]] },
[258697] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear Castle]], w = [[Crusader camp near Dragonspear Castle]], h = { [[While disguised among the crusaders, look for a cleric who handles the camp's trolls.]], [[Sindret wants special troll shackles fetched from a chest somewhere in the camp.]], [[With the shackles, talk to the troll Ulori, or trick Sindret into doing the job herself.]] }, s = [[In the crusader camp, Sindret, a cleric of Shevarash and assistant troll-wrangler, asks you to find troll shackles kept in a chest somewhere in the camp.
Bring the shackles back and agree to put them on the troll Ulori. Talk to the troll and convince it to let you shackle it, then report to Sindret.
Other outcomes: bluff Sindret into shackling it herself (it goes badly for the crusaders), refuse and end up fighting her, or kill the troll, accidentally or on purpose. Killing it angers Sindret but leaves one less troll for the crusade to throw at the coalition.]] },
[258713] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear Castle]], w = [[Crusader camp near Dragonspear Castle]], h = { [[Two crusader rangers are at odds, and their commander Leopas wants an outsider to judge.]], [[Hear Valis and Corinth, then the crusaders Ravoc, Damarr and the gnome Delton.]], [[Corinth did warn the hamlet of Innisfall; give Leopas a verdict or suggest a trial by combat.]] }, s = [[In the crusader camp, the ranger Valis accuses her fellow ranger Corinth of betrayal, and their commander Leopas asks you to find the truth.
Talk to Valis, Corinth, the orc Ravoc, Damarr and the gnome wizard Delton. Ravoc and Delton defend Corinth, Damarr fears the punishment is too harsh, and Corinth himself is evasive.
The truth: Corinth warned the hamlet of Innisfall, costing the crusade recruits and supplies.
Return to Leopas and declare Corinth innocent or guilty, or convince him to settle it by trial by combat, which leaves one fewer crusader in Caelar's ranks. Your companions may react to your choice.]] },
[258806] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear Castle]], w = [[Crusader camp near Dragonspear Castle]], h = { [[The crusade's morale officer wants new recruits to understand why they fight.]], [[Deneld sends you to chat with Ravoc, Sindret, Zare and Tristian around the camp.]], [[Listen to each one's reasons for following Caelar, then answer Deneld's questions accordingly.]] }, s = [[In the crusader camp, Morale Officer Deneld asks you to talk with some crusaders and then prove what you learned.
Speak to the orc Ravoc (his tribe's souls are trapped in the Nine Hells), Sindret (a drow-hunting cleric of Shevarash won over by Caelar's faith), the new recruit Zare (blindly devoted to Caelar) and Tristian (a cleric of the Red Knight conscripted by force, now content to plan for the crusade).
Return to Deneld and answer his questions using what they told you. If he is satisfied, the quest closes and you understand your enemies better.]] },
[259541] = { g = [[sod]], k = [[companion]], o = 0, c = [[any]], w = [[Throughout the expedition]], h = { [[Neera hears the voice of the wild mage Adoy and wants a potion to silence it.]], [[She needs a seven-legged spider's leg, a planetar's feather, belladonna, a potion of perception and turnip juice.]], [[Hand her the ingredients, then rest so she can brew; or seek the Fountain of Nepenthe in the deep caverns.]] }, s = [[With Neera in the party, she asks for five ingredients to drive Adoy from her mind: a leg from a seven-legged spider, a feather from a planetar's wing, belladonna, a potion of perception and turnip juice.
Gather them as you travel. The bard Voghiln can tell you the spider lives in a cavern to the east; the turnip juice is sold by a very dedicated gnome.
Once she has all of them (or if you let her try without them), make camp and she brews the potion. A complete potion frees her; an incomplete one works but costs her, more or less heavily.
She may instead decide to free Adoy for good: then look for the portal to the Fugue Plane, the Fountain of Nepenthe, in the caverns beneath Dragonspear, and help her release his spirit.]] },
[259567] = { g = [[sod]], k = [[side]], o = 0, c = [[Prologue]], w = [[Korlasz's tomb]], h = { [[This quest has no journal entries of its own in this game.]], [[It most likely covers the remnants of Sarevok's followers in Korlasz's tomb at the start of the campaign.]], [[Explore every room of the tomb with the Flaming Fist before leaving.]] }, s = [[The game's quest table lists this quest without any journal entry, so there is nothing specific to track.
It most likely belongs to the opening of Siege of Dragonspear: with the Flaming Fist, you clear the tomb where Korlasz and the last followers of Sarevok are hiding.
Explore the whole dungeon, deal with Korlasz, and take care of the side matters found there (the rescued girl, the mummy Fanegonorom) before returning to the surface.]] },
[259568] = { g = [[sod]], k = [[side]], o = 0, c = [[Prologue]], w = [[Korlasz's tomb]], h = { [[Not everyone held prisoner in Korlasz's tomb is what they appear to be.]], [[A young girl seems to be Korlasz's captive; Imoen may also seem to appear somewhere she should not be.]], [[Doppelgangers are in the tomb: watch for odd details and be ready to fight.]] }, s = [[In Korlasz's tomb you find a young girl claiming to be a child tortured by Korlasz.
You can free her and let the Flaming Fist guide her to the surface, or see through the act: she is a doppelganger, and you fight and kill it.
Later a fake Imoen appears, sometimes working with Korlasz. It reveals itself as a doppelganger and you must destroy it. If you freed the girl earlier, you are left wondering whether she was a real child at all.]] },
[259569] = { g = [[sod]], k = [[side]], o = 0, c = [[Prologue]], w = [[Korlasz's tomb]], h = { [[Something ancient sleeps in a chamber of Korlasz's tomb and dislikes the noise.]], [[The mummy Fanegonorom wants the intruders gone so it can rest.]], [[Defeat Korlasz, then go back upstairs to the mummy's chamber.]] }, s = [[In Korlasz's tomb you disturb the mummy Fanegonorom. Instead of fighting, it orders you to deal with Korlasz, whose noisy followers keep it from sleeping.
Continue through the tomb and defeat Korlasz on the lower level.
Then return to the mummy's chamber on the upper level and speak to it again. It rewards you for the service and the quest ends.]] },
[259615] = { g = [[sod]], k = [[main]], o = 20, c = [[Coast Way Crossing]], w = [[Coast Way Crossing]], h = { [[The expedition's planned road north has been cut.]], [[With the Coast Way bridge destroyed, the Flaming Fist must go around.]], [[Head for Boareskyr Bridge and the fort that guards it, Bridgefort.]] }, s = [[After leaving Baldur's Gate, the expedition camps near Coast Way Crossing. Explore the area, deal with the crusaders there and finish your business with the Flaming Fist officers in camp.
The bridge over the river is blown up, so the army cannot cross there.
The new route leads to Boareskyr Bridge, the place where Bhaal died, guarded by Bridgefort. Travel there when you are ready to continue the main story.]] },
[259618] = { g = [[sod]], k = [[side]], o = 0, c = [[Baldur's Gate]], w = [[Baldur's Gate, Ducal Palace]], h = { [[The gold you carried at the end of your last adventure was put in safekeeping at the palace.]], [[The treasurer Ophyllis works in a small room on the south side of the palace basement.]], [[If he says the gold is lost, meet him outside and follow his lead to the Three Old Kegs.]] }, s = [[Your gold was deposited in the Ducal Palace vault. Go down to the basement and talk to the treasurer Ophyllis in the small room on the south side to get it back. He also places a storage chest in your quarters.
In one branch he admits the gold was lost and promises to repay you outside the palace. He then turns up beaten outside the High Hall: thieves took the money. Their hideout is on the second floor of the Three Old Kegs. They spent it on refugees fleeing Caelar; you can forgive them, kill them, or send them to the Flaming Fist. The gold is gone in every case.
Ophyllis may later offer a golden bust of your head as repayment. If he dies at the hands of crusaders, seek them out to recover your fortune.]] },
[259620] = { g = [[sod]], k = [[side]], o = 0, c = [[Baldur's Gate - Dragonspear Castle]], w = [[Baldur's Gate, then the expedition]], h = { [[Grand Duke Entar Silvershield's daughter Skie wants a private word with you at the palace.]], [[She has secretly joined the Flaming Fist under a false name; decide whether to tell her father.]], [[Keep an eye out for her during the march north, and look for her in Dragonspear Castle after the battle.]] }, s = [[At the Ducal Palace you meet Skie Silvershield, who hints she wants to talk alone. Wait: she visits your room at night and reveals she has joined the Flaming Fist under an assumed name.
Keep her secret or tell Grand Duke Entar Silvershield. Either way she comes along; Entar asks that she be treated as any soldier.
During the expedition, rumors about her identity and her link to Bence Duncan spread through the camps; you can find her at the coalition camp outside Dragonspear Castle.
After the castle falls, Skie, briefly captured by crusaders, is found hiding there. She tells you Caelar went to the vault below the castle, and the Flaming Fist takes charge of her safety.
Her fate is tied to the main story's ending in Baldur's Gate.]] },
[259621] = { g = [[sod]], k = [[main]], o = 19, c = [[Baldur's Gate]], w = [[Baldur's Gate]], h = { [[Before marching north you may gather old friends from your earlier adventures.]], [[Captain Schael Corwin escorts you around the city while you look for companions.]], [[Try the Three Old Kegs, the Elfsong Tavern, the old Iron Throne building and the Flaming Fist headquarters, then return to the palace.]] }, s = [[Captain Schael Corwin accompanies you through Baldur's Gate to recruit companions for the journey to Dragonspear.
Minsc and Dynaheir have rooms at the Three Old Kegs. Garrick, Safana and Coran are at the Elfsong Tavern. Rasaad works at a refugee camp in the old Iron Throne building. Tiax is held at the Flaming Fist headquarters.
Invite whoever you want. When you are done, Corwin advises returning to the Ducal Palace, which moves the story on and ends your time in the city.
Companions you did not take still join the expedition: you will find them at the Flaming Fist camp near Coast Way Crossing.]] },
[259623] = { g = [[sod]], k = [[companion]], o = 0, c = [[any]], w = [[Throughout the expedition]], h = { [[This companion quest has no journal entries of its own in this game.]], [[Captain Schael Corwin of the Flaming Fist can join you from Baldur's Gate onward.]], [[Keep her in the party and talk with her often to learn more about her and her family.]] }, s = [[The game's quest table lists this entry without any journal text, so there are no steps to follow.
Schael Corwin, a Flaming Fist captain, is assigned to you in Baldur's Gate and can travel with you through the whole campaign.
Take her along and answer her when she starts a conversation; her personal story unfolds through those talks during the march north and at the coalition camp.]] },
[259626] = { g = [[sod]], k = [[main]], o = 31, c = [[Baldur's Gate - Epilogue]], w = [[Ducal Palace, Boareskyr Bridge, Baldur's Gate]], h = { [[A hooded stranger keeps appearing wherever you go and seems to know you.]], [[He reveals himself again after your blackout on Boareskyr Bridge and warns you about Caelar.]], [[After the night Skie dies, gather your defense: Duke Belt will hear everyone who met you on the way north.]] }, s = [[A strange hooded man first appears in your quarters at the Ducal Palace. Others mention him asking about you during the journey.
When you black out crossing Boareskyr Bridge, you wake in a burned symbol of Bhaal; he claims to have saved you, says your power could be contained or extracted, and warns that Caelar is not what she seems.
After the campaign, back in Baldur's Gate, you see Skie turn into a monster and wake with blood on your hands, accused of her murder and jailed in the Flaming Fist headquarters.
You learn the hooded man killed Skie. Duke Belt then hears your companions, the coalition commanders and others: your deeds during the expedition weigh on the verdict.]] },
[259645] = { g = [[sod]], k = [[companion]], o = 0, c = [[Dragonspear Castle]], w = [[Crusader camp near Dragonspear Castle]], h = { [[Edwin has his own reasons to fear, and to face, the Shining Lady's crusade.]], [[An old travelling companion of Edwin's, a Red Wizard, now serves among the crusaders.]], [[Find the Red Wizard Vichand in the crusader camp with Edwin in the party, and kill him.]] }, s = [[With Edwin in the party, he eventually explains why he wants to confront Caelar Argent.
In the crusader camp you meet the Red Wizard Vichand, once Edwin's travelling companion and now his bitter enemy. Edwin wants him dead at the first chance.
When the time is right, fight Vichand with Edwin present. Expect a capable spellcaster, so prepare protections. Killing him avenges a fallen comrade of Edwin's and closes the quest; Edwin is as grateful as he ever gets.]] },
[259711] = { g = [[sod]], k = [[main]], o = 21, c = [[Boareskyr Bridge]], w = [[Boareskyr Bridge, Bridgefort]], h = { [[The expedition's new road runs through Boareskyr Bridge, where Bhaal died.]], [[Crossing the bridge will stir something in your blood, in front of your allies.]], [[Secure Bridgefort for the coalition before the army moves on toward Dragonspear.]] }, s = [[The expedition reaches Boareskyr Bridge and Bridgefort, which the crusade threatens.
When you cross the bridge you are struck by a vision of your father Bhaal's death and collapse in front of your allies; rumors about your parentage may cause trouble later. The hooded man appears afterwards.
Help hold Bridgefort against the crusade and explore the region around it. Once the fort is secure, the coalition can continue north to Dragonspear Castle.
The evil alternative, lowering the drawbridge for the crusaders, is covered by the quest Down With the Drawbridge.]] },
[259716] = { g = [[sod]], k = [[companion]], o = 0, c = [[Coast Way Crossing - later]], w = [[Coast Way Crossing, underground dwarf town]], h = { [[Travelling with M'Khiin, keep an eye out for slain goblins near the Coast Way bridge.]], [[Their spirits, called back by M'Khiin, speak of a stash hidden west of the bridge.]], [[Later, in a subterranean dwarf town, a possessed goblin armor awaits; decide whether M'Khiin wears it.]] }, s = [[With M'Khiin in the party, you find four goblin mercenaries recently slain near Coast Way Crossing. M'Khiin calls back their spirits, which reveal a stash of goods hidden west of the Coast Way bridge. Search there to find it.
Later, in the subterranean dwarf town, you find a set of goblin armor possessed by its former owner, Kruntur.
Convince M'Khiin to wear the armor for protection, or let her follow her calling as a spellcaster: she then takes robes and a staff instead.]] },
[259717] = { g = [[sod]], k = [[main]], o = 25, c = [[Dragonspear Castle]], w = [[Dragonspear Castle]], h = { [[The crusade's guards will not let a stranger walk into Dragonspear Castle.]], [[You need one of Caelar's seals; crusader patrols may carry them.]], [[Show the seal to the gate guards, then always play the part of a crusader inside.]] }, s = [[To get into Dragonspear Castle without raising the alarm, you need one of Caelar's seals.
Ambush or deal with a crusader patrol outside the castle and take a seal from them.
Present yourself at the gate and convince the guards to let you in. You can then explore the courtyard, but keep your true name and purpose secret: answer as a crusader in every conversation, or the whole garrison may turn on you.]] },
[259718] = { g = [[sod]], k = [[main]], o = 27, c = [[Dragonspear Castle]], w = [[Dragonspear Castle, coalition camp]], h = { [[Torsin de Lancie has a covert mission for you inside the enemy's stronghold.]], [[Once inside Dragonspear Castle, find the crusade's food and water supplies.]], [[Poison them, flee the castle when Hephernaan arrives, and report to de Lancie.]] }, s = [[At the coalition camp, Torsin de Lancie asks you to sabotage the crusade from inside Dragonspear Castle.
Get into the castle (see Entering Dragonspear Castle) and make your way to the stores. Poison the food supply, the water supply, or both: each one weakens the crusade for the coming battle.
While you continue toward the basement, Hephernaan arrives and your cover is blown. Leave the castle at once before the whole garrison falls on you, and return to de Lancie at the coalition camp to report.]] },
[259722] = { g = [[sod]], k = [[main]], o = 29, c = [[Avernus - Epilogue]], w = [[Avernus, then Baldur's Gate]], h = { [[In Avernus, reach Caelar and stop what Hephernaan has set in motion.]], [[Once the crusade is broken, the expedition returns to Baldur's Gate.]], [[Your troubles are not over at home: the hooded man is waiting.]] }, s = [[In Avernus, fight your way to the basalt tower and confront Hephernaan and the forces of Hell. Your choices toward Caelar decide her fate.
With Hephernaan defeated, the crusade is finished and you return to Baldur's Gate as a hero.
That is when the final part begins: Skie Silvershield dies, you are accused of her murder and imprisoned in the Flaming Fist headquarters. Follow the quests Disturbing Implications and It Wasn't Me to reach the ending.]] },
[259731] = { g = [[sod]], k = [[side]], o = 0, c = [[Avernus]], w = [[Avernus, outside the basalt tower]], h = { [[A devil bars the way into the basalt tower and loves a wager.]], [[Thrix the Profane lets you pass if you win his game; the stake can be a companion or your own soul.]], [[You may also refuse to bet and fight him instead.]] }, s = [[In Avernus, the devil Thrix the Profane guards the entrance to the basalt tower and offers a wager to let you through.
Accept and choose the stake: one of your companions, or your own soul. Answer his challenge carefully. If you win, you pass and nothing is lost.
If you lose, you still get through, but the wagered companion is doomed to be claimed by Thrix some day, or he lays claim to your soul.
Alternatively, refuse to bargain and challenge him: either you destroy him in battle, or he flees, leaving minions to fight you, and swears revenge. Be ready for a hard fight in either case.]] },
[259732] = { g = [[sod]], k = [[main]], o = 28, c = [[Dragonspear Castle - Avernus]], w = [[Dragonspear Castle, basement]], h = { [[The castle is taken, but Caelar is not among the prisoners.]], [[Follow her trail down into the castle's basement and the vault below.]], [[Caelar has gone through a portal to Avernus after Hephernaan: you must follow her into Hell.]] }, s = [[After the battle, Dragonspear Castle is secured by the coalition, but Caelar has escaped.
Search the castle; Skie, if found, reports that Caelar headed for the vault in the basement while the crusaders fled through the tunnels.
Go down through the basement levels. There you learn that Caelar followed Hephernaan through a portal to Avernus, the first layer of the Nine Hells, and that her plan has gone badly wrong.
Prepare your party (rest, restock, pick your companions) and step through the portal to pursue her.]] },
[259734] = { g = [[sod]], k = [[main]], o = 30, c = [[Epilogue]], w = [[Baldur's Gate, Flaming Fist headquarters and sewers]], h = { [[Jailed for Skie's murder, you must either escape or be released by the Council of Four.]], [[If a stranger offers a way out, grab your gear from the central chamber and follow him to the basement.]], [[The secret tunnel leads to the sewers; your only way out is over the waterfall.]] }, s = [[Accused of murdering Skie, you are held in the Flaming Fist headquarters.
If your past deeds convince most of the Council of Four, you are released but exiled: collect your belongings from the headquarters, then leave the city under escort. Skie's father swears vengeance.
Otherwise a stranger offers escape. Take your equipment from the table in the central chamber and follow him to the secret tunnel in the basement. In the sewers, the Flaming Fist corners you; you may have to fight Corwin or Bence Duncan and their men.
Run to the falls and go over the waterfall to escape. Afterwards you realize it was not Imoen who freed you: the hooded man set it all up.]] },
[260258] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear Castle]], w = [[Coalition camp and crusader camp]], h = { [[A gnome fence in the coalition camp pays well for souvenirs from the enemy's camp.]], [[Waizahb wants five items: a commander's signet ring, a battle standard, a holy symbol, a token of faith and Caelar's annotated map.]], [[Bring a replacement for the ruby-eyed symbol, scare Commander Dreon with talk of honest work, and hurry before the battle.]] }, s = [[Waizahb, a fence at the coalition siege camp, wants five items from the crusader camp.
Signet ring: Commander Dreon is hard to approach; win his trust and suggest honest work, and he hands it over.
Battle standard: in a chest in the crusader camp.
Holy symbol: Tristian, cleric of the Red Knight, carries one with ruby eyes. Its loss would be noticed, so bring a replacement to swap it.
Token of faith: some new recruits carry homemade tokens of devotion; get one.
Map: Caelar's annotated map hangs in the camp.
Bring the items to Waizahb as you find them; all five earn the full reward. The quest closes when the battle starts, so finish early.]] },
[261101] = { g = [[sod]], k = [[companion]], o = 0, c = [[Coast Way Crossing - Dragonspear Castle]], w = [[Bridgefort, coalition camp, crusader camp]], h = { [[Glint the gnome sneaked into the caravan to learn what became of his relatives in crusade territory.]], [[His uncle the cobbler is in Bridgefort, his cousin Pritchard annoys the Daggerford militia, and another cousin sews for the crusade.]], [[Ask Glint what to do about Pritchard: beating him up, driving him off or sparing him all close the matter.]] }, s = [[Glint Gardnersonson, a gnome stowaway in the Flaming Fist caravan, joins you to find his relatives.
In Bridgefort, his uncle Hoach Randymonk, a cobbler, can repair the boot and a half found near Coast Way Bridge; return a day later. The Boots of Speed fail badly, so ask him for a refund.
At the coalition camp, Pritchard Gardnersonson troubles the Daggerford militia and General Stonehand; two militiamen offer potions to solve it. Talk to Glint: he asks you to beat Pritchard up to save his life. You can beat him, drive him away (he leaves Glint a family dagger), fake his death, or leave him alone. He may also die.
In the crusader camp you find Glint's cousin Rhonda, forced to work as a seamstress.]] },
[261301] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear Castle]], w = [[Crusader camp near Dragonspear Castle]], h = { [[Two crusaders, Nan and Pedro, have a drunk comrade who cannot do his duty.]], [[Commander Dreon expects the morning report from Morale Officer Deneld, plus some wine.]], [[Wear a crusader uniform before asking Deneld for the report, and fill a flask with wine.]] }, s = [[In the crusader camp, Nan and Pedro explain that their comrade Sallo is too drunk to bring the morning report to Commander Dreon.
Find a flask and fill it with wine.
Get the report from Morale Officer Deneld. He refuses unless you wear a crusader uniform, so find one or come up with a convincing excuse.
Take the wine and the papers to Commander Dreon and persuade him to accept the delivery.
Return to Nan and Pedro: they reward you with some potions.]] },
[261432] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear Castle]], w = [[Coalition camp and nearby forest]], h = { [[The healer Dosia in the coalition camp is worried about a spreading sickness.]], [[Examine the three patients, then look into the camp's rats with a druid or ranger.]], [[Possible cures lie in the forest: blackthorn bark, or the help of a hermit druid who wants a basilisk's claw.]] }, s = [[A sickness spreads through the coalition camp. Talk to the healer Dosia, then examine the patients Xerra, Yestimell and Zidrand (Yestimell attacks you). Companions skilled in healing or nature help. Report back to Dosia.
Lead: the camp's rats. A wererat claims them as his pack and attacks; once he is dead, a druid or ranger can talk to a rat.
Cure options: find a blackthorn tree in the forest near camp and take its moldy bark, or find the hermit druid Onoroth there; he wants you to kill a sick basilisk and bring its claw, then gives you a cure.
Bring the cure to Dosia to heal the soldiers. If she will not pay you can keep it. You can also advise her to isolate, or kill, the infected.]] },
[261449] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear Castle]], w = [[Coalition camp]], h = { [[Warden Twoedged wants you to understand how the coalition's soldiers feel about war.]], [[Talk to the healer Dosia, Vigilant Halasan and Quartermaster Belegarm.]], [[Then find Twoedged near the command tents and share what you learned.]] }, s = [[In the coalition camp, Warden Simonetta Twoedged asks you to talk to people in camp about their experiences of war.
Speak to Dosia (she survived the attack on Daggerford as a child and believes fate brought her here), Vigilant Halasan (she wants to bring her soldiers home alive, though a childhood friend, Tristian, serves the crusade) and Quartermaster Belegarm (a history lover eager for glory).
Return to Twoedged near the command tents and discuss what you heard to close the quest. You can also give up on the exercise, which ends it without the full conversation.]] },
[261502] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear Castle]], w = [[Coalition camp, Dead Man's Pass]], h = { [[The dwarf Helvdar lost his lucky charm and cannot fight without one.]], [[A new pair of boots made from a bear's hide might do; Quartermaster Belegarm can make them.]], [[Hunt a bear in Dead Man's Pass, bring the skin to Belegarm, and come back a day later.]] }, s = [[Helvdar the dwarf has lost his lucky charm and needs a new one.
Go to Dead Man's Pass and hunt down a bear. Take its skin to Quartermaster Belegarm, who grumbles but agrees to make boots; they are ready one day later.
Collect the boots and give them to Helvdar to complete the quest.
If you try to pass off ordinary boots as lucky ones, or keep the new boots for yourself, Helvdar spreads word that you are a boot thief, which hurts your standing in camp.]] },
[261529] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear Castle]], w = [[Coalition camp]], h = { [[General Stonehand of the Daggerford forces suspects a thieves' guild is growing in camp.]], [[Start with the gnome fence Waizahb: convince her to arrange a meeting, or follow her.]], [[The guild meets at the north end of camp; confront its leader Rhynwis, then report to Stonehand.]] }, s = [[In the coalition camp, General Stonehand asks you to uncover the thieves' guild taking root there.
Question the gnome Waizahb, the guild's fence. Persuade her to set up a meeting, or, if she sees through you, follow her as she heads north.
At the north edge of camp, meet the guild's representatives and their leader, Rhynwis. Threaten her: she either agrees to help the camp when the time comes, or flees and leaves the camp alone.
Return to General Stonehand and report. She is grateful and starts to see you as a good influence on the camp.]] },
[261592] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear Castle]], w = [[Dragonspear region camps]], h = { [[A gloomy man named Jospil asks to be left alone for a moment.]], [[Come back and talk with him about the crusade and the Shining Lady.]], [[Choose encouraging replies to lift his spirits; the better his mood, the better his gift.]] }, s = [[A depressed man, Jospil, asks you to give him a moment before talking.
Speak to him again. He tells you about the crusade and Caelar Argent and how bleak he finds the odds.
Try to cheer him up with encouraging, understanding replies. If you turn his attitude around completely, he gives you a shield and a quarterstaff. If you only lift his mood a little, he gives you a quarterstaff. If you fail, you only learn something about the crusade.]] },
[261597] = { g = [[sod]], k = [[side]], o = 0, c = [[Baldur's Gate]], w = [[Baldur's Gate, Three Old Kegs]], h = { [[Two ship crews are about to come to blows in the Three Old Kegs.]], [[The innkeeper Nantrin Bellowglym trusts you to handle it; you can also talk to the two officers.]], [[Side with Lucilla of the Amnian Delight or Autinn of Chiondar's Son, then ask for a reward.]] }, s = [[In the Three Old Kegs in Baldur's Gate, a bar fight is brewing between two ship crews.
Talk to the innkeeper Nantrin Bellowglym, who recognizes you and asks you to step in, or speak directly to the two leaders.
You can defuse the situation peacefully, or take a side: Lucilla, navigator of the Amnian Delight, or Autinn, first mate of Chiondar's Son.
If you sided with one of them, talk to them again afterwards: Lucilla gives you an enchanted cudgel, Autinn an enchanted scimitar.]] },
[261604] = { g = [[sod]], k = [[side]], o = 0, c = [[Baldur's Gate]], w = [[Baldur's Gate, Three Old Kegs]], h = { [[Three nobles have rented a single room upstairs at the Three Old Kegs; it is not a party.]], [[Find proof of their plot against the city, or win their confidence by pretending to agree.]], [[Fetch Captain Corwin at the main door, then get the plotters to repeat their plans while her men listen.]] }, s = [[Upstairs in the Three Old Kegs, three nobles share a room and plot against Baldur's Gate.
Talk to them and pretend to share their views, or find the seditious letter one of them carries.
Go to Captain Corwin, who waits at the main door downstairs. She posts a Flaming Fist team in the hallway; return and trick the nobles into discussing their plans again. If you succeed, they are arrested. If they do not incriminate themselves, Corwin has to let them go.
Other options: extort money from the traitors, or kill them yourself.]] },
[261611] = { g = [[sod]], k = [[side]], o = 0, c = [[Baldur's Gate]], w = [[Baldur's Gate, Three Old Kegs]], h = { [[Barging into the wrong room at the Three Old Kegs can be profitable.]], [[The vain noblewoman Delenda orders you out, guarded by her bodyguard.]], [[Talk her out of her necklace with clever words, scare them off, or fight the bodyguard.]] }, s = [[In a guest room of the Three Old Kegs you walk in on Delenda, a vain noblewoman, who angrily orders you out.
Use cunning replies to trick her into giving you a valuable necklace.
Alternatively, frighten her and her bodyguard off: they flee and leave the room empty. Or fight: killing the bodyguard gets you his wakizashi.]] },
[261612] = { g = [[sod]], k = [[side]], o = 0, c = [[Baldur's Gate - Avernus]], w = [[Elfsong Tavern, then the whole journey]], h = { [[An eccentric elf at the Elfsong Tavern hands out very strange glasses.]], [[Zaviak's Spectacles of Spectacle reveal extraplanar beings and can pull up to three into this world.]], [[Choose wisely where to use the charges: some visitors reward you, others attack.]] }, s = [[Talk to Zaviak, the eccentric elf at the Elfsong Tavern, to get the Spectacles of Spectacle. Wear them to see extraplanar creatures; you can pull three into the world.
Known sightings: a fire elemental in the Elfsong (it attacks); a gauth near Coast Way Crossing (kill it or send it toward the crusader camp); a tiefling, Raeanndra, fighting an earth elemental (pull her for a magic ring); the djinni Nazramu; the rakshasa Vidyadhar (solve his riddle for a Modron Heart); a shadow in a bugbear cave (turn it on them); the imprisoned lich Zhadroth in Kanaglym (an Endless Watcher comes after him); a deva or a demon in Avernus (the demon gives a sword).
The quest ends when the spectacles run out of charges.]] },
[261617] = { g = [[sod]], k = [[side]], o = 0, c = [[Baldur's Gate]], w = [[Baldur's Gate, Elfsong Tavern and Ducal Palace]], h = { [[A halfling working at the Elfsong Tavern has run out of a special wine.]], [[Irina wants a barrel of ruby wine, known for its sharp, spicy smell, from the Ducal Palace cellar.]], [[Sneak a barrel out of the palace cellar, or offer her a convincing substitute.]] }, s = [[At the Elfsong Tavern, the halfling Irina has run out of ruby wine and asks you to pilfer a barrel from the cellar of the Ducal Palace.
Go down to the palace cellar and look for the barrel with a sharp, spicy smell. Bring it back to Irina for a reward.
Instead, you can provide her with a substitute, which also earns a reward.
A druid can try a magical solution, but it may go wrong and turn Irina into a squirrel; once changed back, she loses interest in the wine.]] },
[261618] = { g = [[sod]], k = [[side]], o = 0, c = [[any]], w = [[Unknown (where you meet Ammon)]], h = { [[A woman named Ammon is stuck on a potion for lack of cobalt moss.]], [[Suggest a substitute ingredient, or bring her cobalt moss if you find some.]], [[Her potion is part of a plan to enter Candlekeep; as someone raised there, you may sign her letter or refuse.]] }, s = [[Ammon needs cobalt moss to finish a potion.
Suggest a substitute: she tries it at once; talk to her again shortly after. Or come back if you find cobalt moss.
Once the potion is done, she rewards you.
You learn the potion is part of her plan to get into Candlekeep. If you tell her you grew up there, she asks you to sign a letter explaining her goal. Signing or refusing does not change much: the letter is unlikely to get her past the gates.]] },
[261625] = { g = [[sod]], k = [[side]], o = 0, c = [[Baldur's Gate]], w = [[Baldur's Gate, Ducal Palace basement]], h = { [[An old enemy you captured at the start of the campaign has broken loose in the Ducal Palace.]], [[Korlasz wants revenge on you and on the city.]], [[Go down to the palace basement, prepared for a mage fight, and finish her.]] }, s = [[Korlasz, Sarevok's servant and a former Iron Throne lieutenant, escapes captivity and roams the Ducal Palace, bent on revenge for her capture and Sarevok's death.
Go down to the palace basement and find her. Prepare against a spellcaster (spell protections, ways to break her defenses) before you engage.
This time there is no sparing her: defeat and kill Korlasz to close the quest.]] },
[261628] = { g = [[sod]], k = [[side]], o = 0, c = [[Baldur's Gate]], w = [[Baldur's Gate, Ducal Palace]], h = { [[A Flaming Fist officer got himself locked in one of the palace cells.]], [[Find a way to open the cell and let him out.]], [[Be ready for a fight: the prisoner may not be what he seems.]] }, s = [[In the Ducal Palace, a Flaming Fist officer has been accidentally locked in a cell.
Find a way to open it, by key or by picking the lock, and free him.
In one outcome he is a real, unlucky officer and simply goes on his way. In another, the "officer" is a doppelganger that attacks once freed: kill it to close the quest.]] },
[261630] = { g = [[sod]], k = [[side]], o = 0, c = [[Prologue]], w = [[Baldur's Gate, Ducal Palace / Iron Throne building]], h = { [[One of the prisoners in the Ducal Palace dungeons is not who he claims to be.]], [[The false Flaming Fist officer is a doppelganger who promises a reward for its freedom.]], [[Free it, then wait a few hours and go down to the Iron Throne building basement.]] }, s = [[In the dungeons under the Ducal Palace, talk to the prisoner dressed as a Flaming Fist officer. It is a doppelganger and asks you to let it out, promising a reward.
Agree and free it. It tells you to meet it in the basement of the Iron Throne building in three hours.
Wait, then go to the Iron Throne building (now crowded with refugees) and down to its basement. The doppelganger keeps its word and hands over a cache of gold, weapons and potions.
Afterwards you can let it leave in peace, or attack and kill it so no shapechanger stays loose in the city.]] },
[261636] = { g = [[sod]], k = [[side]], o = 0, c = [[Prologue]], w = [[Baldur's Gate]], h = { [[This quest has no journal entries in the game; it may never appear in normal play.]], [[If it does, look around the streets of Baldur's Gate during the prologue of Siege of Dragonspear.]] }, s = [[The game defines this quest title but writes no journal entry for it, so it is most likely unused or cut content.
Nothing needs to be done for it. If it ever shows up in your journal, it belongs to the Baldur's Gate part of Siege of Dragonspear: talk to the townsfolk and refugees in the city streets before you leave with the coalition army.]] },
[261650] = { g = [[sod]], k = [[side]], o = 0, c = [[Prologue]], w = [[Baldur's Gate, outside the Flaming Fist jail]], h = { [[Walk past the Flaming Fist jail and listen for trouble.]], [[Some mercenaries are bullying a group of young nobles who broke curfew.]], [[Step in on the youths' side.]] }, s = [[Outside the Flaming Fist jail in Baldur's Gate you come across several mercenaries harassing some noble children.
Talk to them and side with the youths. Telling the mercenaries off is enough to end the quest; be ready in case they turn hostile.
If you do not intervene, nothing more happens and the quest stays unfinished.]] },
[261653] = { g = [[sod]], k = [[side]], o = 0, c = [[Prologue]], w = [[Baldur's Gate, around the Iron Throne building]], h = { [[A refugee in the shantytown around the old Iron Throne building tells an odd story about a lost cat.]], [[Byzon's real problem is a Flaming Fist officer, Riggs, who extorts the refugees.]], [[Get the stolen gold back from Riggs, by words or by force, and give it to Byzon.]] }, s = [[In the shantytown around the former Iron Throne building, watch Byzon talking with a Flaming Fist mercenary about his "lost cat". Talk to Byzon afterwards: the cat story is a cover, and he admits that officer Riggs is extorting money from the refugees.
Find Riggs nearby and confront him. With Captain Corwin in the party she can help pressure him into handing over the gold; otherwise he may refuse and fight, and you take the gold from his body.
Return the gold to Byzon, who shares it out among the victims. You can also keep it for yourself, the selfish ending.]] },
[261663] = { g = [[sod]], k = [[side]], o = 0, c = [[Prologue]], w = [[Baldur's Gate, near the Ducal Palace]], h = { [[A homeowner near the Ducal Palace takes everything refugees own in exchange for a bed.]], [[Garachen will open his house if you bring provisions from the Elfsong Tavern.]], [[Or tell the Flaming Fist headquarters what the refugee Perren said about lodgers leaving.]] }, s = [[Talk to Garachen outside his large house near the Ducal Palace, and to the refugee Perren nearby. Garachen says he can only take in more people if someone supplies food.
Kind route: go to the Elfsong Tavern and arrange a week of provisions, then bring them back to Garachen. He keeps helping the refugees.
Ruthless route: go to the Flaming Fist headquarters and use Perren's remark to accuse Garachen of selling refugees into slavery. He is arrested, and the refugees can use his house freely. Talk to the refugees outside the house afterwards to close the quest.]] },
[261669] = { g = [[sod]], k = [[side]], o = 0, c = [[Prologue]], w = [[Baldur's Gate, south of the Ducal Palace / Sorcerous Sundries]], h = { [[A merchant south of the Ducal Palace needs someone to carry her day's earnings.]], [[Teera's moneylender works across the street from Sorcerous Sundries; watch your pockets on the way.]], [[If the purse is stolen, pay the moneylender yourself or confess to Teera.]] }, s = [[Talk to Teera at her stall south of the Ducal Palace and accept to take her purse to her moneylender, across the street from Sorcerous Sundries.
On the way a pickpocket targets you. If you notice her, or charm her into giving the gold back, carry on. If she gets away with it, you can either give the moneylender your own gold to cover the sum, or go back and tell Teera.
Once the purse is deposited, return to Teera's stall outside the palace. She is pleased if the money arrived, and upset if you lost it.]] },
[261676] = { g = [[sod]], k = [[side]], o = 0, c = [[Prologue]], w = [[Baldur's Gate, outside Sorcerous Sundries]], h = { [[A Flaming Fist officer outside Sorcerous Sundries is holding a group of refugees.]], [[Officer Vida needs reinforcements from the Flaming Fist headquarters.]], [[At headquarters you decide whether the refugees get leniency or a harsh punishment.]] }, s = [[Talk to Officer Vida outside Sorcerous Sundries: she has detained some refugees who caused trouble and needs more men.
Go to the Flaming Fist headquarters and report her request. While there you can plead for the refugees to be shown leniency, or back Vida and ask for strict punishment, or simply pass on the message.
Return to Vida to tell her reinforcements are coming and close the quest.]] },
[261681] = { g = [[sod]], k = [[side]], o = 0, c = [[Prologue]], w = [[Baldur's Gate, Three Old Kegs]], h = { [[The town crier outside the Three Old Kegs has shouted himself dry.]], [[Ask Katheera, inside the inn, to send Robel a drink.]], [[Persuade her to send it right away, then tell Robel.]] }, s = [[Talk to Robel, the crier outside the Three Old Kegs; he is parched.
Go inside and speak to Katheera. She is busy but agrees to send him a drink later; with the right words you can convince her to send it immediately.
Go back out and give Robel her answer to finish this small errand.]] },
[261686] = { g = [[sod]], k = [[side]], o = 0, c = [[Prologue]], w = [[Baldur's Gate, alley behind the Three Old Kegs]], h = { [[A woman behind the Three Old Kegs is collecting money for a burial.]], [[Look closer at the body in Aileen's cart and ask who he really was.]], [[Keep her secret, make her pay for it, or report her at the Flaming Fist headquarters.]] }, s = [[In the alley behind the Three Old Kegs, Aileen says she needs 15 gold to bury her cousin. You can simply give her the 15 gp and end it there.
If you question her further, she admits the dead man in the cart is her violent, drunken husband, killed by accident during a fight. Then choose:
- promise to keep her secret;
- keep it only in exchange for all the money she collected;
- go to the Flaming Fist headquarters and report the killing to an officer inside.]] },
[261693] = { g = [[sod]], k = [[side]], o = 0, c = [[Prologue]], w = [[Baldur's Gate, Sorcerous Sundries]], h = { [[Sorcerous Sundries is swamped with customers; its owner could use a hand.]], [[Halbazzer Drin wants a case of empty potion bottles from the upper floor.]], [[Upstairs you will find more than bottles: deal with the robbers, then tell Drin.]] }, s = [[Enter Sorcerous Sundries and talk to Halbazzer Drin on the ground floor. He asks you to fetch a case of empty potion bottles from upstairs.
Go up: thieves are busy robbing the shop's stock. Defeat them and take the bottles.
Go back down and give Drin the bottles. Tell him about the robbery and he rewards you; you can also keep quiet about it, in which case you get no extra reward.]] },
[261696] = { g = [[sod]], k = [[side]], o = 0, c = [[Prologue]], w = [[Baldur's Gate, Iron Throne building]], h = { [[Among the refugees at the Iron Throne building, a man named Lon is accused of theft.]], [[The stolen amulet is a holy symbol of Selune, and Lon reacts badly when pushed.]], [[Expose Lon, kill what he becomes, then talk to Berta.]] }, s = [[At the Iron Throne building, the refugees ask you to judge Lon, accused of stealing an amulet.
If you declare the evidence too weak, Lon goes free and the quest ends there.
If you press him, it turns out he took Berta's holy symbol of Selune; once exposed, he changes into a werewolf. Kill him (silver or magic weapons help).
Then talk to Berta: grateful, she gives you her holy symbol as a reward.]] },
[261707] = { g = [[sod]], k = [[side]], o = 0, c = [[Coast Way]], w = [[Coast Way, burned inn]], h = { [[A halfling sits in the ashes of his inn along the Coast Way.]], [[Takos lost a shield, a mirror and a cloak; two are close to the ruins.]], [[The undead hunters Isabella and Ikros have the shield.]] }, s = [[Talk to Takos in the ruins of his burned inn on the Coast Way. Rowdy soldiers burned it and three heirlooms disappeared: a shield, a mirror and a cloak.
Search the ruins of the inn to find the hand mirror. The cloak is locked in a battered chest near the ruins.
The polished shield is with Isabella and Ikros, the undead hunters camped in the same area; you get it by dealing with them (see their own quest).
Bring all three back to Takos for his thanks and a reward. If you keep the items instead, he attacks you.]] },
[261708] = { g = [[sod]], k = [[side]], o = 0, c = [[Coast Way]], w = [[Coast Way, hunters' camp and vampire cave]], h = { [[Two undead hunters camped near the Coast Way want help with a vampire, but only after dark.]], [[Tsolak flees as mist when beaten; his lair lies past a trapped path to the west.]], [[Stake his body in the cave, or listen to his side and accept his offer instead.]] }, s = [[Talk to Isabella and Ikros at their camp. They ask you to return after dark to fight the vampire Tsolak.
Come back at night and fight him with the hunters. When beaten he turns to mist and escapes; talk to Isabella.
Follow the trapped path to the west (have a thief disarm the traps) and find his cave. Drive a stake into his body to destroy him, then return to the hunters' camp for your reward, including the polished shield Takos wants.
Alternative: when Tsolak explains himself, side with him against the hunters. Later a messenger brings his reward.
You can also find and stake the vampire before meeting the hunters, then visit them for a reward.]] },
[261718] = { g = [[sod]], k = [[side]], o = 0, c = [[Coast Way]], w = [[Coast Way]], h = { [[Old standing stones dot the land around the Coast Way; one hums when someone sings to it.]], [[There are six menhirs in the area, and each must be sung to until it gives a pleasing tone.]], [[With all six active, a minstrel's ghost wakes: decide whether to reunite him with his love or destroy them.]] }, s = [[Explore the Coast Way area and click on each ancient menhir. Choose to sing to it until it gives off a pleasing tone; a failed try just means trying again.
Find and activate all six stones; the journal counts them for you.
When the sixth sings, the ghost of Crommus, a long-dead minstrel, appears. Talk to him: he wants to be with his beloved Carline.
Peaceful ending: free his spirit so he can join her.
Otherwise Carline's ghost appears, driven mad by her years alone, and you must destroy her; you can also destroy both spirits to send them to their rest.]] },
[261720] = { g = [[sod]], k = [[side]], o = 0, c = [[Coast Way]], w = [[Refugee camp and western clearing]], h = { [[Refugees are vanishing from the camp, and people blame a newly arrived elf named Teleria.]], [[Meet Teleria in the clearing to the west: the missing refugees are now statues in her collection.]], [[Stop her and restore the statues for Herod, or help her finish her art and buy her golem.]] }, s = [[At the refugee camp, hear about the missing people and talk to Teleria. She agrees to meet you in a clearing to the west.
In the clearing you learn she turns people into statues for her art collection.
Good path: fight and stop her. Restore the petrified refugees if you can (stone to flesh magic), then report to Herod at the camp. Accept his payment or refuse it.
Evil path: lure a soldier and a nobleman to her clearing so she can complete the collection, then return for a reward.
You can also buy a golem from her; it waits at the Flaming Fist camp and fights for you at Dragonspear Castle.]] },
[261737] = { g = [[sod]], k = [[side]], o = 0, c = [[Bridgefort]], w = [[Bridgefort / crusader camp]], h = { [[Talking to Bridgefort's wizard Wynan Hess leaves the fort open to a magical attack.]], [[A spellstone is slowly killing everyone in the fort; the scroll that made it is in the crusader camp.]], [[A Red Wizard in the camp carries the scroll; bring it to Wynan Hess fast, and be ready for a wraith.]] }, s = [[In Bridgefort, speaking with the wizard Wynan Hess distracts him, and a crusade attack strikes the fort: an enchanted spellstone starts draining everyone inside, you included.
Go into the crusader camp and find the Red Wizard of Thay, Vichand. Kill him and take his scroll.
Hurry back to Wynan Hess with it. Neutralizing the stone releases a dark wraith set as a trap; destroy it and Bridgefort is safe.
If you never talk to Hess, he deals with the stone himself during the attack on the crusade. If you wait too long, the crusade takes Bridgefort and the stone becomes their problem.]] },
[261740] = { g = [[sod]], k = [[side]], o = 0, c = [[Bridgefort]], w = [[Bridgefort, courtyard]], h = { [[Two mages in the Bridgefort courtyard are not coping well with the siege.]], [[Thirrim warns that Elandro's terror could draw something evil, especially at night.]], [[Talk to Elandro after dark and calm him, or be ready to fight what his fear creates.]] }, s = [[In the Bridgefort courtyard, meet the mages Elandro and Thirrim. Elandro is terrified of the crusade; Thirrim asks you to speak with him at night, when his fear grows worse.
Return after dark and talk to Elandro. Reassuring answers calm him and the danger passes.
If you fail or mock him, the fort's magic and his fear spawn a feyr, a monster made of fear. Kill it before it slaughters the people around it.]] },
[261747] = { g = [[sod]], k = [[side]], o = 0, c = [[Bridgefort]], w = [[Bridgefort]], h = { [[This quest has no journal entries in the game; it may never appear in normal play.]], [[Food is scarce among the refugees and soldiers of Siege of Dragonspear; listen to the hungry ones.]] }, s = [[The game defines this quest title but writes no journal entry for it, so it is most likely unused or cut content.
Nothing needs to be done. If it does appear, it is tied to the food shortage during the siege: talk to the hungry people in Bridgefort and see what they ask for.]] },
[261764] = { g = [[sod]], k = [[side]], o = 0, c = [[Bridgefort]], w = [[Bridgefort, courtyard]], h = { [[A hungry half-elf teamster in the Bridgefort courtyard worries about her sick horses.]], [[Senderin wants the cleric Frair Tajik to heal them, or you can try to cure them yourself.]], [[Once the horses are cured, talk to Senderin again; her plans for them may surprise you.]] }, s = [[Talk to Senderin and her son in the Bridgefort courtyard. Their horses have fallen sick.
Either find Frair Tajik, the cleric in the fort, and convince him to heal the horses, or cure them yourself (a curing spell from a party priest should do).
Return to Senderin. She and her son reveal they mean to butcher the horses for meat, since they are starving. She still rewards you with a fine helm.]] },
[261770] = { g = [[sod]], k = [[side]], o = 0, c = [[any]], w = [[Spider cave]], h = { [[After you clear the spider cave, something big is heard moving inside.]], [[Go back in and follow the noise.]] }, s = [[While in the spider cave, you hear a loud noise: something large has entered the caverns.
Explore the cave to find its source. It is a giant rhino beetle; defeat it and the quest is complete.
It hits hard and is well armored, so rest and buff before you go looking for it.]] },
[261774] = { g = [[sod]], k = [[side]], o = 0, c = [[Coalition camp]], w = [[Coalition camp (Flaming Fist camp)]], h = { [[Lieutenant Otilda distrusts a band of half-orc mercenaries in the coalition camp.]], [[She wants you to pick a fight with Rend's unit, but Kava will share their story if you bring her ale.]], [[Ale can be found in the crusader camp; then decide whether the half-orcs stay, leave or die.]] }, s = [[Lieutenant Otilda asks you to pick a fight with the half-orc irregulars so they get banished from camp.
Talk to them first. Kava wants a mug of ale before she talks: find one in the crusader camp and bring it back (refusing her jokes makes her clam up). She explains that she and Farrl came back for hidden loot, and that Rend, a former crusader, truly wants to kill crusaders.
Then choose:
- let them stay for Rend's knowledge; Kava gives a small reward, and you tell Otilda they are no threat;
- challenge and beat them in a fight to drive them off (Otilda rewards you), or lose the fight;
- kill them all.
Report back to Otilda in every case.]] },
[261777] = { g = [[sod]], k = [[side]], o = 0, c = [[Bridgefort]], w = [[Bridgefort, temple and nearby woods]], h = { [[Junia, a priest of Lathander in Bridgefort, needs help carrying the dead to her temple altar.]], [[A dead soldier's brother, Tharantis, wants her necklace; a missing healer in the woods is part of the mystery.]], [[The necklace and the bodies lead back to Junia: confront her in the temple.]] }, s = [[Junia asks you to pick up the bodies of fallen soldiers and carry them to the altar in the temple room. One of them, Kendra, has a brother in the fort: find Tharantis and tell him. He asks for the chain she always wore; ask Junia about it.
The trail leads to Ymori, a healer missing in the woods around Bridgefort. You find his mutilated body in a ritual site, and undead rise when you examine it. Kendra's necklace turns up on a murdered corpse.
Give the necklace to Tharantis (or sell it to him; he may attack), then confront Junia. She claims Ymori was a cultist of Velsharoon and she used his body to strengthen the troops: accept her story, or fight her and her undead servants.
Finally tell Tharantis what happened to his sister.]] },
[261778] = { g = [[sod]], k = [[companion]], o = 0, c = [[any]], w = [[With Khalid in the party]], h = { [[Keep Khalid in the party: he has an anniversary coming and wants to make Jaheira a gift.]], [[He first needs silk from a giant spider.]], [[Then he needs an aquamarine; agree a fair deal with him for it.]] }, s = [[With Khalid in the party, he tells you their wedding anniversary is near and asks for help making Jaheira a necklace.
First bring him giant spider silk: kill a giant spider and loot the silk, then give it to him.
Next he wants an aquamarine. Find or buy one and give it to Khalid. If you demand payment, he may refuse to pay for it; he can also simply drop the idea to focus on the war.
Once he has both, he finishes the necklace and gives it to Jaheira, which closes the quest.]] },
[261853] = { g = [[sod]], k = [[side]], o = 0, c = [[Coalition camp]], w = [[Coalition camp]], h = { [[Vigilant Halasan has a unit of green recruits from Daggerford.]], [[Talk to each of the six soldiers and drill them one by one.]], [[Good advice for each recruit earns Halasan's approval and a better reward.]] }, s = [[Talk to Vigilant Halasan in the coalition camp. Her Daggerford unit is not up to standard and she asks you to train it.
Speak to each of the six privates: Morlis, Danine, Hester, Garrold, Taield and Clovista. Each conversation is a short drill; pick sensible, encouraging answers that fit the soldier's problem.
When all six are trained, report to Halasan. If you did well she is pleased and rewards you; poor answers leave her unimpressed.]] },
[261863] = { g = [[sod]], k = [[companion]], o = 0, c = [[Coalition camp]], w = [[Coalition camp]], h = { [[Safana picked a pocket in camp and found a notebook full of secrets: there is a spy among the coalition.]], [[Trace the three other stolen items: an odd potion bottle, a gilded candle and a page of runes.]], [[All leads point to Malden Col; gather proof, confront him, then report to Marshal Nederlok.]] }, s = [[With Safana in the party, she shows you what she stole, including a notebook proving a spy is in camp. Question people about the other items:
- the potion bottle: ask Quartermaster Belegarm, then Helvdar the dwarf at the northern barricade. He lost a potion at cards to Malden Col.
- the candle: Mizhena, the priest of Tempus, says it was stolen and suspects Col.
- the runes: retired Warden Simonetta Twoedged, near the commanders' tents, lent her book to Col.
Some witnesses refuse to help if you offend them; follow another lead.
Confront Malden Col with the evidence: he confesses and is jailed. Without proof he denies it, and you can kill him anyway.
Report to Marshal Nederlok. Killing an innocent witness as the "traitor" is possible but wrong.]] },
[261867] = { g = [[sod]], k = [[side]], o = 0, c = [[Coalition camp]], w = [[Coalition camp, triage area]], h = { [[A sick priest of Ilmater in the triage area refuses any healing.]], [[Another follower of Ilmater, Dosia, might change Hyreth's mind.]], [[Once Hyreth agrees, find a priest in the triage area to heal him.]] }, s = [[In the triage area, talk to Hyreth, a sick priest of Ilmater who refuses healing because of his faith.
Find Dosia, another follower of Ilmater, and ask her to speak with him. If she agrees, return to Hyreth with her; she can convince him. She may also refuse, saying he has the right to his beliefs.
When Hyreth accepts help, look for a priest working in the triage area and bring them to heal him, which completes the quest.
You can also leave him to his convictions.]] },
[261872] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear]], w = [[Crusader courtyard near Dragonspear]], h = { [[Two crusader recruits pray before a broken icon of Tempus in a corner of the courtyard.]], [[The two missing shards lie in the rubble to the north, or Morale Officer Deneld knows of them.]], [[A priest of Tempus must bless the shards; Mizhena among your allies can do it.]] }, s = [[In the northwest corner of the courtyard, talk to the recruits Kjarvan and Qing, praying at an icon of Tempus missing two pieces.
Search the rubble to the north for the fragments, or ask Morale Officer Deneld. Get both shards.
There is no priest of Tempus among the crusaders: take the shards to Mizhena, the priest of Tempus in the coalition, and have her bless them.
Bring the consecrated shards back to the recruits, then place them on the stone icon yourself.
Tempus answers with a challenge. Decline to end it safely, or accept and win a hard fight for the god's favor.]] },
[261880] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear]], w = [[Near the Underground River / its caverns]], h = { [[Two druids are trapped in a snare of living roots; cut them free.]], [[Jamven and Chorster want you to destroy the dark druid circle of Ferrusk in the underground river caverns.]], [[Plant their enchanted seed in the roots of the underground tree, or side with Ferrusk.]] }, s = [[Cut the druids Jamven and Chorster free from the animated roots. They explain that the dark druid Ferrusk drove them out of the underground river caverns and give you an enchanted seed.
Go down into the caverns and find Ferrusk's circle, built around the roots of an underground tree. Plant the seed in the roots to destroy the circle, then return to the druids.
Alternatives:
- lie to them that the circle is destroyed;
- agree to Ferrusk's offer, go back up, kill Jamven and Chorster and bring him their heads.
If the druids learn you did not destroy the circle, they attack you.]] },
[261881] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear]], w = [[Underground River caverns, myconid tree-tower]], h = { [[A dying myconid in the caverns asks you to look into a corpse inside a tree-tower.]], [[The body lies in the northern part of the tree.]], [[Expect a myconid elder; you cannot understand it, and it will fight.]] }, s = [[In the underground caverns, talk to the dying myconid near the great tree-tower. It asks you to investigate a dead body in the northern part of the tree.
Enter the tree and head north to the body. A myconid elder confronts you; without a way to understand it, the talk fails and it attacks.
Kill the elder to end the quest. Its bloom-sac is useful for the dark druid Ferrusk in the Slime Sickness quest.]] },
[261883] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear]], w = [[Ogre camp, near the caverns]], h = { [[A band of ogre brigands lost its leader Slug to the crusade, and his "widow" Murs wants the job.]], [[Two ogre contenders must be beaten to settle who leads.]], [[Fight them for yourself, or as Murs's champion to make her chief and an ally.]] }, s = [[Talk to Murs at the ogre brigands' camp. The crusade drove the band out of the caverns and caged their leader Slug; Murs wants to take control.
Accept the leadership challenge and fight the two ogre contenders. Either fight in your own name and become leader of the band, or fight as Murs's champion so she becomes chief and helps you.
If you instead slaughter the ogres, the survivors will not help you later.
Murs also tells you about the ghosts and the way into the caverns under Dragonspear (see The Lost and Accessing the Warrens).]] },
[261889] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear]], w = [[Caverns beneath Dragonspear]], h = { [[Murs speaks of ghosts haunting a cavern northwest of the old ogre settlement.]], [[The lost spirits need their remains taken to the Fugue Plane; an ettin ghost wants his club.]], [[Carry the remains until you find a portal to the Fugue Plane later on.]] }, s = [[In the caverns northwest of the old ogre settlement, meet a group of ghosts trapped between worlds. Take their remains with you.
An ettin ghost among them lingers because of his lost club. Find the club in the caverns and give it to him: he moves on and leaves you a reward, an embarrassing one.
Keep the other remains. When you reach a portal to the Fugue Plane, bring them there to lay the spirits to rest and finish the quest.]] },
[261890] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear]], w = [[Underground River caverns]], h = { [[A druid ruling the caverns warns you away from his domain.]], [[This is Ferrusk, the dark druid; the druids Jamven and Chorster want his circle gone.]] }, s = [[This entry only records your meeting with the dark druid Ferrusk, who guards a cavern in the underground river region and lets only some people pass.
Its outcome is handled in other quests: destroy his circle for Jamven and Chorster (The Good Druids), or deal with him for a cure (Slime Sickness).]] },
[261891] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear]], w = [[Caverns beneath Dragonspear Castle, Warrens door]], h = { [[Murs knows a way into the caverns right under Dragonspear, far northwest of the ogre camp.]], [[Guard captain Turin Brassbreaker watches the door to the Warrens.]], [[Bluff her with Caelar's crest, lure her away with an explosion in the cookfire, or fight.]] }, s = [[Following Murs's directions, go northwest of the old ogre settlement to the caverns directly beneath Dragonspear Castle.
At the door to the Warrens stands guard captain Turin Brassbreaker with her crusaders. Ways past:
- show Caelar's crest and bluff your way through without bloodshed;
- crusaders nearby tell of a potion of firebreath that blew up their campfire: toss a potion of firebreath, or something else explosive, into the cookfire to draw Turin from her post;
- attack her and her guards.
Once inside, avoid needless fights, or the whole castle may come down on you.]] },
[261892] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear]], w = [[Underground River caverns / ogre camp]], h = { [[The ogre chief Slug and two of his fellows sit in a crusade cage in the caverns.]], [[Free them; Slug may reveal an ogre treasure cache near a pool in the northern tunnels.]], [[After you collect the cache, visit Slug back at the ogre camp on the surface.]] }, s = [[In the underground river caverns, find Slug and two other ogres caged by the crusade. Find a way to open the cage and free them.
If he trusts you, Slug tells you about a hiding hole in a cavern wall near a pool of water in the northern part of the tunnels. Go there and take the cache. If he does not trust non-ogres, he leaves without helping.
Return to the ogre camp above ground. If Murs is alive, the reunited pair thank you. If Murs is dead, Slug turns violent and you have to fight him.]] },
[261896] = { g = [[sod]], k = [[side]], o = 0, c = [[any]], w = [[Unknown]], h = { [[This quest has no journal entries in the game; it may never appear in normal play.]], [[The title hints at someone who does not want to be bothered at their door.]] }, s = [[The game defines this quest title but writes no journal entry for it, so it is most likely unused or cut content from Siege of Dragonspear.
Nothing needs to be done for it, and it cannot block your progress.]] },
[261898] = { g = [[sod]], k = [[companion]], o = 0, c = [[Dragonspear]], w = [[Near the entrance to the Underground River]], h = { [[A Rashemi witch and her berserker bodyguard want to meet Minsc and Dynaheir.]], [[Come back with both of them alive in the party; Julann is thinking of joining Caelar.]], [[Find proof of Hephernaan's corruption in the caverns and show it to Julann.]] }, s = [[Near the entrance to the underground river, meet the wychlaran Julann and her berserker Rigah. They want to speak with Minsc and Dynaheir: return with both alive and in the party.
They reveal that Julann leans toward joining the crusade. You must convince her otherwise.
In the caverns, look for evidence of Hephernaan's corruption and bring it to Julann. With Rigah's help she may be convinced; Rigah then gives you his sword.
If she refuses the truth, Rigah may help you slay her, or both may leave toward Dragonspear Castle, or you kill them both. You can also simply kill them from the start.]] },
[261910] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear]], w = [[Underground River, crusader depot]], h = { [[Ladle, a gnome at the crusader depot, has a job for you.]], [[Carry his sacks of grain to the empty crates by the river bank.]], [[Then do what he asks next, even if it seems pointless.]] }, s = [[Talk to Ladle at the crusader depot by the underground river. He asks you to move the sacks of grain next to him into the empty crates on the river bank.
Pick up the sacks and put them in the crates, then report back. He now wants the grain moved back where it was.
Do it and talk to him again. He admits it was only busywork, the kind that keeps bored crusaders from fighting each other. No real reward, just a chuckle.]] },
[261914] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear]], w = [[Underground River]], h = { [[A crusade wizard by the underground river is binding water elementals for the battle.]], [[You can stop Strunk by killing him or by killing the elementals.]], [[Siding with the elementals against him pleases the nereid of the river.]] }, s = [[By the underground river, find Strunk, a crusade wizard binding water elementals to use at Dragonspear Castle.
Best outcome: when Strunk loses control of the elementals, side with them and help them kill him. A nereid living in the river rewards you.
If you kill the elementals instead, both Strunk and the nereid attack you.
Simply killing Strunk outright also frees the elementals and ends his plan.]] },
[261915] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear]], w = [[Caverns beneath Dragonspear]], h = { [[Injured crusaders in the caverns are poisoned by a fungus, and someone who knows these caves could help.]], [[The dark druid Ferrusk has a cure, for 2000 gold or a myconid elder's bloom-sac.]], [[Bring the cure to the crusaders' leader before it is too late.]] }, s = [[In the caverns beneath Dragonspear, find a group of crusaders poisoned by an underground fungus. They are slowly turning into slimes.
Seek out the dark druid Ferrusk. He will trade a cure for 2000 gold, or for the bloom-sac of a myconid elder (see The Myconid Tower).
Bring the cure back quickly and give it to the crusaders' leader. If you take too long, they all become slimes.
If you demand payment and they refuse, and you keep the cure, the sickness consumes them too.]] },
[261917] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear]], w = [[Caverns beneath Dragonspear]], h = { [[A drow search party led by Shapur clashes with the crusade in the tunnels.]], [[Two young drow lovers have run away; find them somewhere in the caverns.]], [[Send them home, fake their deaths with their house insignias, or hand them over to the crusaders.]] }, s = [[In the tunnels you meet Shapur and her drow fighting crusaders. Talk to her: two adolescent drow have run away, and she is searching for them.
Explore the caverns to find the pair, star-crossed lovers. Then choose:
- convince them to go home; they meet you where the drow face the crusaders, and Shapur thanks you and withdraws;
- agree to fake their deaths: take their house insignias to Shapur, and her people leave for the Underdark (she may fight instead);
- take them to the crusaders, who either escort them to the surface or keep them as prisoners;
- kill them, or kill Shapur's band first and tell the youths they are free.
If an ankheg kills the pair, report their deaths to Shapur.]] },
[261935] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear Castle]], w = [[Dragonspear Castle, basement]], h = { [[Someone is raising the dead in the depths beneath Dragonspear Castle.]], [[A gathering of dark magicians works its rituals in the castle's lower levels.]], [[The ghost of a dragon haunts the same depths and can help you against the cabal.]] }, s = [[Explore the levels beneath Dragonspear Castle. A cabal of dark magicians is animating corpses there to swell the crusade's ranks.
Prepare for a hard fight against several spellcasters backed by undead: protection from evil, undead-turning and spell disruption help.
If you have met the ghost of the dragon Halatathlaer down there, it can take part in the battle on your side.
Kill all the magicians to close the quest. This weakens the crusade.]] },
[261940] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear Castle]], w = [[Dragonspear Castle]], h = { [[The dragon ghost Halatathlaer left a message for its old friend Daeros.]], [[Daeros Dragonspear died long ago, but his spirit may still linger near the castle he ruled.]], [[When you meet Daeros's ghost, tell him Halatathlaer waits for him in the Fugue Plane.]] }, s = [[This quest starts when the ghost of the dragon Halatathlaer departs (through the Fountain of Nepenthe, or simply leaving this world) and asks you to tell its friend Daeros where it went.
Keep exploring Dragonspear Castle and the places tied to it. The ghost of Daeros Dragonspear, the castle's long-dead lord, can be found there.
Talk to him and pass on Halatathlaer's message: it waits for him in the Fugue Plane.
His spirit is set free and leaves to join the dragon, closing the quest.]] },
[261945] = { g = [[sod]], k = [[side]], o = 0, c = [[Underground River]], w = [[Underground River, caverns beneath Dragonspear]], h = { [[Two sahuagin block the caverns of the underground river beneath Dragonspear.]], [[You do not have to fight them: talk first.]], [[A good story, or enough intimidation, gets you past them without bloodshed.]] }, s = [[In the underground river caverns beneath Dragonspear, a pair of sahuagin, Gurgle and Floss, stop the crusaders from passing.
Talk to them. Three ways out:
- Tell them a story they like: they let you through.
- Frighten them enough and they flee.
- Attack: they are only two and the fight is short.
Any of these closes the quest and opens the way onward through the caverns.]] },
[261963] = { g = [[sod]], k = [[side]], o = 0, c = [[Epilogue]], w = [[Baldur's Gate, sewers beneath the Flaming Fist headquarters]], h = { [[During your escape through the sewers under the Flaming Fist headquarters, check the bodies you pass.]], [[A dead escapee carries a note and a key to a hidden cache.]], [[The cache lies beside an underground pool fed by the city sewers.]] }, s = [[At the end of the campaign, while escaping through the sewers beneath the Flaming Fist headquarters in Baldur's Gate, search the corpse of a failed escapee.
Take his note and key and read the note.
Explore the sewer tunnels until you reach an underground pool fed by the city sewers. The hidden cache is there: open it with the key and take the loot.
The items are welcome, since you start the escape poorly equipped.]] },
[262483] = { g = [[sod]], k = [[main]], o = 22, c = [[Bridgefort]], w = [[Bridgefort]], h = { [[Once inside Bridgefort, find out what strength the defenders really have.]], [[Two people matter: the defenders' spokesman Wynan Hess and the smith Jegg Hillcarver.]], [[After talking to both, report back to Khalid.]] }, s = [[Inside the besieged Bridgefort, talk to Wynan Hess: the defenders are few, mostly merchants and travelers, and need to coordinate with the Flaming Fist to attack the crusade.
Talk to the smith, Jegg Hillcarver (either order works). The fort's supplies would strengthen the crusade at Dragonspear; if you negotiate a surrender, she will make sure most of them are destroyed.
When you have spoken to both, return to Khalid and tell him what you learned. This feeds into how you end the Bridgefort siege.]] },
[264446] = { g = [[sod]], k = [[main]], o = 23, c = [[Bridgefort]], w = [[Bridgefort, crusader camp and ruined temple to the east]], h = { [[The crusader camp's gate guard will not admit new recruits until they prove themselves.]], [[A missing crusader patrol, including the recruiter's nephew Keherrem, was last seen near a ruined temple to the east.]], [[Free the caged patrol with the key someone on that level carries, or pull the lever and bring back their leader's badge.]] }, s = [[Talk to the guard at the crusader camp gate near Bridgefort. To bluff your way in, you must find a missing patrol, likely in a ruined temple to the east.
Enter the temple, now held by Cyricists, and fight down to the caged crusaders.
- Mercy: take the cage key from a cultist on that level, free them, and return to the camp to take the credit.
- Ruthless: pull the wall lever; spikes kill them. Take their leader's badge and tell the camp the Cyricists did it.
Either way you gain access to the crusader camp, from where you can work to lift the siege. If you already have another way in, the prisoners' fate makes no difference.]] },
[264473] = { g = [[sod]], k = [[side]], o = 0, c = [[Coast Way Crossing]], w = [[Coast Way Crossing, dwarven dig site]], h = { [[Near Coast Way Crossing, a dwarf is fighting zombies; help him and hear his story.]], [[Inside the hidden dig, help the clerics of Dumathoin, look for Gurn Coldhearth and spare the giant Semahl.]], [[Coldhearth has become a lich: destroy his phylactery in a hidden room before fighting him, or accept his bargain.]] }, s = [[Near Coast Way Crossing, save Daran Highhammer from zombies. He asks you to check on the dwarven clerics who hired him inside their secret dig.
In the dig, help the clerics fight the undead. Their leader Auchlin Deepvein asks you to find his friend Gurn Coldhearth. In a remote corner, rescue the giant Semahl and send him to the survivors: his word later backs up your report.
Deeper, in a buried fortress, you see Coldhearth become a lich. Do not fight him yet: report to Deepvein, who gives you the weapon Secret Revealed.
Find the phylactery in a hidden room off the transformation chamber, destroy it, then kill the lich. The dwarves may join you at Dragonspear Castle.
Evil option: the lich offers a big reward for the five Amulets of the Keeper worn by the clerics. Bring all five, never fewer.]] },
[264506] = { g = [[sod]], k = [[side]], o = 0, c = [[Prologue / Bridgefort]], w = [[Korlasz family tomb, then the temple of Cyric near Bridgefort]], h = { [[Sarevok left research notes in the Korlasz family tomb; read them carefully.]], [[They point to a secret room in an old temple of Bhaal, which you will visit later in your travels.]], [[The ruined temple of Bhaal is now a temple of Cyric: use the marks in the order 3, 1, 4.]] }, s = [[In the Korlasz family tomb (prologue), find Sarevok's old notes about the Bhaal prophecy. They mention a secret room in an old temple of Bhaal and the marks of the Lord of Shadows: 3, 1 and 4.
Later, near Bridgefort, you explore the ruined temple of Bhaal now used by Cyricists (the same dungeon as the missing patrol).
Look for the marked spots inside and activate them in the order 3, 1, 4 from Sarevok's notes. The secret room opens; take its contents.]] },
[264981] = { g = [[sod]], k = [[main]], o = 24, c = [[Bridgefort]], w = [[Bridgefort]], h = { [[Bridgefort is sealed while the crusade besieges it; you need a special way in.]], [[A wardstone grants passage into the fort.]], [[Once you hold the wardstone, use it at the fort to get inside and meet the defenders.]] }, s = [[During the siege of Bridgefort, the fort cannot be entered normally.
Obtain the Bridgefort wardstone, then use it to pass into the fort.
Once inside, the quest ends and you can speak with the defenders: this leads straight into The Desperate Defenders (Wynan Hess and the smith Jegg Hillcarver).]] },
[264982] = { g = [[sod]], k = [[side]], o = 0, c = [[Bridgefort]], w = [[Ruined temple of Bhaal (temple of Cyric), near Bridgefort]], h = { [[A blind prisoner in the ruined temple of Bhaal claims she was once its high priestess.]], [[Something has gone very wrong in the temple; the Cyricist high priestess Akanna has shut herself in the ritual chambers.]], [[Akanna's mind is not her own: the true master waits in the reliquary.]] }, s = [[In the ruined temple of Bhaal near Bridgefort, now held by Cyricists, meet Madele, a caged former high priestess of Bhaal. Read her notes: she hears a voice promising Akanna's downfall. You may free her if you find a way to open her cell, or leave her there.
Creatures have attacked the temple: proceed with care and find a way into the ritual chambers where the high priestess Akanna is locked.
Akanna admits a voice made her let monsters in. Go on to the reliquary and defeat the mind flayer behind it all and its tentacled minions. Expect mind attacks: protect against charm and stun.]] },
[266700] = { g = [[sod]], k = [[main]], o = 18, c = [[Prologue]], w = [[Baldur's Gate, Ducal Palace]], h = { [[Assassins have struck at the Ducal Palace; drive them off.]], [[The killers were sent by Caelar Argent, whose crusade threatens the lands north of the Winding Water.]], [[Talk to the dukes and get ready to march north with the coalition.]] }, s = [[After clearing the Korlasz family tomb, you rest at the Ducal Palace in Baldur's Gate. At night, assassins attack.
Fight your way through the palace with your companions and kill the assassins. This is a hard fight at this level: keep healing potions ready.
Once the palace is secure, the dukes reveal the assassins came from Caelar Argent's crusade.
Talk to the dukes and Flaming Fist leaders, prepare your party and supplies, then leave the city with the coalition to march north.]] },
[266743] = { g = [[sod]], k = [[main]], o = 26, c = [[Dragonspear Castle]], w = [[Dragonspear Castle]], h = { [[Explore Dragonspear Castle as far as you can, down to the basement.]], [[Securing the underground river route and the basement gives the coalition an edge.]], [[When you return, the commanders are gone: Caelar has asked for a parley.]] }, s = [[Break into Dragonspear Castle with the coalition, through the courtyard or the underground river caverns.
Explore the castle and its basement, clearing crusaders and the horrors below. Side quests here include the looters (Spoils of War), the dark magicians (The Cabal) and the prisoners in the courtyard.
When you come back, the commanders have left: Caelar Argent has requested a parley. Prepare well before going, as the story soon moves on past the point of no return.]] },
[266957] = { g = [[sod]], k = [[side]], o = 0, c = [[Prologue]], w = [[Korlasz family tomb]], h = { [[A restless spirit haunts a robbed sarcophagus, searching for its stolen staff.]], [[The thieves left the staff behind in the tomb, broken in two: the shaft and the headpiece lie in different rooms.]], [[Put both pieces back in the spirit's sarcophagus on that floor.]] }, s = [[In the tomb, thieves robbed a sarcophagus of a plain, non-magical staff, and its owner's spirit now haunts it.
Search the rooms on that floor: one holds the broken staff, another its headpiece. You can join them into the restored staff.
Return to the haunted sarcophagus and place the staff inside. The spirit rests in peace and the quest ends.]] },
[267432] = { g = [[sod]], k = [[main]], o = 17, c = [[Prologue - coalition camp]], w = [[Baldur's Gate, then the coalition camp near Dragonspear]], h = { [[As you leave Baldur's Gate, a crowd gathers: what you say shapes how they see you.]], [[At the coalition camp before Dragonspear Castle, the crusade will attack: hold the camp.]], [[Once the attack is repelled, check in with Marshal Nederlok at the camp entrance.]] }, s = [[Leaving Baldur's Gate, a crowd confronts you about your shared lineage with Sarevok. A reassuring speech wins them over; a harsher attitude leaves them suspicious. Neither blocks the story.
Later, at the coalition's siege camp before Dragonspear Castle, the crusade launches an assault. Defend the camp with the coalition troops until the attackers are driven off.
Then go to Marshal Nederlok at the camp entrance to continue toward the real battle at Dragonspear Castle.]] },
[269214] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear Castle]], w = [[Dragonspear Castle, interior]], h = { [[Some coalition soldiers are filling their pockets with treasure found in the castle.]], [[Order them to stop, or report them to a Flaming Fist officer on the same level.]], [[You can also keep quiet in exchange for a share of the loot.]] }, s = [[Inside Dragonspear Castle, you come upon coalition soldiers looting treasure. Talk to them:
- Order them to leave the valuables: they may comply grudgingly.
- If they refuse, find a Flaming Fist officer on that level and report them; he deals with it.
- Or offer to keep their secret for a cut: they give you a valuable ring.
Any of these closes the quest.]] },
[269686] = { g = [[sod]], k = [[side]], o = 0, c = [[Coalition camp]], w = [[Coalition camp, outside Dragonspear Castle]], h = { [[Marshal Nederlok cannot find Skie Silvershield anywhere in the coalition camp.]], [[Bored with camp life, Skie went to scout the enemy on her own, toward Dragonspear Castle.]], [[Save her from the crusader mercenaries, then tell Nederlok she is safe.]] }, s = [[In the coalition camp, Marshal Nederlok tells you Skie Silvershield is missing.
She was last seen heading toward Dragonspear Castle. Search the area between the camp and the castle.
You find her under attack by crusader mercenaries: kill them quickly before she falls.
Talk to Skie: she was scouting out of boredom and promises to go back to camp.
Return to Nederlok and report. He puts her to filling sandbags, and the quest ends.]] },
[271143] = { g = [[sod]], k = [[side]], o = 0, c = [[Coalition camp]], w = [[Coalition camp, outside Dragonspear Castle]], h = { [[Two Daggerford militiamen in the coalition camp complain about their gnome officer.]], [[Find Pritchard Gardnersonson and deal with him, one way or another.]], [[Telling Pritchard what his men really think brings General Stonehand into the matter.]] }, s = [[In the coalition camp, two Daggerford militiamen tell you their commanding officer, the gnome Pritchard Gardnersonson, is a problem.
Seek out Pritchard and talk to him. Telling him how his troops truly feel leads General Stonehand of the Daggerford militia to handle him personally. Luck can also solve the matter for you.
Once Pritchard is no longer a nuisance, return to the two militiamen. They thank you with several potions.]] },
[271314] = { g = [[sod]], k = [[side]], o = 0, c = [[Coalition camp]], w = [[Coalition camp and nearby woods]], h = { [[Mizhena, a priest of Tempus in the coalition camp, lost a keepsake fighting crusaders.]], [[Look for signs of a struggle in the woods near the camp.]], [[Bring the amulet back to Mizhena; she will then trust you with a bigger request.]] }, s = [[Talk to Mizhena, a priest of Tempus in the coalition camp. She lost an amulet of sentimental value during a fight with crusaders.
Search the woods near the camp for the site of the struggle and pick up the amulet (you may already have found it).
Return it to Mizhena. She is grateful and, now trusting you, asks for help finding her father, which starts Mizhena's Father.]] },
[271319] = { g = [[sod]], k = [[side]], o = 0, c = [[Dragonspear Castle]], w = [[Coalition camp, then Dragonspear Castle courtyard]], h = { [[Mizhena's father was captured when his band of soldiers attacked the castle.]], [[The crusade keeps its prisoners in the courtyard of Dragonspear Castle.]], [[Free him along with the other prisoners, then bring the news back to Mizhena.]] }, s = [[After you return her amulet, Mizhena asks you to look for her father among the crusade's prisoners.
Storm the courtyard of Dragonspear Castle and find the captives. Free her father along with the other prisoners.
Return to Mizhena with the good news: she is relieved and goes to find him.
Other outcomes: if you killed him, you can tell her and she leaves to search for his body. If Mizhena has died, her father mourns her when you free him.]] },
}
